const HSK1_DATA = {"lessons":[{"id":1,"title_cn":"AI小语，你好！","title_pinyin":"AI Xiǎoyǔ, nǐ hǎo!","title_vn":"Chào AI Tiểu Ngữ!","goals":["Có thể nghe hiểu và sử dụng các cách diễn đạt lịch sự để chào hỏi, cảm ơn và tạm biệt.","Hiểu lễ nghi giao tiếp của người Trung Quốc, có thể nghe hiểu và sử dụng đại từ nhân xưng ngôi thứ hai kính ngữ \"您\"."],"vocab":[{"hanzi":"你好","pinyin":"nǐ hǎo","pos":"","vn":"xin chào","examples":[{"cn":"你好,我是王老师。","pinyin":"Nǐ hǎo, wǒ shì Wáng lǎoshī.","vn":"Xin chào, tôi là cô Vương."},{"cn":"老师,你好!","pinyin":"Lǎoshī, nǐ hǎo!","vn":"Chào thầy/cô!"},{"cn":"你好吗?","pinyin":"Nǐ hǎo ma?","vn":"Bạn khỏe không?"}]},{"hanzi":"王老师","pinyin":"Wáng lǎoshī","pos":"danh từ riêng","vn":"cô Vương","examples":[{"cn":"王老师,您好!","pinyin":"Wáng lǎoshī, nín hǎo!","vn":"Chào cô Vương!"},{"cn":"这是王老师。","pinyin":"Zhè shì Wáng lǎoshī.","vn":"Đây là cô Vương."},{"cn":"王老师是我们的老师。","pinyin":"Wáng lǎoshī shì wǒmen de lǎoshī.","vn":"Cô Vương là giáo viên của chúng tôi."}]},{"hanzi":"大家","pinyin":"dàjiā","pos":"đt.","vn":"mọi người","examples":[{"cn":"大家好!","pinyin":"Dàjiā hǎo!","vn":"Xin chào mọi người!"},{"cn":"大家都是学生。","pinyin":"Dàjiā dōu shì xuésheng.","vn":"Mọi người đều là học sinh."},{"cn":"谢谢大家!","pinyin":"Xièxie dàjiā!","vn":"Cảm ơn mọi người!"}]},{"hanzi":"好","pinyin":"hǎo","pos":"tt.","vn":"tốt; khỏe","examples":[{"cn":"你好吗?我很好。","pinyin":"Nǐ hǎo ma? Wǒ hěn hǎo.","vn":"Bạn khỏe không? Tôi khỏe."},{"cn":"今天天气很好。","pinyin":"Jīntiān tiānqì hěn hǎo.","vn":"Hôm nay thời tiết tốt."},{"cn":"这个很好。","pinyin":"Zhège hěn hǎo.","vn":"Cái này tốt."}]},{"hanzi":"学生","pinyin":"xuésheng","pos":"dt.","vn":"học sinh","examples":[{"cn":"我是学生。","pinyin":"Wǒ shì xuésheng.","vn":"Tôi là học sinh."},{"cn":"他们是学生。","pinyin":"Tāmen shì xuésheng.","vn":"Họ là học sinh."},{"cn":"她是好学生。","pinyin":"Tā shì hǎo xuésheng.","vn":"Cô ấy là học sinh giỏi."}]},{"hanzi":"们","pinyin":"men","pos":"htố.","vn":"hậu tố đặt sau đại từ nhân xưng hoặc danh từ để biểu thị số nhiều","examples":[{"cn":"我们是学生。","pinyin":"Wǒmen shì xuésheng.","vn":"Chúng tôi là học sinh."},{"cn":"你们好!","pinyin":"Nǐmen hǎo!","vn":"Chào các bạn!"},{"cn":"老师们很忙。","pinyin":"Lǎoshīmen hěn máng.","vn":"Các thầy cô rất bận."}]},{"hanzi":"老师","pinyin":"lǎoshī","pos":"dt.","vn":"giáo viên, thầy/cô","examples":[{"cn":"他是老师。","pinyin":"Tā shì lǎoshī.","vn":"Anh ấy là giáo viên."},{"cn":"老师,再见!","pinyin":"Lǎoshī, zàijiàn!","vn":"Tạm biệt thầy/cô!"},{"cn":"我的老师很好。","pinyin":"Wǒ de lǎoshī hěn hǎo.","vn":"Giáo viên của tôi rất tốt."}]},{"hanzi":"您","pinyin":"nín","pos":"đt.","vn":"ngài, ông/bà (kính ngữ)","examples":[{"cn":"您好!","pinyin":"Nín hǎo!","vn":"Xin chào ạ!"},{"cn":"您是老师吗?","pinyin":"Nín shì lǎoshī ma?","vn":"Ông/bà là giáo viên phải không?"},{"cn":"谢谢您!","pinyin":"Xièxie nín!","vn":"Cảm ơn ông/bà!"}]},{"hanzi":"你们","pinyin":"nǐmen","pos":"đt.","vn":"các bạn (số nhiều)","examples":[{"cn":"你们好吗?","pinyin":"Nǐmen hǎo ma?","vn":"Các bạn khỏe không?"},{"cn":"你们是同学吗?","pinyin":"Nǐmen shì tóngxué ma?","vn":"Các bạn là bạn học phải không?"},{"cn":"你们是学生。","pinyin":"Nǐmen shì xuésheng.","vn":"Các bạn là học sinh."}]},{"hanzi":"谢谢","pinyin":"xièxie","pos":"dgt.","vn":"cảm ơn","examples":[{"cn":"谢谢你!","pinyin":"Xièxie nǐ!","vn":"Cảm ơn bạn!"},{"cn":"谢谢老师!","pinyin":"Xièxie lǎoshī!","vn":"Cảm ơn thầy/cô!"},{"cn":"谢谢大家!","pinyin":"Xièxie dàjiā!","vn":"Cảm ơn mọi người!"}]},{"hanzi":"不客气","pinyin":"bú kèqi","pos":"","vn":"không có gì","examples":[{"cn":"谢谢!不客气!","pinyin":"Xièxie! Bú kèqi!","vn":"Cảm ơn! Không có gì!"},{"cn":"不客气,再见!","pinyin":"Bú kèqi, zàijiàn!","vn":"Không có gì, tạm biệt!"},{"cn":"不客气,这是我的工作。","pinyin":"Bú kèqi, zhè shì wǒ de gōngzuò.","vn":"Không có gì, đây là công việc của tôi."}]},{"hanzi":"同学","pinyin":"tóngxué","pos":"dt.","vn":"bạn học","examples":[{"cn":"他是我的同学。","pinyin":"Tā shì wǒ de tóngxué.","vn":"Anh ấy là bạn học của tôi."},{"cn":"同学,你好!","pinyin":"Tóngxué, nǐ hǎo!","vn":"Chào bạn học!"},{"cn":"我们是同学。","pinyin":"Wǒmen shì tóngxué.","vn":"Chúng tôi là bạn học."}]},{"hanzi":"再见","pinyin":"zàijiàn","pos":"dgt.","vn":"tạm biệt","examples":[{"cn":"老师,再见!","pinyin":"Lǎoshī, zàijiàn!","vn":"Tạm biệt thầy/cô!"},{"cn":"再见,明天见!","pinyin":"Zàijiàn, míngtiān jiàn!","vn":"Tạm biệt, hẹn mai gặp lại!"},{"cn":"大家再见!","pinyin":"Dàjiā zàijiàn!","vn":"Tạm biệt mọi người!"}]}],"grammar":[],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一飞","cn":"AI小语，你好！","pinyin":"AI Xiǎoyǔ, nǐ hǎo!"},{"speaker":"小语","cn":"王老师，你好！","pinyin":"Wáng lǎoshī, nǐ hǎo!"}],"translation_vn":"Vương Nhất Phi: Chào AI Tiểu Ngữ!\nTiểu Ngữ: Chào cô Vương!","audio_dialogue":"1-1.mp3","audio_vocab":"1-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一飞","cn":"大家好！","pinyin":"Dàjiā hǎo!"},{"speaker":"白家月/安妮/陈天中","cn":"老师，您好！","pinyin":"Lǎoshī, nín hǎo!"},{"speaker":"小语","cn":"你们好！","pinyin":"Nǐmen hǎo!"},{"speaker":"白家月/安妮/陈天中","cn":"你好，小语！","pinyin":"Nǐ hǎo, Xiǎoyǔ!"}],"translation_vn":"Vương Nhất Phi: Chào cả lớp!\nBạch Gia Nguyệt/Annie/Trần Thiên Trung: Chào cô ạ!\nTiểu Ngữ: Chào tất cả mọi người!\nBạch Gia Nguyệt/Annie/Trần Thiên Trung: Chào Tiểu Ngữ!","audio_dialogue":"1-3.mp3","audio_vocab":"1-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"白家月/安妮/陈天中","cn":"谢谢！","pinyin":"Xièxie!"},{"speaker":"小语","cn":"不客气！","pinyin":"Bú kèqi!"},{"speaker":"王一飞","cn":"同学们，再见！","pinyin":"Tóngxuémen, zàijiàn!"},{"speaker":"白家月/安妮/陈天中","cn":"老师，再见！","pinyin":"Lǎoshī, zàijiàn!"}],"translation_vn":"Bạch Gia Nguyệt/Annie/Trần Thiên Trung: Cảm ơn cô!\nTiểu Ngữ: Không có gì!\nVương Nhất Phi: Tạm biệt các em!\nBạch Gia Nguyệt/Annie/Trần Thiên Trung: Tạm biệt cô!","audio_dialogue":"1-5.mp3","audio_vocab":"1-6.mp3"}]},{"id":2,"title_cn":"我叫李文","title_pinyin":"Wǒ jiào Lǐ Wén","title_vn":"Tôi tên là Lý Văn","goals":["Có thể nghe hiểu và sử dụng tên tiếng Trung để tự giới thiệu bản thân.","Có thể nghe hiểu và sử dụng ngôn ngữ xin lỗi, dùng \"对不起\" để xin lỗi và \"没关系\" để đáp lại.","Nắm được trật tự từ cơ bản trong tiếng Hán.","Hiểu được cấu tạo của tên người Trung Quốc."],"vocab":[{"hanzi":"请问","pinyin":"qǐngwèn","pos":"dgt.","vn":"xin hỏi, làm phiền hỏi","examples":[{"cn":"请问,您叫什么名字?","pinyin":"Qǐngwèn, nín jiào shénme míngzi?","vn":"Xin hỏi, ông/bà tên là gì?"},{"cn":"请问,这是什么?","pinyin":"Qǐngwèn, zhè shì shénme?","vn":"Xin hỏi, đây là cái gì?"},{"cn":"请问,老师在吗?","pinyin":"Qǐngwèn, lǎoshī zài ma?","vn":"Xin hỏi, thầy/cô có ở đây không?"}]},{"hanzi":"你","pinyin":"nǐ","pos":"đt.","vn":"bạn, anh/chị (số ít)","examples":[{"cn":"你叫什么名字?","pinyin":"Nǐ jiào shénme míngzi?","vn":"Bạn tên là gì?"},{"cn":"你是学生吗?","pinyin":"Nǐ shì xuésheng ma?","vn":"Bạn là học sinh phải không?"},{"cn":"你好吗?","pinyin":"Nǐ hǎo ma?","vn":"Bạn khỏe không?"}]},{"hanzi":"叫","pinyin":"jiào","pos":"dgt.","vn":"tên là, gọi là","examples":[{"cn":"我叫王明。","pinyin":"Wǒ jiào Wáng Míng.","vn":"Tôi tên là Vương Minh."},{"cn":"你叫什么名字?","pinyin":"Nǐ jiào shénme míngzi?","vn":"Bạn tên là gì?"},{"cn":"她叫什么?","pinyin":"Tā jiào shénme?","vn":"Cô ấy tên là gì?"}]},{"hanzi":"什么","pinyin":"shénme","pos":"đt.","vn":"cái gì, gì","examples":[{"cn":"这是什么?","pinyin":"Zhè shì shénme?","vn":"Đây là cái gì?"},{"cn":"你叫什么名字?","pinyin":"Nǐ jiào shénme míngzi?","vn":"Bạn tên là gì?"},{"cn":"你想吃什么?","pinyin":"Nǐ xiǎng chī shénme?","vn":"Bạn muốn ăn gì?"}]},{"hanzi":"名字","pinyin":"míngzi","pos":"dt.","vn":"tên","examples":[{"cn":"你的名字是什么?","pinyin":"Nǐ de míngzi shì shénme?","vn":"Tên của bạn là gì?"},{"cn":"我的名字是小明。","pinyin":"Wǒ de míngzi shì Xiǎomíng.","vn":"Tên tôi là Tiểu Minh."},{"cn":"她的名字很好听。","pinyin":"Tā de míngzi hěn hǎotīng.","vn":"Tên của cô ấy rất hay."}]},{"hanzi":"我","pinyin":"wǒ","pos":"đt.","vn":"tôi","examples":[{"cn":"我是学生。","pinyin":"Wǒ shì xuésheng.","vn":"Tôi là học sinh."},{"cn":"我叫小明。","pinyin":"Wǒ jiào Xiǎomíng.","vn":"Tôi tên là Tiểu Minh."},{"cn":"我很好。","pinyin":"Wǒ hěn hǎo.","vn":"Tôi khỏe."}]},{"hanzi":"不","pinyin":"bù","pos":"phó.","vn":"không","examples":[{"cn":"我不是老师。","pinyin":"Wǒ bú shì lǎoshī.","vn":"Tôi không phải là giáo viên."},{"cn":"我不忙。","pinyin":"Wǒ bù máng.","vn":"Tôi không bận."},{"cn":"她不是学生。","pinyin":"Tā bú shì xuésheng.","vn":"Cô ấy không phải là học sinh."}]},{"hanzi":"是","pinyin":"shì","pos":"dgt.","vn":"là","examples":[{"cn":"我是中国人。","pinyin":"Wǒ shì Zhōngguó rén.","vn":"Tôi là người Trung Quốc."},{"cn":"这是我的老师。","pinyin":"Zhè shì wǒ de lǎoshī.","vn":"Đây là giáo viên của tôi."},{"cn":"她是我姐姐。","pinyin":"Tā shì wǒ jiějie.","vn":"Cô ấy là chị gái tôi."}]},{"hanzi":"对不起","pinyin":"duìbuqǐ","pos":"dgt.","vn":"xin lỗi","examples":[{"cn":"对不起!","pinyin":"Duìbuqǐ!","vn":"Xin lỗi!"},{"cn":"对不起,老师。","pinyin":"Duìbuqǐ, lǎoshī.","vn":"Xin lỗi thầy/cô."},{"cn":"对不起!没关系!","pinyin":"Duìbuqǐ! Méi guānxi!","vn":"Xin lỗi! Không sao!"}]},{"hanzi":"没关系","pinyin":"méi guānxi","pos":"","vn":"không sao","examples":[{"cn":"没关系,再见。","pinyin":"Méi guānxi, zàijiàn.","vn":"Không sao, tạm biệt."},{"cn":"没关系,我不忙。","pinyin":"Méi guānxi, wǒ bù máng.","vn":"Không sao, tôi không bận."},{"cn":"对不起!没关系!","pinyin":"Duìbuqǐ! Méi guānxi!","vn":"Xin lỗi! Không sao!"}]},{"hanzi":"没事","pinyin":"méishì","pos":"dgt.","vn":"không sao, không có gì","examples":[{"cn":"没事,谢谢你。","pinyin":"Méishì, xièxie nǐ.","vn":"Không sao, cảm ơn bạn."},{"cn":"你没事吧?","pinyin":"Nǐ méishì ba?","vn":"Bạn không sao chứ?"},{"cn":"没事,我很好。","pinyin":"Méishì, wǒ hěn hǎo.","vn":"Không sao, tôi khỏe."}]},{"hanzi":"很","pinyin":"hěn","pos":"phó.","vn":"rất","examples":[{"cn":"我很高兴。","pinyin":"Wǒ hěn gāoxìng.","vn":"Tôi rất vui."},{"cn":"她很忙。","pinyin":"Tā hěn máng.","vn":"Cô ấy rất bận."},{"cn":"老师很好。","pinyin":"Lǎoshī hěn hǎo.","vn":"Giáo viên rất tốt."}]},{"hanzi":"高兴","pinyin":"gāoxìng","pos":"tt.","vn":"vui, vui mừng","examples":[{"cn":"认识你很高兴。","pinyin":"Rènshi nǐ hěn gāoxìng.","vn":"Rất vui được quen biết bạn."},{"cn":"我很高兴。","pinyin":"Wǒ hěn gāoxìng.","vn":"Tôi rất vui."},{"cn":"她今天很高兴。","pinyin":"Tā jīntiān hěn gāoxìng.","vn":"Hôm nay cô ấy rất vui."}]},{"hanzi":"认识","pinyin":"rènshi","pos":"dgt.","vn":"quen biết, nhận biết","examples":[{"cn":"认识你很高兴。","pinyin":"Rènshi nǐ hěn gāoxìng.","vn":"Rất vui được quen biết bạn."},{"cn":"我认识她。","pinyin":"Wǒ rènshi tā.","vn":"Tôi quen cô ấy."},{"cn":"你认识王老师吗?","pinyin":"Nǐ rènshi Wáng lǎoshī ma?","vn":"Bạn có quen cô Vương không?"}]},{"hanzi":"也","pinyin":"yě","pos":"phó.","vn":"cũng","examples":[{"cn":"我也是学生。","pinyin":"Wǒ yě shì xuésheng.","vn":"Tôi cũng là học sinh."},{"cn":"她也很高兴。","pinyin":"Tā yě hěn gāoxìng.","vn":"Cô ấy cũng rất vui."},{"cn":"我也认识她。","pinyin":"Wǒ yě rènshi tā.","vn":"Tôi cũng quen cô ấy."}]}],"grammar":[{"title":"汉语的基本语序","explanation_vn":"Trật tự từ cơ bản trong tiếng Hán là: Chủ ngữ + Vị ngữ + Tân ngữ. Ví dụ: 我 (chủ ngữ) 叫 (vị ngữ) 陈天中 (tân ngữ).","examples":[{"cn":"你叫什么名字？","pinyin":"Nǐ jiào shénme míngzi?","vn":"Bạn tên là gì?"},{"cn":"我叫白家月。","pinyin":"Wǒ jiào Bái Jiāyuè.","vn":"Tôi tên là Bạch Gia Nguyệt."},{"cn":"我是学生。","pinyin":"Wǒ shì xuésheng.","vn":"Tôi là học sinh."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一飞","cn":"请问，你叫什么名字？","pinyin":"Qǐngwèn, nǐ jiào shénme míngzi?"},{"speaker":"陈天中","cn":"我叫陈天中。","pinyin":"Wǒ jiào Chén Tiānzhōng."}],"translation_vn":"Vương Nhất Phi: Xin hỏi, bạn tên là gì?\nTrần Thiên Trung: Tôi tên là Trần Thiên Trung.","audio_dialogue":"2-1.mp3","audio_vocab":"2-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"陈天中","cn":"你好，安妮！","pinyin":"Nǐ hǎo, Ānnī!"},{"speaker":"白家月","cn":"你好，陈天中！我不是安妮，我是白家月。","pinyin":"Nǐ hǎo, Chén Tiānzhōng! Wǒ bú shì Ānnī, wǒ shì Bái Jiāyuè."},{"speaker":"陈天中","cn":"对不起！","pinyin":"Duìbuqǐ!"},{"speaker":"白家月","cn":"没关系！","pinyin":"Méi guānxi!"}],"translation_vn":"Trần Thiên Trung: Chào Annie!\nBạch Gia Nguyệt: Chào Trần Thiên Trung! Tôi không phải Annie, tôi là Bạch Gia Nguyệt.\nTrần Thiên Trung: Xin lỗi!\nBạch Gia Nguyệt: Không sao!","audio_dialogue":"2-3.mp3","audio_vocab":"2-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"李文","cn":"你好！我叫李文。","pinyin":"Nǐ hǎo! Wǒ jiào Lǐ Wén."},{"speaker":"白家月","cn":"你好！我叫白家月。","pinyin":"Nǐ hǎo! Wǒ jiào Bái Jiāyuè."},{"speaker":"李文","cn":"很高兴认识你。","pinyin":"Hěn gāoxìng rènshi nǐ."},{"speaker":"白家月","cn":"认识你我也很高兴。","pinyin":"Rènshi nǐ wǒ yě hěn gāoxìng."}],"translation_vn":"Lý Văn: Xin chào! Tôi tên là Lý Văn.\nBạch Gia Nguyệt: Xin chào! Tôi tên là Bạch Gia Nguyệt.\nLý Văn: Rất vui được quen biết bạn.\nBạch Gia Nguyệt: Quen biết bạn tôi cũng rất vui.","audio_dialogue":"2-5.mp3","audio_vocab":"2-6.mp3"}]},{"id":3,"title_cn":"我是中国人","title_pinyin":"Wǒ shì Zhōngguó rén","title_vn":"Tôi là người Trung Quốc","goals":["Có thể nghe hiểu và sử dụng câu chữ \"是\" để biểu đạt sự đồng nhất hoặc phân loại.","Nắm được cách dùng trợ từ kết cấu \"的\".","Nắm được cách dùng câu hỏi có/không với \"吗\"."],"vocab":[{"hanzi":"人","pinyin":"rén","pos":"dt.","vn":"người","examples":[{"cn":"我是中国人。","pinyin":"Wǒ shì Zhōngguó rén.","vn":"Tôi là người Trung Quốc."},{"cn":"她是哪国人?","pinyin":"Tā shì nǎ guó rén?","vn":"Cô ấy là người nước nào?"},{"cn":"这个人是我的同学。","pinyin":"Zhège rén shì wǒ de tóngxué.","vn":"Người này là bạn học của tôi."}]},{"hanzi":"的","pinyin":"de","pos":"trợ.","vn":"trợ từ kết cấu, biểu thị quan hệ sở hữu/định ngữ","examples":[{"cn":"这是我的名字。","pinyin":"Zhè shì wǒ de míngzi.","vn":"Đây là tên của tôi."},{"cn":"她是我的姐姐。","pinyin":"Tā shì wǒ de jiějie.","vn":"Cô ấy là chị gái tôi."},{"cn":"这是老师的工作。","pinyin":"Zhè shì lǎoshī de gōngzuò.","vn":"Đây là công việc của giáo viên."}]},{"hanzi":"中国","pinyin":"Zhōngguó","pos":"danh từ riêng","vn":"Trung Quốc","examples":[{"cn":"我是中国人。","pinyin":"Wǒ shì Zhōngguó rén.","vn":"Tôi là người Trung Quốc."},{"cn":"她在中国工作。","pinyin":"Tā zài Zhōngguó gōngzuò.","vn":"Cô ấy làm việc ở Trung Quốc."},{"cn":"王老师是中国人。","pinyin":"Wáng lǎoshī shì Zhōngguó rén.","vn":"Cô Vương là người Trung Quốc."}]},{"hanzi":"法国","pinyin":"Fǎguó","pos":"danh từ riêng","vn":"Pháp","examples":[{"cn":"他是法国人。","pinyin":"Tā shì Fǎguó rén.","vn":"Anh ấy là người Pháp."},{"cn":"我想去法国。","pinyin":"Wǒ xiǎng qù Fǎguó.","vn":"Tôi muốn đi Pháp."},{"cn":"她在法国工作。","pinyin":"Tā zài Fǎguó gōngzuò.","vn":"Cô ấy làm việc ở Pháp."}]},{"hanzi":"中文","pinyin":"Zhōngwén","pos":"danh từ riêng","vn":"tiếng Trung, Hán ngữ","examples":[{"cn":"我学中文。","pinyin":"Wǒ xué Zhōngwén.","vn":"Tôi học tiếng Trung."},{"cn":"她的中文很好。","pinyin":"Tā de Zhōngwén hěn hǎo.","vn":"Tiếng Trung của cô ấy rất tốt."},{"cn":"你会中文吗?","pinyin":"Nǐ huì Zhōngwén ma?","vn":"Bạn biết tiếng Trung không?"}]},{"hanzi":"这","pinyin":"zhè","pos":"đt.","vn":"cái này, đây","examples":[{"cn":"这是我的老师。","pinyin":"Zhè shì wǒ de lǎoshī.","vn":"Đây là giáo viên của tôi."},{"cn":"这是什么?","pinyin":"Zhè shì shénme?","vn":"Đây là cái gì?"},{"cn":"这是谁?","pinyin":"Zhè shì shéi?","vn":"Đây là ai?"}]},{"hanzi":"谁","pinyin":"shéi/shuí","pos":"đt.","vn":"ai","examples":[{"cn":"她是谁?","pinyin":"Tā shì shéi?","vn":"Cô ấy là ai?"},{"cn":"这是谁的名字?","pinyin":"Zhè shì shéi de míngzi?","vn":"Đây là tên của ai?"},{"cn":"谁是你的老师?","pinyin":"Shéi shì nǐ de lǎoshī?","vn":"Ai là giáo viên của bạn?"}]},{"hanzi":"女朋友","pinyin":"nǚpéngyou","pos":"dt.","vn":"bạn gái","examples":[{"cn":"她是我的女朋友。","pinyin":"Tā shì wǒ de nǚpéngyou.","vn":"Cô ấy là bạn gái của tôi."},{"cn":"你有女朋友吗?","pinyin":"Nǐ yǒu nǚpéngyou ma?","vn":"Bạn có bạn gái không?"},{"cn":"我的女朋友很忙。","pinyin":"Wǒ de nǚpéngyou hěn máng.","vn":"Bạn gái tôi rất bận."}]},{"hanzi":"哪","pinyin":"nǎ","pos":"đt.","vn":"nào","examples":[{"cn":"你是哪国人?","pinyin":"Nǐ shì nǎ guó rén?","vn":"Bạn là người nước nào?"},{"cn":"她是哪里人?","pinyin":"Tā shì nǎlǐ rén?","vn":"Cô ấy là người ở đâu?"},{"cn":"这是哪个?","pinyin":"Zhè shì nǎge?","vn":"Cái này là cái nào?"}]},{"hanzi":"国","pinyin":"guó","pos":"dt.","vn":"nước, quốc gia","examples":[{"cn":"你是哪国人?","pinyin":"Nǐ shì nǎ guó rén?","vn":"Bạn là người nước nào?"},{"cn":"中国是大国。","pinyin":"Zhōngguó shì dà guó.","vn":"Trung Quốc là nước lớn."},{"cn":"她是哪国人?","pinyin":"Tā shì nǎ guó rén?","vn":"Cô ấy là người nước nào?"}]},{"hanzi":"她","pinyin":"tā","pos":"đt.","vn":"cô ấy, chị ấy","examples":[{"cn":"她是我姐姐。","pinyin":"Tā shì wǒ jiějie.","vn":"Cô ấy là chị gái tôi."},{"cn":"她很忙。","pinyin":"Tā hěn máng.","vn":"Cô ấy rất bận."},{"cn":"她是谁?","pinyin":"Tā shì shéi?","vn":"Cô ấy là ai?"}]},{"hanzi":"泰国","pinyin":"Tàiguó","pos":"danh từ riêng","vn":"Thái Lan","examples":[{"cn":"她是泰国人。","pinyin":"Tā shì Tàiguó rén.","vn":"Cô ấy là người Thái Lan."},{"cn":"我想去泰国。","pinyin":"Wǒ xiǎng qù Tàiguó.","vn":"Tôi muốn đi Thái Lan."},{"cn":"他在泰国工作。","pinyin":"Tā zài Tàiguó gōngzuò.","vn":"Anh ấy làm việc ở Thái Lan."}]},{"hanzi":"喂","pinyin":"wèi","pos":"ct.","vn":"này, alô","examples":[{"cn":"喂,你好!","pinyin":"Wèi, nǐ hǎo!","vn":"Alô, xin chào!"},{"cn":"喂,是王老师吗?","pinyin":"Wèi, shì Wáng lǎoshī ma?","vn":"Alô, có phải cô Vương không?"},{"cn":"喂,你是谁?","pinyin":"Wèi, nǐ shì shéi?","vn":"Alô, bạn là ai?"}]},{"hanzi":"姐姐","pinyin":"jiějie","pos":"dt.","vn":"chị gái","examples":[{"cn":"她是我姐姐。","pinyin":"Tā shì wǒ jiějie.","vn":"Cô ấy là chị gái tôi."},{"cn":"我姐姐很忙。","pinyin":"Wǒ jiějie hěn máng.","vn":"Chị gái tôi rất bận."},{"cn":"姐姐,你好吗?","pinyin":"Jiějie, nǐ hǎo ma?","vn":"Chị ơi, chị khỏe không?"}]},{"hanzi":"工作","pinyin":"gōngzuò","pos":"dt.","vn":"công việc","examples":[{"cn":"她的工作很忙。","pinyin":"Tā de gōngzuò hěn máng.","vn":"Công việc của cô ấy rất bận rộn."},{"cn":"我想工作。","pinyin":"Wǒ xiǎng gōngzuò.","vn":"Tôi muốn làm việc."},{"cn":"你工作忙吗?","pinyin":"Nǐ gōngzuò máng ma?","vn":"Công việc của bạn có bận không?"}]},{"hanzi":"还","pinyin":"hái","pos":"phó.","vn":"vẫn, còn","examples":[{"cn":"你还忙吗?","pinyin":"Nǐ hái máng ma?","vn":"Bạn vẫn còn bận không?"},{"cn":"她还是学生。","pinyin":"Tā hái shì xuésheng.","vn":"Cô ấy vẫn còn là học sinh."},{"cn":"我还想认识她。","pinyin":"Wǒ hái xiǎng rènshi tā.","vn":"Tôi vẫn muốn quen biết cô ấy."}]},{"hanzi":"忙","pinyin":"máng","pos":"tt.","vn":"bận, bận rộn","examples":[{"cn":"我很忙。","pinyin":"Wǒ hěn máng.","vn":"Tôi rất bận."},{"cn":"你工作忙吗?","pinyin":"Nǐ gōngzuò máng ma?","vn":"Công việc của bạn có bận không?"},{"cn":"她还忙吗?","pinyin":"Tā hái máng ma?","vn":"Cô ấy vẫn còn bận không?"}]},{"hanzi":"吗","pinyin":"ma","pos":"trợ.","vn":"trợ từ nghi vấn, đặt cuối câu hỏi có/không","examples":[{"cn":"你好吗?","pinyin":"Nǐ hǎo ma?","vn":"Bạn khỏe không?"},{"cn":"你是学生吗?","pinyin":"Nǐ shì xuésheng ma?","vn":"Bạn là học sinh phải không?"},{"cn":"她忙吗?","pinyin":"Tā máng ma?","vn":"Cô ấy có bận không?"}]},{"hanzi":"对","pinyin":"duì","pos":"tt.","vn":"đúng","examples":[{"cn":"对,我是学生。","pinyin":"Duì, wǒ shì xuésheng.","vn":"Đúng, tôi là học sinh."},{"cn":"这个对吗?","pinyin":"Zhège duì ma?","vn":"Cái này đúng không?"},{"cn":"对,她是我姐姐。","pinyin":"Duì, tā shì wǒ jiějie.","vn":"Đúng, cô ấy là chị gái tôi."}]},{"hanzi":"太","pinyin":"tài","pos":"phó.","vn":"quá, rất","examples":[{"cn":"太好了!","pinyin":"Tài hǎo le!","vn":"Tốt quá!"},{"cn":"太忙了!","pinyin":"Tài máng le!","vn":"Bận quá!"},{"cn":"她太高兴了。","pinyin":"Tā tài gāoxìng le.","vn":"Cô ấy vui quá."}]},{"hanzi":"我们","pinyin":"wǒmen","pos":"đt.","vn":"chúng tôi, chúng ta","examples":[{"cn":"我们是同学。","pinyin":"Wǒmen shì tóngxué.","vn":"Chúng tôi là bạn học."},{"cn":"我们很忙。","pinyin":"Wǒmen hěn máng.","vn":"Chúng tôi rất bận."},{"cn":"我们是中国人。","pinyin":"Wǒmen shì Zhōngguó rén.","vn":"Chúng tôi là người Trung Quốc."}]},{"hanzi":"想","pinyin":"xiǎng","pos":"dgt.","vn":"nhớ, mong nhớ","examples":[{"cn":"我想你。","pinyin":"Wǒ xiǎng nǐ.","vn":"Tôi nhớ bạn."},{"cn":"他很想家。","pinyin":"Tā hěn xiǎng jiā.","vn":"Anh ấy rất nhớ nhà."},{"cn":"我想我的姐姐。","pinyin":"Wǒ xiǎng wǒ de jiějie.","vn":"Tôi nhớ chị gái tôi."}]}],"grammar":[{"title":"\"是\"字句","explanation_vn":"Câu chữ \"是\" dùng để biểu thị người hoặc sự vật đồng nhất với cái gì hoặc thuộc loại gì, hình thức phủ định là \"不是\".","examples":[{"cn":"我是法国人。","pinyin":"Wǒ shì Fǎguó rén.","vn":"Tôi là người Pháp."},{"cn":"她是中文老师。","pinyin":"Tā shì Zhōngwén lǎoshī.","vn":"Cô ấy là giáo viên tiếng Trung."},{"cn":"我老师不是法国人。","pinyin":"Wǒ lǎoshī bú shì Fǎguó rén.","vn":"Giáo viên của tôi không phải người Pháp."}]},{"title":"结构助词\"的\"","explanation_vn":"Trợ từ kết cấu \"的\" đặt giữa định ngữ và trung tâm ngữ, biểu đạt quan hệ sở hữu. Nếu trước \"的\" là đại từ nhân xưng, phía sau là từ chỉ quan hệ thân thuộc hoặc danh từ chỉ người, có thể lược bỏ \"的\".","examples":[{"cn":"白家月的中文老师","pinyin":"Bái Jiāyuè de Zhōngwén lǎoshī","vn":"giáo viên tiếng Trung của Bạch Gia Nguyệt"},{"cn":"你的名字","pinyin":"nǐ de míngzi","vn":"tên của bạn"},{"cn":"我老师","pinyin":"wǒ lǎoshī","vn":"giáo viên của tôi"},{"cn":"我学生","pinyin":"wǒ xuésheng","vn":"học sinh của tôi"},{"cn":"你同学","pinyin":"nǐ tóngxué","vn":"bạn học của bạn"},{"cn":"我妈妈","pinyin":"wǒ māma","vn":"mẹ tôi"}]},{"title":"用\"吗\"的是非问句","explanation_vn":"\"吗\" là trợ từ ngữ khí, thường đặt ở cuối câu để biểu thị nghi vấn. Cấu trúc cơ bản: ……吗？","examples":[{"cn":"你也很忙吗？","pinyin":"Nǐ yě hěn máng ma?","vn":"Bạn cũng rất bận à?"},{"cn":"你是他的中文老师吗？","pinyin":"Nǐ shì tā de Zhōngwén lǎoshī ma?","vn":"Bạn là giáo viên tiếng Trung của anh ấy à?"},{"cn":"你有姐姐吗？","pinyin":"Nǐ yǒu jiějie ma?","vn":"Bạn có chị gái không?"}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"李文","cn":"我是中国人。","pinyin":"Wǒ shì Zhōngguó rén."},{"speaker":"白家月","cn":"我是法国人。我的中文老师也是中国人。","pinyin":"Wǒ shì Fǎguó rén. Wǒ de Zhōngwén lǎoshī yě shì Zhōngguó rén."}],"translation_vn":"Lý Văn: Tôi là người Trung Quốc.\nBạch Gia Nguyệt: Tôi là người Pháp. Giáo viên tiếng Trung của tôi cũng là người Trung Quốc.","audio_dialogue":"3-1.mp3","audio_vocab":"3-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"安妮","cn":"这是谁？","pinyin":"Zhè shì shéi?"},{"speaker":"陈天中","cn":"这是我女朋友。","pinyin":"Zhè shì wǒ nǚpéngyou."},{"speaker":"安妮","cn":"你女朋友是哪国人？","pinyin":"Nǐ nǚpéngyou shì nǎ guó rén?"},{"speaker":"陈天中","cn":"她也是泰国人。","pinyin":"Tā yě shì Tàiguó rén."}],"translation_vn":"Annie: Đây là ai vậy?\nTrần Thiên Trung: Đây là bạn gái của tôi.\nAnnie: Bạn gái của bạn là người nước nào?\nTrần Thiên Trung: Cô ấy cũng là người Thái Lan.","audio_dialogue":"3-3.mp3","audio_vocab":"3-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"喂，一飞！","pinyin":"Wèi, Yīfēi!"},{"speaker":"王一飞","cn":"姐姐！","pinyin":"Jiějie!"},{"speaker":"王一雪","cn":"你工作还忙吗？","pinyin":"Nǐ gōngzuò hái máng ma?"},{"speaker":"王一飞","cn":"对，还很忙。你也很忙吗？","pinyin":"Duì, hái hěn máng. Nǐ yě hěn máng ma?"},{"speaker":"王一雪","cn":"我不太忙。我们很想你。","pinyin":"Wǒ bú tài máng. Wǒmen hěn xiǎng nǐ."},{"speaker":"王一飞","cn":"我也想你们。","pinyin":"Wǒ yě xiǎng nǐmen."}],"translation_vn":"Vương Nhất Tuyết: Alô, Nhất Phi!\nVương Nhất Phi: Chị ơi!\nVương Nhất Tuyết: Công việc của em vẫn bận chứ?\nVương Nhất Phi: Vâng, vẫn bận lắm. Chị cũng bận lắm à?\nVương Nhất Tuyết: Chị không bận lắm. Bọn chị rất nhớ em.\nVương Nhất Phi: Em cũng nhớ mọi người.","audio_dialogue":"3-5.mp3","audio_vocab":"3-6.mp3"}]},{"id":4,"title_cn":"我有两个孩子","title_pinyin":"Wǒ yǒu liǎng gè háizi","title_vn":"Tôi có hai con","goals":["Có thể nghe hiểu và sử dụng câu \"有\" (1) để biểu đạt sự sở hữu người hoặc vật.","Nắm vững cách dùng cấu trúc \"A……, B呢？\".","Nắm vững cách dùng số từ, lượng từ được học trong bài này.","Hiểu cách người Trung Quốc hỏi đáp về tuổi tác, có thể sử dụng từ ngữ phù hợp để hỏi đáp về tuổi."],"vocab":[{"hanzi":"有","pinyin":"yǒu","pos":"dgt.","vn":"có","examples":[{"cn":"我有一个哥哥。","pinyin":"Wǒ yǒu yí gè gēge.","vn":"Tôi có một anh trai."},{"cn":"你有手机吗？","pinyin":"Nǐ yǒu shǒujī ma?","vn":"Bạn có điện thoại không?"},{"cn":"家里有五口人。","pinyin":"Jiā li yǒu wǔ kǒu rén.","vn":"Nhà tôi có năm người."}]},{"hanzi":"多少","pinyin":"duōshao","pos":"đt.","vn":"bao nhiêu","examples":[{"cn":"你家有多少人？","pinyin":"Nǐ jiā yǒu duōshao rén?","vn":"Nhà bạn có bao nhiêu người?"},{"cn":"这个多少钱？","pinyin":"Zhège duōshao qián?","vn":"Cái này bao nhiêu tiền?"},{"cn":"你有多少个孩子？","pinyin":"Nǐ yǒu duōshao gè háizi?","vn":"Bạn có bao nhiêu đứa con?"}]},{"hanzi":"个","pinyin":"gè","pos":"lượng.","vn":"cái (lượng từ chung)","examples":[{"cn":"我有一个妹妹。","pinyin":"Wǒ yǒu yí gè mèimei.","vn":"Tôi có một em gái."},{"cn":"他买了两个包子。","pinyin":"Tā mǎile liǎng gè bāozi.","vn":"Anh ấy mua hai cái bánh bao."},{"cn":"这个人是谁？","pinyin":"Zhège rén shì shéi?","vn":"Người này là ai?"}]},{"hanzi":"哥哥","pinyin":"gēge","pos":"dt.","vn":"anh trai","examples":[{"cn":"我哥哥今年二十岁。","pinyin":"Wǒ gēge jīnnián èrshí suì.","vn":"Anh trai tôi năm nay hai mươi tuổi."},{"cn":"我哥哥没有女儿。","pinyin":"Wǒ gēge méiyǒu nǚ'ér.","vn":"Anh trai tôi không có con gái."},{"cn":"这是我哥哥。","pinyin":"Zhè shì wǒ gēge.","vn":"Đây là anh trai tôi."}]},{"hanzi":"呢","pinyin":"ne","pos":"trợ.","vn":"trợ từ ngữ khí dùng ở cuối câu nghi vấn","examples":[{"cn":"我很好，你呢？","pinyin":"Wǒ hěn hǎo, nǐ ne?","vn":"Tôi khỏe, còn bạn thì sao?"},{"cn":"我爸爸在家，你爸爸呢？","pinyin":"Wǒ bàba zài jiā, nǐ bàba ne?","vn":"Bố tôi ở nhà, còn bố bạn thì sao?"},{"cn":"我喜欢面条儿，你呢？","pinyin":"Wǒ xǐhuan miàntiáor, nǐ ne?","vn":"Tôi thích mì, còn bạn thì sao?"}]},{"hanzi":"没有","pinyin":"méiyǒu","pos":"dgt.","vn":"không có","examples":[{"cn":"我没有哥哥。","pinyin":"Wǒ méiyǒu gēge.","vn":"Tôi không có anh trai."},{"cn":"他今天没有电话。","pinyin":"Tā jīntiān méiyǒu diànhuà.","vn":"Hôm nay anh ấy không có cuộc gọi."},{"cn":"家里没有牛奶了。","pinyin":"Jiā li méiyǒu niúnǎi le.","vn":"Nhà không còn sữa nữa."}]},{"hanzi":"家","pinyin":"jiā","pos":"dt.","vn":"nhà, gia đình","examples":[{"cn":"我家有四口人。","pinyin":"Wǒ jiā yǒu sì kǒu rén.","vn":"Nhà tôi có bốn người."},{"cn":"你家在哪儿？","pinyin":"Nǐ jiā zài nǎr?","vn":"Nhà bạn ở đâu?"},{"cn":"我今天在家休息。","pinyin":"Wǒ jīntiān zài jiā xiūxi.","vn":"Hôm nay tôi nghỉ ngơi ở nhà."}]},{"hanzi":"几","pinyin":"jǐ","pos":"đt.","vn":"mấy","examples":[{"cn":"你家有几口人？","pinyin":"Nǐ jiā yǒu jǐ kǒu rén?","vn":"Nhà bạn có mấy người?"},{"cn":"今天几号？","pinyin":"Jīntiān jǐ hào?","vn":"Hôm nay là ngày mấy?"},{"cn":"你有几个孩子？","pinyin":"Nǐ yǒu jǐ gè háizi?","vn":"Bạn có mấy đứa con?"}]},{"hanzi":"口","pinyin":"kǒu","pos":"lượng.","vn":"lượng từ dùng để đếm người trong gia đình, dao, v.v.","examples":[{"cn":"我家有三口人。","pinyin":"Wǒ jiā yǒu sān kǒu rén.","vn":"Nhà tôi có ba người."},{"cn":"你家有几口人？","pinyin":"Nǐ jiā yǒu jǐ kǒu rén?","vn":"Nhà bạn có mấy người?"},{"cn":"他家有五口人。","pinyin":"Tā jiā yǒu wǔ kǒu rén.","vn":"Nhà anh ấy có năm người."}]},{"hanzi":"爸爸","pinyin":"bàba","pos":"dt.","vn":"bố","examples":[{"cn":"我爸爸今年五十岁。","pinyin":"Wǒ bàba jīnnián wǔshí suì.","vn":"Bố tôi năm nay năm mươi tuổi."},{"cn":"爸爸在做饭。","pinyin":"Bàba zài zuò fàn.","vn":"Bố đang nấu cơm."},{"cn":"我爸爸喜欢喝牛奶。","pinyin":"Wǒ bàba xǐhuan hē niúnǎi.","vn":"Bố tôi thích uống sữa."}]},{"hanzi":"妈妈","pinyin":"māma","pos":"dt.","vn":"mẹ","examples":[{"cn":"我妈妈在家休息。","pinyin":"Wǒ māma zài jiā xiūxi.","vn":"Mẹ tôi ở nhà nghỉ ngơi."},{"cn":"妈妈，我回来了。","pinyin":"Māma, wǒ huílái le.","vn":"Mẹ ơi, con về rồi."},{"cn":"我妈妈会做饺子。","pinyin":"Wǒ māma huì zuò jiǎozi.","vn":"Mẹ tôi biết làm sủi cảo."}]},{"hanzi":"妹妹","pinyin":"mèimei","pos":"dt.","vn":"em gái","examples":[{"cn":"我妹妹今年十岁。","pinyin":"Wǒ mèimei jīnnián shí suì.","vn":"Em gái tôi năm nay mười tuổi."},{"cn":"我妹妹喜欢吃米饭。","pinyin":"Wǒ mèimei xǐhuan chī mǐfàn.","vn":"Em gái tôi thích ăn cơm."},{"cn":"这是我妹妹。","pinyin":"Zhè shì wǒ mèimei.","vn":"Đây là em gái tôi."}]},{"hanzi":"和","pinyin":"hé","pos":"liên.","vn":"và","examples":[{"cn":"我和哥哥在家。","pinyin":"Wǒ hé gēge zài jiā.","vn":"Tôi và anh trai ở nhà."},{"cn":"爸爸和妈妈去超市。","pinyin":"Bàba hé māma qù chāoshì.","vn":"Bố và mẹ đi siêu thị."},{"cn":"我喜欢米饭和饺子。","pinyin":"Wǒ xǐhuan mǐfàn hé jiǎozi.","vn":"Tôi thích cơm và sủi cảo."}]},{"hanzi":"儿子","pinyin":"érzi","pos":"dt.","vn":"con trai","examples":[{"cn":"我有一个儿子。","pinyin":"Wǒ yǒu yí gè érzi.","vn":"Tôi có một con trai."},{"cn":"他儿子今年三岁。","pinyin":"Tā érzi jīnnián sān suì.","vn":"Con trai anh ấy năm nay ba tuổi."},{"cn":"我儿子喜欢吃面条儿。","pinyin":"Wǒ érzi xǐhuan chī miàntiáor.","vn":"Con trai tôi thích ăn mì."}]},{"hanzi":"孩子","pinyin":"háizi","pos":"dt.","vn":"con, con cái","examples":[{"cn":"你有孩子吗？","pinyin":"Nǐ yǒu háizi ma?","vn":"Bạn có con chưa?"},{"cn":"我有两个孩子。","pinyin":"Wǒ yǒu liǎng gè háizi.","vn":"Tôi có hai đứa con."},{"cn":"这个孩子真好看。","pinyin":"Zhège háizi zhēn hǎokàn.","vn":"Đứa trẻ này thật dễ thương."}]},{"hanzi":"女儿","pinyin":"nǚ'ér","pos":"dt.","vn":"con gái","examples":[{"cn":"我有一个女儿。","pinyin":"Wǒ yǒu yí gè nǚ'ér.","vn":"Tôi có một con gái."},{"cn":"他女儿今年八岁。","pinyin":"Tā nǚ'ér jīnnián bā suì.","vn":"Con gái anh ấy năm nay tám tuổi."},{"cn":"我女儿真好看。","pinyin":"Wǒ nǚ'ér zhēn hǎokàn.","vn":"Con gái tôi thật xinh."}]},{"hanzi":"岁","pinyin":"suì","pos":"lượng.","vn":"tuổi","examples":[{"cn":"我今年二十岁。","pinyin":"Wǒ jīnnián èrshí suì.","vn":"Năm nay tôi hai mươi tuổi."},{"cn":"你今年多大岁数？","pinyin":"Nǐ jīnnián duō dà suìshu?","vn":"Năm nay bạn bao nhiêu tuổi?"},{"cn":"他儿子五岁了。","pinyin":"Tā érzi wǔ suì le.","vn":"Con trai anh ấy năm tuổi rồi."}]},{"hanzi":"他","pinyin":"tā","pos":"đt.","vn":"anh ấy, nó, cậu ấy","examples":[{"cn":"他是我哥哥。","pinyin":"Tā shì wǒ gēge.","vn":"Anh ấy là anh trai tôi."},{"cn":"他今年三十岁。","pinyin":"Tā jīnnián sānshí suì.","vn":"Năm nay anh ấy ba mươi tuổi."},{"cn":"他没有手机。","pinyin":"Tā méiyǒu shǒujī.","vn":"Anh ấy không có điện thoại."}]},{"hanzi":"今年","pinyin":"jīnnián","pos":"dt.","vn":"năm nay","examples":[{"cn":"我今年二十五岁。","pinyin":"Wǒ jīnnián èrshíwǔ suì.","vn":"Năm nay tôi hai mươi lăm tuổi."},{"cn":"他今年去中国。","pinyin":"Tā jīnnián qù Zhōngguó.","vn":"Năm nay anh ấy đi Trung Quốc."},{"cn":"今年我家有一个新孩子。","pinyin":"Jīnnián wǒ jiā yǒu yí gè xīn háizi.","vn":"Năm nay nhà tôi có thêm một em bé mới."}]},{"hanzi":"多","pinyin":"duō","pos":"đt.","vn":"bao nhiêu, đến mức nào (dùng hỏi về mức độ)","examples":[{"cn":"你今年多大？","pinyin":"Nǐ jīnnián duō dà?","vn":"Năm nay bạn bao nhiêu tuổi?"},{"cn":"你儿子多大了？","pinyin":"Nǐ érzi duō dà le?","vn":"Con trai bạn bao nhiêu tuổi rồi?"},{"cn":"你爸爸多大年纪？","pinyin":"Nǐ bàba duō dà niánjì?","vn":"Bố bạn bao nhiêu tuổi rồi?"}]},{"hanzi":"大","pinyin":"dà","pos":"tt.","vn":"(tuổi) lớn, nhiều","examples":[{"cn":"我哥哥比我大。","pinyin":"Wǒ gēge bǐ wǒ dà.","vn":"Anh trai tôi lớn tuổi hơn tôi."},{"cn":"你多大了？","pinyin":"Nǐ duō dà le?","vn":"Bạn bao nhiêu tuổi rồi?"},{"cn":"他儿子很大了。","pinyin":"Tā érzi hěn dà le.","vn":"Con trai anh ấy đã lớn rồi."}]}],"grammar":[{"title":"\"有\"字句（1） \"Có\" Sentence (1)","explanation_vn":"\"有\" trong bài này biểu thị sự sở hữu, hình thức phủ định là \"没/没有\".","examples":[{"cn":"她有二十个学生。","pinyin":"Tā yǒu èrshí gè xuésheng.","vn":"Cô ấy có hai mươi học sinh."},{"cn":"她有一个姐姐。","pinyin":"Tā yǒu yí gè jiějie.","vn":"Cô ấy có một chị gái."},{"cn":"我没/没有姐姐。","pinyin":"Wǒ méi/méiyǒu jiějie.","vn":"Tôi không có chị gái."}]},{"title":"数字的表达 Expression of Numbers","explanation_vn":"Trong tiếng Hán, số có hai cách viết: chữ số Ả Rập và chữ Hán, ví dụ \"1\" và \"一\". Với số \"2\", khi dùng làm số thứ tự (như \"第二\") thì đọc là \"二 (èr)\", còn khi đứng trước lượng từ thì đọc là \"两 (liǎng)\".","examples":[{"cn":"十二","pinyin":"shí'èr","vn":"12"},{"cn":"二十二","pinyin":"èrshí'èr","vn":"22"},{"cn":"一百二十二","pinyin":"yìbǎi èrshí'èr","vn":"122"},{"cn":"两个人","pinyin":"liǎng gè rén","vn":"hai người"},{"cn":"两口人","pinyin":"liǎng kǒu rén","vn":"hai người (trong gia đình)"},{"cn":"两本书","pinyin":"liǎng běn shū","vn":"hai quyển sách"}]},{"title":"语气助词\"呢\"（1） Modal Particle \"呢\" (1)","explanation_vn":"\"呢\" trong bài này đặt ở cuối câu, biểu thị nghi vấn, hỏi về tình huống đã được nhắc đến ở trên. Cấu trúc cơ bản: A……, B呢？","examples":[{"cn":"我有两个哥哥，你呢？","pinyin":"Wǒ yǒu liǎng gè gēge, nǐ ne?","vn":"Tôi có hai anh trai, còn bạn thì sao?"},{"cn":"我叫白家月，你呢？","pinyin":"Wǒ jiào Bái Jiāyuè, nǐ ne?","vn":"Tôi tên là Bạch Gia Nguyệt, còn bạn?"},{"cn":"我是中国人，你呢？","pinyin":"Wǒ shì Zhōngguó rén, nǐ ne?","vn":"Tôi là người Trung Quốc, còn bạn?"}]},{"title":"名量词和名量结构 Nominal Measure Words and [Num+M+(N)] Structure","explanation_vn":"Khi biểu đạt số lượng, số từ trong tiếng Hán thường phải đi kèm với lượng từ. Bài này học các danh lượng từ chỉ số lượng người hoặc vật như \"口, 个\", cùng với cấu trúc [Số từ + Lượng từ + (Danh từ)] như \"四口人, 两个哥哥\".","examples":[{"cn":"四口","pinyin":"sì kǒu","vn":"bốn người (trong gia đình)"},{"cn":"四口人","pinyin":"sì kǒu rén","vn":"bốn người trong gia đình"},{"cn":"两个","pinyin":"liǎng gè","vn":"hai (cái/người)"},{"cn":"两个学生","pinyin":"liǎng gè xuésheng","vn":"hai học sinh"}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"刘明","cn":"一飞忙吗？","pinyin":"Yīfēi máng ma?"},{"speaker":"王一雪","cn":"她很忙。","pinyin":"Tā hěn máng."},{"speaker":"刘明","cn":"她有多少个学生？","pinyin":"Tā yǒu duōshao gè xuésheng?"},{"speaker":"王一雪","cn":"她有二十个学生。","pinyin":"Tā yǒu èrshí gè xuésheng."}],"translation_vn":"Lưu Minh: Nhất Phi có bận không?\nVương Nhất Tuyết: Chị ấy rất bận.\nLưu Minh: Chị ấy có bao nhiêu học sinh?\nVương Nhất Tuyết: Chị ấy có hai mươi học sinh.","audio_dialogue":"4-1.mp3","audio_vocab":"4-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"我有两个哥哥，你呢？","pinyin":"Wǒ yǒu liǎng gè gēge, nǐ ne?"},{"speaker":"杨同乐","cn":"我没有哥哥。","pinyin":"Wǒ méiyǒu gēge."},{"speaker":"王一雪","cn":"你家有几口人？","pinyin":"Nǐ jiā yǒu jǐ kǒu rén?"},{"speaker":"杨同乐","cn":"我家有四口人，爸爸、妈妈、妹妹和我。","pinyin":"Wǒ jiā yǒu sì kǒu rén, bàba, māma, mèimei hé wǒ."}],"translation_vn":"Vương Nhất Tuyết: Tôi có hai anh trai, còn bạn?\nDương Đồng Lạc: Tôi không có anh trai.\nVương Nhất Tuyết: Nhà bạn có mấy người?\nDương Đồng Lạc: Nhà tôi có bốn người: bố, mẹ, em gái và tôi.","audio_dialogue":"4-3.mp3","audio_vocab":"4-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"杨同乐","cn":"这是您儿子吗？","pinyin":"Zhè shì nín érzi ma?"},{"speaker":"王一雪","cn":"是的。我有两个孩子，一个儿子，一个女儿。","pinyin":"Shì de. Wǒ yǒu liǎng gè háizi, yí gè érzi, yí gè nǚ'ér."},{"speaker":"杨同乐","cn":"您儿子几岁？","pinyin":"Nín érzi jǐ suì?"},{"speaker":"王一雪","cn":"他今年五岁。","pinyin":"Tā jīnnián wǔ suì."},{"speaker":"杨同乐","cn":"您女儿多大？","pinyin":"Nín nǚ'ér duō dà?"},{"speaker":"王一雪","cn":"她今年十二。","pinyin":"Tā jīnnián shí'èr."}],"translation_vn":"Dương Đồng Lạc: Đây là con trai của chị ạ?\nVương Nhất Tuyết: Đúng vậy. Tôi có hai con, một con trai, một con gái.\nDương Đồng Lạc: Con trai chị mấy tuổi rồi?\nVương Nhất Tuyết: Cháu năm nay năm tuổi.\nDương Đồng Lạc: Con gái chị bao nhiêu tuổi rồi?\nVương Nhất Tuyết: Cháu năm nay mười hai tuổi.","audio_dialogue":"4-5.mp3","audio_vocab":"4-6.mp3"}]},{"id":5,"title_cn":"今天我休息","title_pinyin":"Jīntiān wǒ xiūxi","title_vn":"Hôm nay tôi nghỉ","goals":["Có thể nghe hiểu, đọc hiểu và miêu tả ngày tháng xảy ra sự việc, hành vi theo thói quen của tiếng Trung.","Có thể nghe hiểu và sử dụng động từ năng nguyện \"会\" để biểu đạt việc biết làm hoặc có khả năng làm việc gì đó.","Nắm vững cách dùng câu có vị ngữ là danh từ."],"vocab":[{"hanzi":"今天","pinyin":"jīntiān","pos":"dt.","vn":"hôm nay","examples":[{"cn":"今天几号？","pinyin":"Jīntiān jǐ hào?","vn":"Hôm nay là ngày mấy?"},{"cn":"今天我不上班。","pinyin":"Jīntiān wǒ bú shàngbān.","vn":"Hôm nay tôi không đi làm."},{"cn":"今天天气真好。","pinyin":"Jīntiān tiānqì zhēn hǎo.","vn":"Hôm nay thời tiết thật đẹp."}]},{"hanzi":"号","pinyin":"hào","pos":"lượng.","vn":"ngày (trong tháng)","examples":[{"cn":"今天十五号。","pinyin":"Jīntiān shíwǔ hào.","vn":"Hôm nay là ngày mười lăm."},{"cn":"我的生日是五月一号。","pinyin":"Wǒ de shēngrì shì wǔ yuè yī hào.","vn":"Sinh nhật tôi là ngày một tháng năm."},{"cn":"明天几号？","pinyin":"Míngtiān jǐ hào?","vn":"Ngày mai là ngày mấy?"}]},{"hanzi":"月","pinyin":"yuè","pos":"dt.","vn":"tháng","examples":[{"cn":"现在是几月？","pinyin":"Xiànzài shì jǐ yuè?","vn":"Bây giờ là tháng mấy?"},{"cn":"我十月去中国。","pinyin":"Wǒ shí yuè qù Zhōngguó.","vn":"Tháng mười tôi đi Trung Quốc."},{"cn":"一年有十二个月。","pinyin":"Yì nián yǒu shí'èr gè yuè.","vn":"Một năm có mười hai tháng."}]},{"hanzi":"日","pinyin":"rì","pos":"lượng.","vn":"ngày","examples":[{"cn":"今天是几月几日？","pinyin":"Jīntiān shì jǐ yuè jǐ rì?","vn":"Hôm nay là ngày mấy tháng mấy?"},{"cn":"十月一日是国庆节。","pinyin":"Shí yuè yī rì shì Guóqìngjié.","vn":"Ngày mùng một tháng mười là Quốc khánh."},{"cn":"我的生日是三月八日。","pinyin":"Wǒ de shēngrì shì sān yuè bā rì.","vn":"Sinh nhật tôi là ngày tám tháng ba."}]},{"hanzi":"星期","pinyin":"xīngqī","pos":"dt.","vn":"tuần","examples":[{"cn":"今天星期几？","pinyin":"Jīntiān xīngqī jǐ?","vn":"Hôm nay thứ mấy?"},{"cn":"我星期一上班。","pinyin":"Wǒ xīngqīyī shàngbān.","vn":"Tôi đi làm vào thứ Hai."},{"cn":"下星期我休息。","pinyin":"Xià xīngqī wǒ xiūxi.","vn":"Tuần sau tôi nghỉ."}]},{"hanzi":"星期日","pinyin":"Xīngqīrì","pos":"dt.","vn":"Chủ nhật","examples":[{"cn":"今天星期日。","pinyin":"Jīntiān Xīngqīrì.","vn":"Hôm nay là Chủ nhật."},{"cn":"星期日我不上班。","pinyin":"Xīngqīrì wǒ bú shàngbān.","vn":"Chủ nhật tôi không đi làm."},{"cn":"星期日我去超市。","pinyin":"Xīngqīrì wǒ qù chāoshì.","vn":"Chủ nhật tôi đi siêu thị."}]},{"hanzi":"星期天","pinyin":"Xīngqītiān","pos":"dt.","vn":"Chủ nhật","examples":[{"cn":"明天是星期天。","pinyin":"Míngtiān shì Xīngqītiān.","vn":"Ngày mai là Chủ nhật."},{"cn":"星期天我在家休息。","pinyin":"Xīngqītiān wǒ zài jiā xiūxi.","vn":"Chủ nhật tôi ở nhà nghỉ ngơi."},{"cn":"星期天你想做什么？","pinyin":"Xīngqītiān nǐ xiǎng zuò shénme?","vn":"Chủ nhật bạn muốn làm gì?"}]},{"hanzi":"休息","pinyin":"xiūxi","pos":"dgt.","vn":"nghỉ ngơi","examples":[{"cn":"我今天休息。","pinyin":"Wǒ jīntiān xiūxi.","vn":"Hôm nay tôi nghỉ ngơi."},{"cn":"你累了吗？休息一下吧。","pinyin":"Nǐ lèi le ma? Xiūxi yíxià ba.","vn":"Bạn mệt chưa? Nghỉ một chút đi."},{"cn":"星期天我在家休息。","pinyin":"Xīngqītiān wǒ zài jiā xiūxi.","vn":"Chủ nhật tôi ở nhà nghỉ ngơi."}]},{"hanzi":"会","pinyin":"huì","pos":"đtnn.","vn":"biết, có thể","examples":[{"cn":"我会做饭。","pinyin":"Wǒ huì zuò fàn.","vn":"Tôi biết nấu ăn."},{"cn":"你会说中文吗？","pinyin":"Nǐ huì shuō Zhōngwén ma?","vn":"Bạn biết nói tiếng Trung không?"},{"cn":"我妈妈会做饺子。","pinyin":"Wǒ māma huì zuò jiǎozi.","vn":"Mẹ tôi biết làm sủi cảo."}]},{"hanzi":"做饭","pinyin":"zuò fàn","pos":"","vn":"nấu cơm, nấu ăn","examples":[{"cn":"我在做饭。","pinyin":"Wǒ zài zuò fàn.","vn":"Tôi đang nấu cơm."},{"cn":"谁会做饭？","pinyin":"Shéi huì zuò fàn?","vn":"Ai biết nấu ăn?"},{"cn":"妈妈每天做饭。","pinyin":"Māma měitiān zuò fàn.","vn":"Mẹ nấu cơm mỗi ngày."}]},{"hanzi":"做","pinyin":"zuò","pos":"dgt.","vn":"làm, chế biến","examples":[{"cn":"你在做什么？","pinyin":"Nǐ zài zuò shénme?","vn":"Bạn đang làm gì?"},{"cn":"我做了一些菜。","pinyin":"Wǒ zuòle yìxiē cài.","vn":"Tôi đã làm một vài món ăn."},{"cn":"妈妈做的饺子真好吃。","pinyin":"Māma zuò de jiǎozi zhēn hǎochī.","vn":"Sủi cảo mẹ làm thật ngon."}]},{"hanzi":"面条儿","pinyin":"miàntiáor","pos":"dt.","vn":"mì sợi","examples":[{"cn":"我喜欢吃面条儿。","pinyin":"Wǒ xǐhuan chī miàntiáor.","vn":"Tôi thích ăn mì."},{"cn":"妈妈做了面条儿。","pinyin":"Māma zuòle miàntiáor.","vn":"Mẹ đã làm mì."},{"cn":"这个面条儿真好吃。","pinyin":"Zhège miàntiáor zhēn hǎochī.","vn":"Mì này thật ngon."}]},{"hanzi":"饺子","pinyin":"jiǎozi","pos":"dt.","vn":"sủi cảo (jiaozi)","examples":[{"cn":"我们吃饺子吧。","pinyin":"Wǒmen chī jiǎozi ba.","vn":"Chúng ta ăn sủi cảo nhé."},{"cn":"妈妈会做饺子。","pinyin":"Māma huì zuò jiǎozi.","vn":"Mẹ biết làm sủi cảo."},{"cn":"这些饺子真好吃。","pinyin":"Zhèxiē jiǎozi zhēn hǎochī.","vn":"Những cái sủi cảo này thật ngon."}]},{"hanzi":"一些","pinyin":"yìxiē","pos":"sl.","vn":"một ít, một vài","examples":[{"cn":"我买了一些东西。","pinyin":"Wǒ mǎile yìxiē dōngxi.","vn":"Tôi đã mua một ít đồ."},{"cn":"妈妈做了一些菜。","pinyin":"Māma zuòle yìxiē cài.","vn":"Mẹ đã làm một vài món ăn."},{"cn":"我想买一些牛奶。","pinyin":"Wǒ xiǎng mǎi yìxiē niúnǎi.","vn":"Tôi muốn mua một ít sữa."}]},{"hanzi":"菜","pinyin":"cài","pos":"dt.","vn":"món ăn","examples":[{"cn":"妈妈做了很多菜。","pinyin":"Māma zuòle hěn duō cài.","vn":"Mẹ đã làm rất nhiều món ăn."},{"cn":"这个菜真好吃。","pinyin":"Zhège cài zhēn hǎochī.","vn":"Món này thật ngon."},{"cn":"你喜欢吃什么菜？","pinyin":"Nǐ xǐhuan chī shénme cài?","vn":"Bạn thích ăn món gì?"}]},{"hanzi":"下班","pinyin":"xiàbān","pos":"dgt.","vn":"tan làm, hết giờ làm","examples":[{"cn":"我六点下班。","pinyin":"Wǒ liù diǎn xiàbān.","vn":"Tôi tan làm lúc sáu giờ."},{"cn":"你几点下班？","pinyin":"Nǐ jǐ diǎn xiàbān?","vn":"Mấy giờ bạn tan làm?"},{"cn":"爸爸还没下班。","pinyin":"Bàba hái méi xiàbān.","vn":"Bố vẫn chưa tan làm."}]},{"hanzi":"新","pinyin":"xīn","pos":"tt.","vn":"mới","examples":[{"cn":"我买了一个新手机。","pinyin":"Wǒ mǎile yí gè xīn shǒujī.","vn":"Tôi đã mua một chiếc điện thoại mới."},{"cn":"这是我的新电脑。","pinyin":"Zhè shì wǒ de xīn diànnǎo.","vn":"Đây là máy tính mới của tôi."},{"cn":"他有一个新家。","pinyin":"Tā yǒu yí gè xīn jiā.","vn":"Anh ấy có một ngôi nhà mới."}]},{"hanzi":"电脑","pinyin":"diànnǎo","pos":"dt.","vn":"máy tính","examples":[{"cn":"我买了一台电脑。","pinyin":"Wǒ mǎile yì tái diànnǎo.","vn":"Tôi đã mua một cái máy tính."},{"cn":"这是我的新电脑。","pinyin":"Zhè shì wǒ de xīn diànnǎo.","vn":"Đây là máy tính mới của tôi."},{"cn":"他的电脑真好看。","pinyin":"Tā de diànnǎo zhēn hǎokàn.","vn":"Máy tính của anh ấy thật đẹp."}]},{"hanzi":"真","pinyin":"zhēn","pos":"phó.","vn":"thật, thật sự","examples":[{"cn":"这个菜真好吃。","pinyin":"Zhège cài zhēn hǎochī.","vn":"Món này thật ngon."},{"cn":"你真好。","pinyin":"Nǐ zhēn hǎo.","vn":"Bạn thật tốt."},{"cn":"今天真冷。","pinyin":"Jīntiān zhēn lěng.","vn":"Hôm nay thật lạnh."}]},{"hanzi":"好看","pinyin":"hǎokàn","pos":"tt.","vn":"đẹp, đẹp mắt","examples":[{"cn":"这件衣服真好看。","pinyin":"Zhè jiàn yīfu zhēn hǎokàn.","vn":"Cái áo này thật đẹp."},{"cn":"你的手机很好看。","pinyin":"Nǐ de shǒujī hěn hǎokàn.","vn":"Điện thoại của bạn rất đẹp."},{"cn":"我女儿真好看。","pinyin":"Wǒ nǚ'ér zhēn hǎokàn.","vn":"Con gái tôi thật xinh."}]},{"hanzi":"喜欢","pinyin":"xǐhuan","pos":"dgt.","vn":"thích","examples":[{"cn":"我喜欢吃饺子。","pinyin":"Wǒ xǐhuan chī jiǎozi.","vn":"Tôi thích ăn sủi cảo."},{"cn":"你喜欢它吗？","pinyin":"Nǐ xǐhuan tā ma?","vn":"Bạn có thích nó không?"},{"cn":"我妹妹喜欢喝牛奶。","pinyin":"Wǒ mèimei xǐhuan hē niúnǎi.","vn":"Em gái tôi thích uống sữa."}]},{"hanzi":"它","pinyin":"tā","pos":"đt.","vn":"nó","examples":[{"cn":"这是我的电脑，我很喜欢它。","pinyin":"Zhè shì wǒ de diànnǎo, wǒ hěn xǐhuan tā.","vn":"Đây là máy tính của tôi, tôi rất thích nó."},{"cn":"这只猫，它真好看。","pinyin":"Zhè zhī māo, tā zhēn hǎokàn.","vn":"Con mèo này, nó thật đẹp."},{"cn":"手机在那边，你看到它了吗？","pinyin":"Shǒujī zài nàbiān, nǐ kàndào tā le ma?","vn":"Điện thoại ở đằng kia, bạn thấy nó chưa?"}]}],"grammar":[{"title":"时间的表达（1） Expression of Time (1)","explanation_vn":"Bài này học cách biểu đạt ngày tháng và thứ trong tuần. Thứ tự biểu đạt ngày tháng, thứ trong tiếng Hán là: năm → tháng → ngày/số → thứ.","examples":[{"cn":"1992年5月16日/号，星期六","pinyin":"yī jiǔ jiǔ èr nián wǔ yuè shíliù rì/hào, Xīngqīliù","vn":"Thứ Bảy, ngày 16 tháng 5 năm 1992"},{"cn":"2024年10月22日/号，星期二","pinyin":"èr líng èr sì nián shí yuè èrshí'èr rì/hào, Xīngqī'èr","vn":"Thứ Ba, ngày 22 tháng 10 năm 2024"},{"cn":"今天9月8号。","pinyin":"Jīntiān jiǔ yuè bā hào.","vn":"Hôm nay là ngày 8 tháng 9."},{"cn":"今天是2025年5月22号。","pinyin":"Jīntiān shì èr líng èr wǔ nián wǔ yuè èrshí'èr hào.","vn":"Hôm nay là ngày 22 tháng 5 năm 2025."},{"cn":"明天是2024年8月18号，星期天。","pinyin":"Míngtiān shì èr líng èr sì nián bā yuè shíbā hào, Xīngqītiān.","vn":"Ngày mai là Chủ nhật, ngày 18 tháng 8 năm 2024."}]},{"title":"名词谓语句 Nominal-Predicate Sentences","explanation_vn":"Trong câu có vị ngữ là danh từ, phần vị ngữ chỉ gồm danh từ hoặc thành phần mang tính danh từ, các từ ngữ này thường biểu thị thời gian, ngày tháng, tuổi tác, v.v.","examples":[{"cn":"今天几号？今天5月1号。","pinyin":"Jīntiān jǐ hào? Jīntiān wǔ yuè yī hào.","vn":"Hôm nay là ngày mấy? Hôm nay là ngày 1 tháng 5."},{"cn":"我妹妹12岁。","pinyin":"Wǒ mèimei shí'èr suì.","vn":"Em gái tôi 12 tuổi."}]},{"title":"能愿动词\"会\" Modal Verb \"会\"","explanation_vn":"\"会\" đặt trước động từ, biểu thị việc thông qua học tập mà biết cách làm hoặc có khả năng làm việc gì đó.","examples":[{"cn":"你会做饭吗？","pinyin":"Nǐ huì zuò fàn ma?","vn":"Bạn có biết nấu ăn không?"},{"cn":"我会做面条儿。","pinyin":"Wǒ huì zuò miàntiáor.","vn":"Tôi biết làm mì."},{"cn":"我不会做菜。","pinyin":"Wǒ bú huì zuò cài.","vn":"Tôi không biết nấu món ăn."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"今天几号？","pinyin":"Jīntiān jǐ hào?"},{"speaker":"刘明","cn":"今天9月8号。","pinyin":"Jīntiān jiǔ yuè bā hào."},{"speaker":"王一雪","cn":"星期几？","pinyin":"Xīngqī jǐ?"},{"speaker":"刘明","cn":"星期日。今天我休息。","pinyin":"Xīngqīrì. Jīntiān wǒ xiūxi."}],"translation_vn":"Vương Nhất Tuyết: Hôm nay là ngày mấy?\nLưu Minh: Hôm nay là ngày 8 tháng 9.\nVương Nhất Tuyết: Thứ mấy?\nLưu Minh: Chủ nhật. Hôm nay tôi nghỉ.","audio_dialogue":"5-1.mp3","audio_vocab":"5-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"你会做饭吗？","pinyin":"Nǐ huì zuò fàn ma?"},{"speaker":"杨同乐","cn":"我会做。","pinyin":"Wǒ huì zuò."},{"speaker":"王一雪","cn":"你会做什么？","pinyin":"Nǐ huì zuò shénme?"},{"speaker":"杨同乐","cn":"我会做面条儿、饺子，也会做一些菜。星期天我也做饭。","pinyin":"Wǒ huì zuò miàntiáor, jiǎozi, yě huì zuò yìxiē cài. Xīngqītiān wǒ yě zuò fàn."}],"translation_vn":"Vương Nhất Tuyết: Bạn có biết nấu ăn không?\nDương Đồng Lạc: Tôi biết nấu.\nVương Nhất Tuyết: Bạn biết làm món gì?\nDương Đồng Lạc: Tôi biết làm mì, sủi cảo, cũng biết nấu một vài món ăn. Chủ nhật tôi cũng nấu cơm.","audio_dialogue":"5-3.mp3","audio_vocab":"5-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"同乐，下班吗？","pinyin":"Tóngle, xiàbān ma?"},{"speaker":"杨同乐","cn":"下班。","pinyin":"Xiàbān."},{"speaker":"王一雪","cn":"这是你的新电脑吗？","pinyin":"Zhè shì nǐ de xīn diànnǎo ma?"},{"speaker":"杨同乐","cn":"是的，是我的新电脑。","pinyin":"Shì de, shì wǒ de xīn diànnǎo."},{"speaker":"王一雪","cn":"真好看！","pinyin":"Zhēn hǎokàn!"},{"speaker":"杨同乐","cn":"我也很喜欢它。","pinyin":"Wǒ yě hěn xǐhuan tā."}],"translation_vn":"Vương Nhất Tuyết: Đồng Lạc, tan làm rồi à?\nDương Đồng Lạc: Tan làm rồi.\nVương Nhất Tuyết: Đây là máy tính mới của bạn à?\nDương Đồng Lạc: Đúng vậy, là máy tính mới của tôi.\nVương Nhất Tuyết: Đẹp thật đấy!\nDương Đồng Lạc: Tôi cũng rất thích nó.","audio_dialogue":"5-5.mp3","audio_vocab":"5-6.mp3"}]},{"id":6,"title_cn":"你的手机号是多少？","title_pinyin":"Nǐ de shǒujīhào shì duōshao?","title_vn":"Số điện thoại di động của bạn là bao nhiêu?","goals":["Có thể nghe hiểu số điện thoại di động và sử dụng số để gọi điện.","Có thể nghe hiểu và sử dụng hai hoặc nhiều cụm động từ để biểu đạt mục đích hoặc cách thức của hành động.","Nắm vững cách dùng động từ năng nguyện \"想\".","Nắm vững cách dùng đại từ nghi vấn \"怎么\" để hỏi về cách thức."],"vocab":[{"hanzi":"手机","pinyin":"shǒujī","pos":"dt.","vn":"điện thoại di động","examples":[{"cn":"我的手机是新的。","pinyin":"Wǒ de shǒujī shì xīn de.","vn":"Điện thoại của tôi là mới."},{"cn":"你的手机号是多少？","pinyin":"Nǐ de shǒujī hào shì duōshao?","vn":"Số điện thoại của bạn là gì?"},{"cn":"我没有手机。","pinyin":"Wǒ méiyǒu shǒujī.","vn":"Tôi không có điện thoại."}]},{"hanzi":"电话","pinyin":"diànhuà","pos":"dt.","vn":"điện thoại, cuộc gọi","examples":[{"cn":"我给你打电话。","pinyin":"Wǒ gěi nǐ dǎ diànhuà.","vn":"Tôi sẽ gọi điện cho bạn."},{"cn":"你的电话号码是多少？","pinyin":"Nǐ de diànhuà hàomǎ shì duōshao?","vn":"Số điện thoại của bạn là bao nhiêu?"},{"cn":"他在打电话。","pinyin":"Tā zài dǎ diànhuà.","vn":"Anh ấy đang gọi điện thoại."}]},{"hanzi":"号","pinyin":"hào","pos":"dt.","vn":"số","examples":[{"cn":"你的电话号是多少？","pinyin":"Nǐ de diànhuà hào shì duōshao?","vn":"Số điện thoại của bạn là bao nhiêu?"},{"cn":"我的手机号是138开头。","pinyin":"Wǒ de shǒujī hào shì yāo sān bā kāitóu.","vn":"Số điện thoại của tôi bắt đầu bằng 138."},{"cn":"这是我家的门牌号。","pinyin":"Zhè shì wǒ jiā de ménpái hào.","vn":"Đây là số nhà của tôi."}]},{"hanzi":"明天","pinyin":"míngtiān","pos":"dt.","vn":"ngày mai","examples":[{"cn":"明天我去超市。","pinyin":"Míngtiān wǒ qù chāoshì.","vn":"Ngày mai tôi đi siêu thị."},{"cn":"明天几号？","pinyin":"Míngtiān jǐ hào?","vn":"Ngày mai là ngày mấy?"},{"cn":"明天我休息。","pinyin":"Míngtiān wǒ xiūxi.","vn":"Ngày mai tôi nghỉ."}]},{"hanzi":"去","pinyin":"qù","pos":"dgt.","vn":"đi","examples":[{"cn":"我去超市。","pinyin":"Wǒ qù chāoshì.","vn":"Tôi đi siêu thị."},{"cn":"你想去哪儿？","pinyin":"Nǐ xiǎng qù nǎr?","vn":"Bạn muốn đi đâu?"},{"cn":"我们坐出租车去。","pinyin":"Wǒmen zuò chūzūchē qù.","vn":"Chúng ta đi bằng taxi."}]},{"hanzi":"哪儿","pinyin":"nǎr","pos":"đt.","vn":"đâu, chỗ nào","examples":[{"cn":"你去哪儿？","pinyin":"Nǐ qù nǎr?","vn":"Bạn đi đâu?"},{"cn":"你家在哪儿？","pinyin":"Nǐ jiā zài nǎr?","vn":"Nhà bạn ở đâu?"},{"cn":"超市在哪儿？","pinyin":"Chāoshì zài nǎr?","vn":"Siêu thị ở đâu?"}]},{"hanzi":"想","pinyin":"xiǎng","pos":"đtnn.","vn":"muốn","examples":[{"cn":"我想去超市。","pinyin":"Wǒ xiǎng qù chāoshì.","vn":"Tôi muốn đi siêu thị."},{"cn":"你想吃什么？","pinyin":"Nǐ xiǎng chī shénme?","vn":"Bạn muốn ăn gì?"},{"cn":"我想买一个新手机。","pinyin":"Wǒ xiǎng mǎi yí gè xīn shǒujī.","vn":"Tôi muốn mua một chiếc điện thoại mới."}]},{"hanzi":"超市","pinyin":"chāoshì","pos":"dt.","vn":"siêu thị","examples":[{"cn":"我去超市买东西。","pinyin":"Wǒ qù chāoshì mǎi dōngxi.","vn":"Tôi đi siêu thị mua đồ."},{"cn":"超市在那边。","pinyin":"Chāoshì zài nàbiān.","vn":"Siêu thị ở đằng kia."},{"cn":"妈妈在超市买牛奶。","pinyin":"Māma zài chāoshì mǎi niúnǎi.","vn":"Mẹ mua sữa ở siêu thị."}]},{"hanzi":"买","pinyin":"mǎi","pos":"dgt.","vn":"mua","examples":[{"cn":"我想买一些东西。","pinyin":"Wǒ xiǎng mǎi yìxiē dōngxi.","vn":"Tôi muốn mua một ít đồ."},{"cn":"你买了什么？","pinyin":"Nǐ mǎile shénme?","vn":"Bạn đã mua gì?"},{"cn":"我买了一个新电脑。","pinyin":"Wǒ mǎile yí gè xīn diànnǎo.","vn":"Tôi đã mua một cái máy tính mới."}]},{"hanzi":"东西","pinyin":"dōngxi","pos":"dt.","vn":"đồ, thứ","examples":[{"cn":"我去超市买东西。","pinyin":"Wǒ qù chāoshì mǎi dōngxi.","vn":"Tôi đi siêu thị mua đồ."},{"cn":"这是什么东西？","pinyin":"Zhè shì shénme dōngxi?","vn":"Đây là cái gì?"},{"cn":"我买了很多东西。","pinyin":"Wǒ mǎile hěn duō dōngxi.","vn":"Tôi đã mua rất nhiều đồ."}]},{"hanzi":"些","pinyin":"xiē","pos":"lượng.","vn":"vài, một số","examples":[{"cn":"我买了一些东西。","pinyin":"Wǒ mǎile yìxiē dōngxi.","vn":"Tôi đã mua một ít đồ."},{"cn":"这些菜真好吃。","pinyin":"Zhèxiē cài zhēn hǎochī.","vn":"Những món này thật ngon."},{"cn":"那些是谁的东西？","pinyin":"Nàxiē shì shéi de dōngxi?","vn":"Những thứ đó là của ai?"}]},{"hanzi":"牛奶","pinyin":"niúnǎi","pos":"dt.","vn":"sữa (bò)","examples":[{"cn":"我每天喝牛奶。","pinyin":"Wǒ měitiān hē niúnǎi.","vn":"Mỗi ngày tôi uống sữa."},{"cn":"家里没有牛奶了。","pinyin":"Jiā li méiyǒu niúnǎi le.","vn":"Nhà không còn sữa nữa."},{"cn":"妹妹喜欢喝牛奶。","pinyin":"Mèimei xǐhuan hē niúnǎi.","vn":"Em gái thích uống sữa."}]},{"hanzi":"吃","pinyin":"chī","pos":"dgt.","vn":"ăn","examples":[{"cn":"我喜欢吃米饭。","pinyin":"Wǒ xǐhuan chī mǐfàn.","vn":"Tôi thích ăn cơm."},{"cn":"你吃饭了吗？","pinyin":"Nǐ chī fàn le ma?","vn":"Bạn ăn cơm chưa?"},{"cn":"我们吃饺子吧。","pinyin":"Wǒmen chī jiǎozi ba.","vn":"Chúng ta ăn sủi cảo nhé."}]},{"hanzi":"晚饭","pinyin":"wǎnfàn","pos":"dt.","vn":"bữa tối, cơm tối","examples":[{"cn":"我们吃晚饭吧。","pinyin":"Wǒmen chī wǎnfàn ba.","vn":"Chúng ta ăn cơm tối nhé."},{"cn":"晚饭你想吃什么？","pinyin":"Wǎnfàn nǐ xiǎng chī shénme?","vn":"Bữa tối bạn muốn ăn gì?"},{"cn":"妈妈在做晚饭。","pinyin":"Māma zài zuò wǎnfàn.","vn":"Mẹ đang nấu cơm tối."}]},{"hanzi":"那边","pinyin":"nàbiān","pos":"đt.","vn":"đằng kia, chỗ đó","examples":[{"cn":"超市在那边。","pinyin":"Chāoshì zài nàbiān.","vn":"Siêu thị ở đằng kia."},{"cn":"我的手机在那边。","pinyin":"Wǒ de shǒujī zài nàbiān.","vn":"Điện thoại của tôi ở đằng kia."},{"cn":"他在那边等你。","pinyin":"Tā zài nàbiān děng nǐ.","vn":"Anh ấy đang đợi bạn ở đằng kia."}]},{"hanzi":"包子","pinyin":"bāozi","pos":"dt.","vn":"bánh bao","examples":[{"cn":"我喜欢吃包子。","pinyin":"Wǒ xǐhuan chī bāozi.","vn":"Tôi thích ăn bánh bao."},{"cn":"妈妈做了很多包子。","pinyin":"Māma zuòle hěn duō bāozi.","vn":"Mẹ đã làm rất nhiều bánh bao."},{"cn":"这个包子真好吃。","pinyin":"Zhège bāozi zhēn hǎochī.","vn":"Cái bánh bao này thật ngon."}]},{"hanzi":"非常","pinyin":"fēicháng","pos":"phó.","vn":"rất, vô cùng","examples":[{"cn":"这个菜非常好吃。","pinyin":"Zhège cài fēicháng hǎochī.","vn":"Món này rất ngon."},{"cn":"我非常喜欢你。","pinyin":"Wǒ fēicháng xǐhuan nǐ.","vn":"Tôi rất thích bạn."},{"cn":"今天非常冷。","pinyin":"Jīntiān fēicháng lěng.","vn":"Hôm nay rất lạnh."}]},{"hanzi":"好吃","pinyin":"hǎochī","pos":"tt.","vn":"ngon","examples":[{"cn":"这个包子真好吃。","pinyin":"Zhège bāozi zhēn hǎochī.","vn":"Cái bánh bao này thật ngon."},{"cn":"妈妈做的菜很好吃。","pinyin":"Māma zuò de cài hěn hǎochī.","vn":"Món mẹ làm rất ngon."},{"cn":"这个面条儿好吃吗？","pinyin":"Zhège miàntiáor hǎochī ma?","vn":"Mì này có ngon không?"}]},{"hanzi":"米饭","pinyin":"mǐfàn","pos":"dt.","vn":"cơm","examples":[{"cn":"我喜欢吃米饭。","pinyin":"Wǒ xǐhuan chī mǐfàn.","vn":"Tôi thích ăn cơm."},{"cn":"晚饭吃米饭吧。","pinyin":"Wǎnfàn chī mǐfàn ba.","vn":"Bữa tối ăn cơm nhé."},{"cn":"妈妈做了米饭和菜。","pinyin":"Māma zuòle mǐfàn hé cài.","vn":"Mẹ đã nấu cơm và món ăn."}]},{"hanzi":"怎么","pinyin":"zěnme","pos":"đt.","vn":"như thế nào, làm sao, bằng cách nào","examples":[{"cn":"这个字怎么写？","pinyin":"Zhège zì zěnme xiě?","vn":"Chữ này viết như thế nào?"},{"cn":"你怎么去超市？","pinyin":"Nǐ zěnme qù chāoshì?","vn":"Bạn đi siêu thị bằng cách nào?"},{"cn":"你今天怎么了？","pinyin":"Nǐ jīntiān zěnme le?","vn":"Hôm nay bạn làm sao vậy?"}]},{"hanzi":"坐","pinyin":"zuò","pos":"dgt.","vn":"đi (bằng phương tiện), ngồi","examples":[{"cn":"我坐出租车去。","pinyin":"Wǒ zuò chūzūchē qù.","vn":"Tôi đi bằng taxi."},{"cn":"请坐。","pinyin":"Qǐng zuò.","vn":"Mời ngồi."},{"cn":"我们坐在那边吧。","pinyin":"Wǒmen zuò zài nàbiān ba.","vn":"Chúng ta ngồi ở đằng kia đi."}]},{"hanzi":"出租车","pinyin":"chūzūchē","pos":"dt.","vn":"xe taxi","examples":[{"cn":"我坐出租车去上班。","pinyin":"Wǒ zuò chūzūchē qù shàngbān.","vn":"Tôi đi làm bằng taxi."},{"cn":"我们坐出租车去超市吧。","pinyin":"Wǒmen zuò chūzūchē qù chāoshì ba.","vn":"Chúng ta đi taxi đến siêu thị nhé."},{"cn":"那边有出租车。","pinyin":"Nàbiān yǒu chūzūchē.","vn":"Đằng kia có taxi."}]},{"hanzi":"西安饭店","pinyin":"Xī'ān Fàndiàn","pos":"danh từ riêng","vn":"Nhà hàng Tây An","examples":[{"cn":"我们去西安饭店吃饭吧。","pinyin":"Wǒmen qù Xī'ān Fàndiàn chīfàn ba.","vn":"Chúng ta đến Nhà hàng Tây An ăn cơm nhé."},{"cn":"西安饭店的饺子非常好吃。","pinyin":"Xī'ān Fàndiàn de jiǎozi fēicháng hǎochī.","vn":"Sủi cảo ở Nhà hàng Tây An rất ngon."},{"cn":"西安饭店在那边。","pinyin":"Xī'ān Fàndiàn zài nàbiān.","vn":"Nhà hàng Tây An ở đằng kia."}]}],"grammar":[{"title":"能愿动词\"想\" Modal Verb \"想\"","explanation_vn":"Động từ năng nguyện \"想\" đặt trước động từ, biểu thị mong muốn, dự định.","examples":[{"cn":"我想去超市。","pinyin":"Wǒ xiǎng qù chāoshì.","vn":"Tôi muốn đi siêu thị."},{"cn":"我哥哥不想休息。","pinyin":"Wǒ gēge bù xiǎng xiūxi.","vn":"Anh trai tôi không muốn nghỉ ngơi."}]},{"title":"连动句（1） Serial Verb Sentences (1)","explanation_vn":"Vị ngữ của câu liên động do hai hoặc nhiều cụm động từ cấu thành. Câu liên động thường biểu thị hai ý nghĩa: (1) biểu thị mục đích của hành động; (2) biểu thị cách thức của hành động.","examples":[{"cn":"我想去超市买东西。","pinyin":"Wǒ xiǎng qù chāoshì mǎi dōngxi.","vn":"Tôi muốn đi siêu thị mua đồ."},{"cn":"我们去西安饭店吃晚饭。","pinyin":"Wǒmen qù Xī'ān Fàndiàn chī wǎnfàn.","vn":"Chúng tôi đi Nhà hàng Tây An ăn tối."},{"cn":"我们坐出租车去西安饭店。","pinyin":"Wǒmen zuò chūzūchē qù Xī'ān Fàndiàn.","vn":"Chúng tôi đi taxi đến Nhà hàng Tây An."},{"cn":"她坐出租车去超市。","pinyin":"Tā zuò chūzūchē qù chāoshì.","vn":"Cô ấy đi taxi đến siêu thị."}]},{"title":"疑问代词\"怎么\" Interrogative Pronoun \"怎么\"","explanation_vn":"Đại từ nghi vấn \"怎么\" đặt trước động từ, dùng để hỏi về cách thức.","examples":[{"cn":"我们怎么去？","pinyin":"Wǒmen zěnme qù?","vn":"Chúng ta đi bằng cách nào?"},{"cn":"她怎么去超市？","pinyin":"Tā zěnme qù chāoshì?","vn":"Cô ấy đi siêu thị bằng cách nào?"}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"李文","cn":"家月，你的手机号是多少？","pinyin":"Jiāyuè, nǐ de shǒujīhào shì duōshao?"},{"speaker":"白家月","cn":"我的手机号是+33 601493190。","pinyin":"Wǒ de shǒujīhào shì sān sān liù líng yāo sì jiǔ sān yāo jiǔ líng."},{"speaker":"李文","cn":"我的手机号是+86 13552721160。","pinyin":"Wǒ de shǒujīhào shì bā liù yāo sān wǔ wǔ èr qī èr yāo yāo liù líng."},{"speaker":"白家月","cn":"好的。","pinyin":"Hǎo de."}],"translation_vn":"Lý Văn: Gia Nguyệt, số điện thoại di động của bạn là bao nhiêu?\nBạch Gia Nguyệt: Số điện thoại di động của tôi là +33 601493190.\nLý Văn: Số điện thoại di động của tôi là +86 13552721160.\nBạch Gia Nguyệt: Được rồi.","audio_dialogue":"6-1.mp3","audio_vocab":"6-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"陈天中","cn":"家月，明天你去哪儿？","pinyin":"Jiāyuè, míngtiān nǐ qù nǎr?"},{"speaker":"白家月","cn":"我想去超市买东西。","pinyin":"Wǒ xiǎng qù chāoshì mǎi dōngxi."},{"speaker":"陈天中","cn":"你去超市买什么？","pinyin":"Nǐ qù chāoshì mǎi shénme?"},{"speaker":"白家月","cn":"我想买些牛奶。","pinyin":"Wǒ xiǎng mǎi xiē niúnǎi."}],"translation_vn":"Trần Thiên Trung: Gia Nguyệt, ngày mai bạn đi đâu?\nBạch Gia Nguyệt: Tôi muốn đi siêu thị mua đồ.\nTrần Thiên Trung: Bạn đi siêu thị mua gì?\nBạch Gia Nguyệt: Tôi muốn mua một ít sữa.","audio_dialogue":"6-3.mp3","audio_vocab":"6-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"星期天我们去哪儿吃晚饭？","pinyin":"Xīngqītiān wǒmen qù nǎr chī wǎnfàn?"},{"speaker":"刘明","cn":"我还想去西安饭店。","pinyin":"Wǒ hái xiǎng qù Xī'ān Fàndiàn."},{"speaker":"刘小雪","cn":"那边的包子非常好吃，我想吃包子。","pinyin":"Nàbiān de bāozi fēicháng hǎochī, wǒ xiǎng chī bāozi."},{"speaker":"刘小明","cn":"妈妈，我想吃米饭，不想吃包子。","pinyin":"Māma, wǒ xiǎng chī mǐfàn, bù xiǎng chī bāozi."},{"speaker":"王一雪","cn":"好的。我们怎么去？","pinyin":"Hǎo de. Wǒmen zěnme qù?"},{"speaker":"刘明","cn":"坐出租车去。","pinyin":"Zuò chūzūchē qù."}],"translation_vn":"Vương Nhất Tuyết: Chủ nhật chúng ta đi đâu ăn tối?\nLưu Minh: Anh vẫn muốn đi Nhà hàng Tây An.\nLưu Tiểu Tuyết: Bánh bao ở đó rất ngon, con muốn ăn bánh bao.\nLưu Tiểu Minh: Mẹ ơi, con muốn ăn cơm, không muốn ăn bánh bao.\nVương Nhất Tuyết: Được rồi. Chúng ta đi bằng gì?\nLưu Minh: Đi taxi.","audio_dialogue":"6-5.mp3","audio_vocab":"6-6.mp3"}]},{"id":7,"title_cn":"我晚上六点半下班","title_pinyin":"Wǒ wǎnshang liù diǎn bàn xiàbān","title_vn":"Tôi tan làm lúc sáu giờ rưỡi tối","goals":["Có thể nghe hiểu và miêu tả thời gian xảy ra sự việc.","Nắm vững cách dùng trợ từ ngữ khí \"吧\" (1) để diễn đạt đề nghị, bàn bạc, v.v.","Nắm vững cách dùng trợ từ ngữ khí \"呢\" (2) để diễn đạt sự việc đã được xác nhận.","Nắm vững vị trí của phó từ, từ ngữ chỉ thời gian khi làm trạng ngữ."],"vocab":[{"hanzi":"现在","pinyin":"xiànzài","pos":"dt.","vn":"hiện nay, bây giờ","examples":[{"cn":"现在几点?","pinyin":"Xiànzài jǐ diǎn?","vn":"Bây giờ mấy giờ?"},{"cn":"我现在很忙。","pinyin":"Wǒ xiànzài hěn máng.","vn":"Bây giờ tôi rất bận."},{"cn":"现在是几月?","pinyin":"Xiànzài shì jǐ yuè?","vn":"Bây giờ là tháng mấy?"}]},{"hanzi":"点","pinyin":"diǎn","pos":"lượng.","vn":"giờ","examples":[{"cn":"现在三点。","pinyin":"Xiànzài sān diǎn.","vn":"Bây giờ là 3 giờ."},{"cn":"我们八点见。","pinyin":"Wǒmen bā diǎn jiàn.","vn":"Chúng ta gặp nhau lúc 8 giờ."},{"cn":"现在几点了?","pinyin":"Xiànzài jǐ diǎn le?","vn":"Bây giờ mấy giờ rồi?"}]},{"hanzi":"早上","pinyin":"zǎoshang","pos":"dt.","vn":"buổi sáng sớm","examples":[{"cn":"早上好!","pinyin":"Zǎoshang hǎo!","vn":"Chào buổi sáng!"},{"cn":"我早上七点起床。","pinyin":"Wǒ zǎoshang qī diǎn qǐchuáng.","vn":"Tôi dậy lúc 7 giờ sáng."},{"cn":"他早上不喝水。","pinyin":"Tā zǎoshang bù hē shuǐ.","vn":"Buổi sáng anh ấy không uống nước."}]},{"hanzi":"上午","pinyin":"shàngwǔ","pos":"dt.","vn":"buổi sáng","examples":[{"cn":"上午我有课。","pinyin":"Shàngwǔ wǒ yǒu kè.","vn":"Buổi sáng tôi có tiết học."},{"cn":"他上午去医院。","pinyin":"Tā shàngwǔ qù yīyuàn.","vn":"Buổi sáng anh ấy đi bệnh viện."},{"cn":"上午九点上班。","pinyin":"Shàngwǔ jiǔ diǎn shàngbān.","vn":"9 giờ sáng đi làm."}]},{"hanzi":"分","pinyin":"fēn","pos":"lượng.","vn":"phút","examples":[{"cn":"现在三点五分。","pinyin":"Xiànzài sān diǎn wǔ fēn.","vn":"Bây giờ là 3 giờ 5 phút."},{"cn":"八点十分见。","pinyin":"Bā diǎn shí fēn jiàn.","vn":"Gặp lúc 8 giờ 10 phút."},{"cn":"现在两点二十分。","pinyin":"Xiànzài liǎng diǎn èrshí fēn.","vn":"Bây giờ là 2 giờ 20 phút."}]},{"hanzi":"课","pinyin":"kè","pos":"dt.","vn":"tiết học; bài học","examples":[{"cn":"我今天有三节课。","pinyin":"Wǒ jīntiān yǒu sān jié kè.","vn":"Hôm nay tôi có 3 tiết học."},{"cn":"这节课很有意思。","pinyin":"Zhè jié kè hěn yǒu yìsi.","vn":"Tiết học này rất thú vị."},{"cn":"下午没有课。","pinyin":"Xiàwǔ méiyǒu kè.","vn":"Buổi chiều không có tiết học."}]},{"hanzi":"下午","pinyin":"xiàwǔ","pos":"dt.","vn":"buổi chiều","examples":[{"cn":"下午我们见。","pinyin":"Xiàwǔ wǒmen jiàn.","vn":"Chiều chúng ta gặp nhau."},{"cn":"他下午去书店。","pinyin":"Tā xiàwǔ qù shūdiàn.","vn":"Chiều anh ấy đi hiệu sách."},{"cn":"下午三点上课。","pinyin":"Xiàwǔ sān diǎn shàngkè.","vn":"3 giờ chiều vào học."}]},{"hanzi":"见","pinyin":"jiàn","pos":"dgt.","vn":"gặp","examples":[{"cn":"我们明天见。","pinyin":"Wǒmen míngtiān jiàn.","vn":"Mai chúng ta gặp nhau."},{"cn":"很高兴见到你。","pinyin":"Hěn gāoxìng jiàn dào nǐ.","vn":"Rất vui được gặp bạn."},{"cn":"晚上八点见。","pinyin":"Wǎnshang bā diǎn jiàn.","vn":"Gặp lúc 8 giờ tối."}]},{"hanzi":"吧","pinyin":"ba","pos":"trợ.","vn":"trợ từ ngữ khí biểu thị đề nghị, bàn bạc, khuyên bảo, yêu cầu","examples":[{"cn":"我们走吧。","pinyin":"Wǒmen zǒu ba.","vn":"Chúng ta đi thôi."},{"cn":"你看吧。","pinyin":"Nǐ kàn ba.","vn":"Bạn xem đi."},{"cn":"吃饭吧!","pinyin":"Chīfàn ba!","vn":"Ăn cơm thôi!"}]},{"hanzi":"电影院","pinyin":"diànyǐngyuàn","pos":"dt.","vn":"rạp chiếu phim","examples":[{"cn":"我们去电影院吧。","pinyin":"Wǒmen qù diànyǐngyuàn ba.","vn":"Chúng ta đi rạp chiếu phim đi."},{"cn":"电影院在哪儿?","pinyin":"Diànyǐngyuàn zài nǎr?","vn":"Rạp chiếu phim ở đâu?"},{"cn":"电影院里人很多。","pinyin":"Diànyǐngyuàn lǐ rén hěn duō.","vn":"Trong rạp chiếu phim rất đông người."}]},{"hanzi":"看","pinyin":"kàn","pos":"dgt.","vn":"xem; nhìn; đọc","examples":[{"cn":"我喜欢看书。","pinyin":"Wǒ xǐhuan kàn shū.","vn":"Tôi thích đọc sách."},{"cn":"你看什么?","pinyin":"Nǐ kàn shénme?","vn":"Bạn đang xem gì?"},{"cn":"我们去看电影。","pinyin":"Wǒmen qù kàn diànyǐng.","vn":"Chúng ta đi xem phim."}]},{"hanzi":"电影","pinyin":"diànyǐng","pos":"dt.","vn":"phim","examples":[{"cn":"这个电影很好看。","pinyin":"Zhège diànyǐng hěn hǎokàn.","vn":"Bộ phim này rất hay."},{"cn":"你喜欢看电影吗?","pinyin":"Nǐ xǐhuan kàn diànyǐng ma?","vn":"Bạn có thích xem phim không?"},{"cn":"我们晚上看电影。","pinyin":"Wǒmen wǎnshang kàn diànyǐng.","vn":"Tối nay chúng ta xem phim."}]},{"hanzi":"事","pinyin":"shì","pos":"dt.","vn":"việc, chuyện","examples":[{"cn":"你有事吗?","pinyin":"Nǐ yǒu shì ma?","vn":"Bạn có việc gì không?"},{"cn":"我今天没有事。","pinyin":"Wǒ jīntiān méiyǒu shì.","vn":"Hôm nay tôi không có việc gì."},{"cn":"这是我的事。","pinyin":"Zhè shì wǒ de shì.","vn":"Đây là việc của tôi."}]},{"hanzi":"上课","pinyin":"shàngkè","pos":"dgt.","vn":"lên lớp, học","examples":[{"cn":"我们九点上课。","pinyin":"Wǒmen jiǔ diǎn shàngkè.","vn":"Chúng tôi vào học lúc 9 giờ."},{"cn":"他正在上课。","pinyin":"Tā zhèngzài shàngkè.","vn":"Anh ấy đang học."},{"cn":"快上课了。","pinyin":"Kuài shàngkè le.","vn":"Sắp vào học rồi."}]},{"hanzi":"呢","pinyin":"ne","pos":"trợ.","vn":"trợ từ ngữ khí xác nhận sự việc","examples":[{"cn":"我很好,你呢?","pinyin":"Wǒ hěn hǎo, nǐ ne?","vn":"Tôi khỏe, còn bạn thì sao?"},{"cn":"他在哪儿呢?","pinyin":"Tā zài nǎr ne?","vn":"Anh ấy đang ở đâu nhỉ?"},{"cn":"我的书呢?","pinyin":"Wǒ de shū ne?","vn":"Sách của tôi đâu rồi?"}]},{"hanzi":"半","pinyin":"bàn","pos":"số.","vn":"rưỡi, nửa","examples":[{"cn":"现在三点半。","pinyin":"Xiànzài sān diǎn bàn.","vn":"Bây giờ là 3 giờ rưỡi."},{"cn":"我只吃了一半。","pinyin":"Wǒ zhǐ chīle yíbàn.","vn":"Tôi chỉ ăn một nửa."},{"cn":"八点半见。","pinyin":"Bā diǎn bàn jiàn.","vn":"Gặp lúc 8 giờ rưỡi."}]},{"hanzi":"下课","pinyin":"xiàkè","pos":"dgt.","vn":"tan học, hết tiết","examples":[{"cn":"我们十二点下课。","pinyin":"Wǒmen shí'èr diǎn xiàkè.","vn":"Chúng tôi tan học lúc 12 giờ."},{"cn":"下课了!","pinyin":"Xiàkè le!","vn":"Tan học rồi!"},{"cn":"下课以后我们去吃饭。","pinyin":"Xiàkè yǐhòu wǒmen qù chīfàn.","vn":"Tan học xong chúng ta đi ăn cơm."}]},{"hanzi":"在","pinyin":"zài","pos":"dgt.","vn":"ở, tại","examples":[{"cn":"我在家。","pinyin":"Wǒ zài jiā.","vn":"Tôi đang ở nhà."},{"cn":"他在学校。","pinyin":"Tā zài xuéxiào.","vn":"Anh ấy đang ở trường."},{"cn":"你在哪儿?","pinyin":"Nǐ zài nǎr?","vn":"Bạn đang ở đâu?"}]},{"hanzi":"家","pinyin":"jiā","pos":"dt.","vn":"nhà","examples":[{"cn":"我家很大。","pinyin":"Wǒ jiā hěn dà.","vn":"Nhà tôi rất to."},{"cn":"我回家了。","pinyin":"Wǒ huí jiā le.","vn":"Tôi về nhà rồi."},{"cn":"你家在哪儿?","pinyin":"Nǐ jiā zài nǎr?","vn":"Nhà bạn ở đâu?"}]},{"hanzi":"里","pinyin":"lǐ","pos":"dt.","vn":"bên trong, trong","examples":[{"cn":"书在包里。","pinyin":"Shū zài bāo lǐ.","vn":"Sách ở trong cặp."},{"cn":"家里有五个人。","pinyin":"Jiā lǐ yǒu wǔ gè rén.","vn":"Trong nhà có 5 người."},{"cn":"房间里很干净。","pinyin":"Fángjiān lǐ hěn gānjìng.","vn":"Trong phòng rất sạch sẽ."}]},{"hanzi":"晚上","pinyin":"wǎnshang","pos":"dt.","vn":"buổi tối","examples":[{"cn":"晚上好!","pinyin":"Wǎnshang hǎo!","vn":"Chào buổi tối!"},{"cn":"我晚上七点吃饭。","pinyin":"Wǒ wǎnshang qī diǎn chīfàn.","vn":"Tôi ăn cơm lúc 7 giờ tối."},{"cn":"晚上我们看电影。","pinyin":"Wǎnshang wǒmen kàn diànyǐng.","vn":"Tối nay chúng ta xem phim."}]},{"hanzi":"医院","pinyin":"yīyuàn","pos":"dt.","vn":"bệnh viện","examples":[{"cn":"他在医院工作。","pinyin":"Tā zài yīyuàn gōngzuò.","vn":"Anh ấy làm việc ở bệnh viện."},{"cn":"医院在前边。","pinyin":"Yīyuàn zài qiánbian.","vn":"Bệnh viện ở phía trước."},{"cn":"我去医院看病。","pinyin":"Wǒ qù yīyuàn kànbìng.","vn":"Tôi đi khám bệnh ở bệnh viện."}]},{"hanzi":"上班","pinyin":"shàngbān","pos":"dgt.","vn":"đi làm","examples":[{"cn":"我八点上班。","pinyin":"Wǒ bā diǎn shàngbān.","vn":"Tôi đi làm lúc 8 giờ."},{"cn":"他每天上班。","pinyin":"Tā měitiān shàngbān.","vn":"Anh ấy ngày nào cũng đi làm."},{"cn":"你几点上班?","pinyin":"Nǐ jǐ diǎn shàngbān?","vn":"Mấy giờ bạn đi làm?"}]},{"hanzi":"店","pinyin":"diàn","pos":"dt.","vn":"cửa hàng","examples":[{"cn":"那个店很好。","pinyin":"Nàge diàn hěn hǎo.","vn":"Cửa hàng đó rất tốt."},{"cn":"店里人很多。","pinyin":"Diàn lǐ rén hěn duō.","vn":"Trong cửa hàng rất đông người."},{"cn":"这是我家的店。","pinyin":"Zhè shì wǒ jiā de diàn.","vn":"Đây là cửa hàng nhà tôi."}]},{"hanzi":"菜","pinyin":"cài","pos":"dt.","vn":"rau; món ăn","examples":[{"cn":"这个菜很好吃。","pinyin":"Zhège cài hěn hǎochī.","vn":"Món ăn này rất ngon."},{"cn":"妈妈做菜。","pinyin":"Māma zuò cài.","vn":"Mẹ nấu món ăn."},{"cn":"我喜欢吃菜。","pinyin":"Wǒ xǐhuan chī cài.","vn":"Tôi thích ăn rau."}]},{"hanzi":"分钟","pinyin":"fēnzhōng","pos":"lượng.","vn":"phút","examples":[{"cn":"等五分钟。","pinyin":"Děng wǔ fēnzhōng.","vn":"Đợi 5 phút."},{"cn":"我十分钟就到。","pinyin":"Wǒ shí fēnzhōng jiù dào.","vn":"10 phút nữa tôi sẽ đến."},{"cn":"这节课四十分钟。","pinyin":"Zhè jié kè sìshí fēnzhōng.","vn":"Tiết học này 40 phút."}]},{"hanzi":"后","pinyin":"hòu","pos":"dt.","vn":"sau, sau đó","examples":[{"cn":"下课后我们去吃饭。","pinyin":"Xiàkè hòu wǒmen qù chīfàn.","vn":"Tan học xong chúng ta đi ăn cơm."},{"cn":"以后再说。","pinyin":"Yǐhòu zài shuō.","vn":"Sau này nói tiếp."},{"cn":"两天后他回家。","pinyin":"Liǎng tiān hòu tā huí jiā.","vn":"2 ngày nữa anh ấy về nhà."}]}],"grammar":[{"title":"时间的表达（2）","explanation_vn":"Dùng \"点\" và \"分\" để diễn đạt mốc thời gian cụ thể: \"点\" dùng cho giờ chẵn, không phải giờ chẵn thì dùng \"分\" (phút); \"分\" có thể lược bỏ, nhưng khi là \"mười phút\" thì không được lược bỏ \"分\"; khi thời gian dưới mười phút phải đọc \"零\". Ngoài ra, các danh từ chỉ thời gian như \"上午, 中午, 下午, 晚上\" có thể dùng để diễn đạt khoảng thời gian, và có thể đứng trước mốc thời gian cụ thể.","examples":[{"cn":"现在二十一点十分。","pinyin":"Xiànzài èrshíyī diǎn shí fēn.","vn":"Bây giờ là 21 giờ 10 phút."},{"cn":"下午两点半。","pinyin":"Xiàwǔ liǎng diǎn bàn.","vn":"Hai giờ rưỡi chiều."},{"cn":"晚上九点十分。","pinyin":"Wǎnshang jiǔ diǎn shí fēn.","vn":"Chín giờ mười phút tối."}]},{"title":"语气助词“吧”(1)","explanation_vn":"Trong bài này, trợ từ ngữ khí \"吧\" đọc nhẹ (ba), đặt ở cuối câu, biểu thị sự đề nghị, bàn bạc, khuyên bảo hoặc yêu cầu.","examples":[{"cn":"我们下午三点见吧。","pinyin":"Wǒmen xiàwǔ sān diǎn jiàn ba.","vn":"Chúng ta gặp nhau lúc ba giờ chiều nhé."},{"cn":"你去超市买吧。","pinyin":"Nǐ qù chāoshì mǎi ba.","vn":"Bạn đi siêu thị mua đi."},{"cn":"我们去西安饭店吃晚饭吧。","pinyin":"Wǒmen qù Xī'ān Fàndiàn chī wǎnfàn ba.","vn":"Chúng ta đi nhà hàng Tây An ăn tối nhé."}]},{"title":"副词、时间词语作状语的位置","explanation_vn":"Trong tiếng Hán, khi phó từ, từ ngữ chỉ thời gian làm trạng ngữ, thường phải đặt trước động từ hoặc tính từ.","examples":[{"cn":"我不想去。","pinyin":"Wǒ bù xiǎng qù.","vn":"Tôi không muốn đi."},{"cn":"妹妹很高兴。","pinyin":"Mèimei hěn gāoxìng.","vn":"Em gái rất vui."},{"cn":"她上午十点半上课。","pinyin":"Tā shàngwǔ shí diǎn bàn shàngkè.","vn":"Cô ấy mười giờ rưỡi sáng lên lớp."}]},{"title":"语气助词“呢”(2)","explanation_vn":"Trợ từ ngữ khí \"呢\" trong bài này đặt ở cuối câu, biểu thị sự xác nhận một sự việc. Cấu trúc cơ bản: ……呢。","examples":[{"cn":"我明天下午两点还上课呢。","pinyin":"Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne.","vn":"Ngày mai lúc hai giờ chiều tôi vẫn còn phải học đấy."},{"cn":"妹妹会做两个菜呢。","pinyin":"Mèimei huì zuò liǎng gè cài ne.","vn":"Em gái biết nấu hai món ăn đấy."},{"cn":"李文晚上还有事呢。","pinyin":"Lǐ Wén wǎnshang hái yǒu shì ne.","vn":"Lý Văn tối nay vẫn còn việc đấy."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"现在几点？","pinyin":"Xiànzài jǐ diǎn?"},{"speaker":"安妮","cn":"早上八点四十。","pinyin":"Zǎoshang bā diǎn sìshí."},{"speaker":"白家月","cn":"我上午十点十分有课。","pinyin":"Wǒ shàngwǔ shí diǎn shí fēn yǒu kè."},{"speaker":"安妮","cn":"好的，我们下午两点见吧。","pinyin":"Hǎo de, wǒmen xiàwǔ liǎng diǎn jiàn ba."}],"translation_vn":"Bạch Gia Nguyệt: Bây giờ là mấy giờ?\nAnnie: Tám giờ bốn mươi sáng.\nBạch Gia Nguyệt: Tôi có tiết học lúc mười giờ mười phút sáng.\nAnnie: Được, chiều chúng ta gặp nhau lúc hai giờ nhé.","audio_dialogue":"7-1.mp3","audio_vocab":"7-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"李文","cn":"下午我想去电影院看电影，你去吗？","pinyin":"Xiàwǔ wǒ xiǎng qù diànyǐngyuàn kàn diànyǐng, nǐ qù ma?"},{"speaker":"白家月","cn":"我不想去，下午还有事。","pinyin":"Wǒ bù xiǎng qù, xiàwǔ hái yǒu shì."},{"speaker":"李文","cn":"好的。明天呢？","pinyin":"Hǎo de. Míngtiān ne?"},{"speaker":"白家月","cn":"我明天下午两点还上课呢，四点半下课。","pinyin":"Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne, sì diǎn bàn xiàkè."}],"translation_vn":"Lý Văn: Chiều nay tôi muốn đi rạp xem phim, bạn đi không?\nBạch Gia Nguyệt: Tôi không muốn đi, chiều nay tôi còn có việc.\nLý Văn: Được rồi. Thế ngày mai thì sao?\nBạch Gia Nguyệt: Ngày mai chiều tôi vẫn còn phải học đến hai giờ, bốn giờ rưỡi mới tan học.","audio_dialogue":"7-3.mp3","audio_vocab":"7-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"喂，你在哪儿呢？","pinyin":"Wèi, nǐ zài nǎr ne?"},{"speaker":"刘明","cn":"我在家里呢。","pinyin":"Wǒ zài jiā li ne."},{"speaker":"王一雪","cn":"我晚上六点半下班。","pinyin":"Wǒ wǎnshang liù diǎn bàn xiàbān."},{"speaker":"刘明","cn":"我八点去医院上班。","pinyin":"Wǒ bā diǎn qù yīyuàn shàngbān."},{"speaker":"王一雪","cn":"好的，你去店里买些菜吧。","pinyin":"Hǎo de, nǐ qù diàn li mǎi xiē cài ba."},{"speaker":"刘明","cn":"好，我十分钟后去。","pinyin":"Hǎo, wǒ shí fēnzhōng hòu qù."}],"translation_vn":"Vương Nhất Tuyết: Alo, anh đang ở đâu thế?\nLưu Minh: Anh đang ở nhà.\nVương Nhất Tuyết: Tối nay em tan làm lúc sáu giờ rưỡi.\nLưu Minh: Anh đi làm ở bệnh viện lúc tám giờ.\nVương Nhất Tuyết: Được rồi, anh ghé cửa hàng mua ít rau nhé.\nLưu Minh: Được, mười phút nữa anh đi.","audio_dialogue":"7-5.mp3","audio_vocab":"7-6.mp3"}]},{"id":8,"title_cn":"我爸爸也在医院工作","title_pinyin":"Wǒ bàba yě zài yīyuàn gōngzuò","title_vn":"Bố tôi cũng làm việc ở bệnh viện","goals":["Có thể nghe hiểu và miêu tả thông tin về nơi chốn, vị trí.","Nắm vững cách dùng giới từ \"在\" để biểu thị phương vị.","Nắm vững cách dùng động từ năng nguyện \"能\"."],"vocab":[{"hanzi":"房间","pinyin":"fángjiān","pos":"dt.","vn":"phòng","examples":[{"cn":"我的房间很小。","pinyin":"Wǒ de fángjiān hěn xiǎo.","vn":"Phòng tôi rất nhỏ."},{"cn":"房间里有桌子。","pinyin":"Fángjiān lǐ yǒu zhuōzi.","vn":"Trong phòng có cái bàn."},{"cn":"这个房间很干净。","pinyin":"Zhège fángjiān hěn gānjìng.","vn":"Phòng này rất sạch sẽ."}]},{"hanzi":"外","pinyin":"wài","pos":"dt.","vn":"ngoài, bên ngoài","examples":[{"cn":"猫在门外。","pinyin":"Māo zài mén wài.","vn":"Con mèo ở ngoài cửa."},{"cn":"外边很冷。","pinyin":"Wàibian hěn lěng.","vn":"Bên ngoài trời rất lạnh."},{"cn":"他在屋外。","pinyin":"Tā zài wū wài.","vn":"Anh ấy ở ngoài nhà."}]},{"hanzi":"只","pinyin":"zhī","pos":"lượng.","vn":"con (lượng từ chỉ động vật)","examples":[{"cn":"一只猫。","pinyin":"Yì zhī māo.","vn":"Một con mèo."},{"cn":"我家有两只狗。","pinyin":"Wǒ jiā yǒu liǎng zhī gǒu.","vn":"Nhà tôi có 2 con chó."},{"cn":"那只猫很小。","pinyin":"Nà zhī māo hěn xiǎo.","vn":"Con mèo đó rất nhỏ."}]},{"hanzi":"小","pinyin":"xiǎo","pos":"tt.","vn":"nhỏ, bé","examples":[{"cn":"这只猫很小。","pinyin":"Zhè zhī māo hěn xiǎo.","vn":"Con mèo này rất nhỏ."},{"cn":"我的房间很小。","pinyin":"Wǒ de fángjiān hěn xiǎo.","vn":"Phòng tôi rất nhỏ."},{"cn":"这个杯子很小。","pinyin":"Zhège bēizi hěn xiǎo.","vn":"Cái cốc này rất nhỏ."}]},{"hanzi":"猫","pinyin":"māo","pos":"dt.","vn":"mèo","examples":[{"cn":"我家有一只猫。","pinyin":"Wǒ jiā yǒu yì zhī māo.","vn":"Nhà tôi có một con mèo."},{"cn":"猫在桌子下边。","pinyin":"Māo zài zhuōzi xiàbian.","vn":"Con mèo ở dưới bàn."},{"cn":"这只猫很漂亮。","pinyin":"Zhè zhī māo hěn piàoliang.","vn":"Con mèo này rất xinh đẹp."}]},{"hanzi":"没","pinyin":"méi","pos":"phó.","vn":"không, chưa","examples":[{"cn":"我没有钱。","pinyin":"Wǒ méiyǒu qián.","vn":"Tôi không có tiền."},{"cn":"他没去学校。","pinyin":"Tā méi qù xuéxiào.","vn":"Anh ấy chưa đi học."},{"cn":"我没看见他。","pinyin":"Wǒ méi kànjiàn tā.","vn":"Tôi không nhìn thấy anh ấy."}]},{"hanzi":"看见","pinyin":"kànjiàn","pos":"dgt.","vn":"nhìn thấy","examples":[{"cn":"我看见他了。","pinyin":"Wǒ kànjiàn tā le.","vn":"Tôi đã nhìn thấy anh ấy."},{"cn":"你看见我的书了吗?","pinyin":"Nǐ kànjiàn wǒ de shū le ma?","vn":"Bạn có thấy sách của tôi không?"},{"cn":"我没看见猫。","pinyin":"Wǒ méi kànjiàn māo.","vn":"Tôi không nhìn thấy con mèo."}]},{"hanzi":"桌子","pinyin":"zhuōzi","pos":"dt.","vn":"cái bàn","examples":[{"cn":"书在桌子上。","pinyin":"Shū zài zhuōzi shàng.","vn":"Sách ở trên bàn."},{"cn":"这张桌子很大。","pinyin":"Zhè zhāng zhuōzi hěn dà.","vn":"Cái bàn này rất to."},{"cn":"猫在桌子下边。","pinyin":"Māo zài zhuōzi xiàbian.","vn":"Con mèo ở dưới bàn."}]},{"hanzi":"下","pinyin":"xià","pos":"dt.","vn":"dưới, phía dưới","examples":[{"cn":"书在桌子下边。","pinyin":"Shū zài zhuōzi xiàbian.","vn":"Sách ở dưới bàn."},{"cn":"猫在床下。","pinyin":"Māo zài chuáng xià.","vn":"Con mèo ở dưới giường."},{"cn":"他在楼下。","pinyin":"Tā zài lóu xià.","vn":"Anh ấy ở tầng dưới."}]},{"hanzi":"漂亮","pinyin":"piàoliang","pos":"tt.","vn":"xinh đẹp","examples":[{"cn":"她很漂亮。","pinyin":"Tā hěn piàoliang.","vn":"Cô ấy rất xinh đẹp."},{"cn":"这件衣服很漂亮。","pinyin":"Zhè jiàn yīfu hěn piàoliang.","vn":"Chiếc áo này rất đẹp."},{"cn":"这个房间很漂亮。","pinyin":"Zhège fángjiān hěn piàoliang.","vn":"Căn phòng này rất đẹp."}]},{"hanzi":"在","pinyin":"zài","pos":"giới.","vn":"ở, tại","examples":[{"cn":"我在学校学习。","pinyin":"Wǒ zài xuéxiào xuéxí.","vn":"Tôi học tập ở trường."},{"cn":"他在家吃饭。","pinyin":"Tā zài jiā chīfàn.","vn":"Anh ấy ăn cơm ở nhà."},{"cn":"猫在桌子下边。","pinyin":"Māo zài zhuōzi xiàbian.","vn":"Con mèo ở dưới bàn."}]},{"hanzi":"学校","pinyin":"xuéxiào","pos":"dt.","vn":"trường học","examples":[{"cn":"我的学校很大。","pinyin":"Wǒ de xuéxiào hěn dà.","vn":"Trường học của tôi rất to."},{"cn":"他在学校工作。","pinyin":"Tā zài xuéxiào gōngzuò.","vn":"Anh ấy làm việc ở trường."},{"cn":"学校前边有书店。","pinyin":"Xuéxiào qiánbian yǒu shūdiàn.","vn":"Trước trường học có hiệu sách."}]},{"hanzi":"书店","pinyin":"shūdiàn","pos":"dt.","vn":"hiệu sách","examples":[{"cn":"书店在学校前边。","pinyin":"Shūdiàn zài xuéxiào qiánbian.","vn":"Hiệu sách ở trước trường học."},{"cn":"我们去书店吧。","pinyin":"Wǒmen qù shūdiàn ba.","vn":"Chúng ta đi hiệu sách đi."},{"cn":"书店里有很多书。","pinyin":"Shūdiàn lǐ yǒu hěn duō shū.","vn":"Trong hiệu sách có rất nhiều sách."}]},{"hanzi":"前","pinyin":"qián","pos":"dt.","vn":"trước, phía trước","examples":[{"cn":"医院在前边。","pinyin":"Yīyuàn zài qiánbian.","vn":"Bệnh viện ở phía trước."},{"cn":"书店在学校前边。","pinyin":"Shūdiàn zài xuéxiào qiánbian.","vn":"Hiệu sách ở trước trường học."},{"cn":"他在我前边。","pinyin":"Tā zài wǒ qiánbian.","vn":"Anh ấy ở phía trước tôi."}]},{"hanzi":"能","pinyin":"néng","pos":"đtnn.","vn":"có thể","examples":[{"cn":"我能看见你。","pinyin":"Wǒ néng kànjiàn nǐ.","vn":"Tôi có thể nhìn thấy bạn."},{"cn":"你能来吗?","pinyin":"Nǐ néng lái ma?","vn":"Bạn có thể đến không?"},{"cn":"他不能上班。","pinyin":"Tā bù néng shàngbān.","vn":"Anh ấy không thể đi làm."}]},{"hanzi":"到","pinyin":"dào","pos":"dgt.","vn":"đến, tới","examples":[{"cn":"我到家了。","pinyin":"Wǒ dào jiā le.","vn":"Tôi đã về đến nhà."},{"cn":"他几点到?","pinyin":"Tā jǐ diǎn dào?","vn":"Mấy giờ anh ấy đến?"},{"cn":"我十分钟就到。","pinyin":"Wǒ shí fēnzhōng jiù dào.","vn":"10 phút nữa tôi sẽ đến."}]},{"hanzi":"午饭","pinyin":"wǔfàn","pos":"dt.","vn":"bữa trưa","examples":[{"cn":"我们一起吃午饭吧。","pinyin":"Wǒmen yìqǐ chī wǔfàn ba.","vn":"Chúng ta cùng ăn trưa đi."},{"cn":"午饭很好吃。","pinyin":"Wǔfàn hěn hǎochī.","vn":"Bữa trưa rất ngon."},{"cn":"你吃午饭了吗?","pinyin":"Nǐ chī wǔfàn le ma?","vn":"Bạn ăn trưa chưa?"}]},{"hanzi":"饭","pinyin":"fàn","pos":"dt.","vn":"cơm, bữa ăn","examples":[{"cn":"我吃饭了。","pinyin":"Wǒ chīfàn le.","vn":"Tôi ăn cơm rồi."},{"cn":"妈妈做饭。","pinyin":"Māma zuòfàn.","vn":"Mẹ nấu cơm."},{"cn":"饭很好吃。","pinyin":"Fàn hěn hǎochī.","vn":"Cơm rất ngon."}]},{"hanzi":"大","pinyin":"dà","pos":"tt.","vn":"to, lớn","examples":[{"cn":"这个房间很大。","pinyin":"Zhège fángjiān hěn dà.","vn":"Căn phòng này rất to."},{"cn":"他的狗很大。","pinyin":"Tā de gǒu hěn dà.","vn":"Con chó của anh ấy rất to."},{"cn":"学校很大。","pinyin":"Xuéxiào hěn dà.","vn":"Trường học rất to."}]},{"hanzi":"病人","pinyin":"bìngrén","pos":"dt.","vn":"bệnh nhân","examples":[{"cn":"医院里有很多病人。","pinyin":"Yīyuàn lǐ yǒu hěn duō bìngrén.","vn":"Trong bệnh viện có rất nhiều bệnh nhân."},{"cn":"医生在看病人。","pinyin":"Yīshēng zài kàn bìngrén.","vn":"Bác sĩ đang khám bệnh nhân."},{"cn":"病人在房间里。","pinyin":"Bìngrén zài fángjiān lǐ.","vn":"Bệnh nhân ở trong phòng."}]},{"hanzi":"多","pinyin":"duō","pos":"tt.","vn":"nhiều","examples":[{"cn":"医院里人很多。","pinyin":"Yīyuàn lǐ rén hěn duō.","vn":"Trong bệnh viện rất đông người."},{"cn":"他有很多书。","pinyin":"Tā yǒu hěn duō shū.","vn":"Anh ấy có rất nhiều sách."},{"cn":"这儿病人很多。","pinyin":"Zhèr bìngrén hěn duō.","vn":"Ở đây có rất nhiều bệnh nhân."}]},{"hanzi":"医生","pinyin":"yīshēng","pos":"dt.","vn":"bác sĩ","examples":[{"cn":"他是医生。","pinyin":"Tā shì yīshēng.","vn":"Anh ấy là bác sĩ."},{"cn":"医生在医院工作。","pinyin":"Yīshēng zài yīyuàn gōngzuò.","vn":"Bác sĩ làm việc ở bệnh viện."},{"cn":"我想当医生。","pinyin":"Wǒ xiǎng dāng yīshēng.","vn":"Tôi muốn làm bác sĩ."}]},{"hanzi":"工作","pinyin":"gōngzuò","pos":"dgt.","vn":"làm việc","examples":[{"cn":"我每天工作。","pinyin":"Wǒ měitiān gōngzuò.","vn":"Tôi làm việc mỗi ngày."},{"cn":"你在哪儿工作?","pinyin":"Nǐ zài nǎr gōngzuò?","vn":"Bạn làm việc ở đâu?"},{"cn":"他工作很忙。","pinyin":"Tā gōngzuò hěn máng.","vn":"Anh ấy làm việc rất bận."}]},{"hanzi":"胡医生","pinyin":"Hú yīshēng","pos":"danh từ riêng","vn":"Bác sĩ Hồ","examples":[{"cn":"胡医生,你好!","pinyin":"Hú yīshēng, nǐ hǎo!","vn":"Chào bác sĩ Hồ!"},{"cn":"胡医生在医院工作。","pinyin":"Hú yīshēng zài yīyuàn gōngzuò.","vn":"Bác sĩ Hồ làm việc ở bệnh viện."},{"cn":"这是胡医生。","pinyin":"Zhè shì Hú yīshēng.","vn":"Đây là bác sĩ Hồ."}]}],"grammar":[{"title":"方位词","explanation_vn":"Các từ chỉ phương vị biểu đạt phương hướng, vị trí được học trong tập này gồm: 上, 下, 里, 外, 前, 后, 外边.","examples":[{"cn":"房间里有一只小猫。","pinyin":"Fángjiān li yǒu yì zhī xiǎo māo.","vn":"Trong phòng có một con mèo nhỏ."},{"cn":"我们去书店外吧。","pinyin":"Wǒmen qù shūdiàn wài ba.","vn":"Chúng ta ra ngoài hiệu sách đi."},{"cn":"小雪的手机在桌子上呢。","pinyin":"Xiǎoxuě de shǒujī zài zhuōzi shang ne.","vn":"Điện thoại của Tiểu Tuyết đang ở trên bàn đấy."}]},{"title":"介词“在”","explanation_vn":"Giới từ \"在\" kết hợp với từ ngữ chỉ vị trí, nơi chốn, đứng trước động từ, biểu thị làm việc gì đó ở vị trí, nơi chốn nào.","examples":[{"cn":"我在学校吃午饭。","pinyin":"Wǒ zài xuéxiào chī wǔfàn.","vn":"Tôi ăn trưa ở trường."},{"cn":"他爸爸在医院工作。","pinyin":"Tā bàba zài yīyuàn gōngzuò.","vn":"Bố anh ấy làm việc ở bệnh viện."},{"cn":"你在哪儿买菜？","pinyin":"Nǐ zài nǎr mǎi cài?","vn":"Bạn mua rau ở đâu?"}]},{"title":"能愿动词“能”","explanation_vn":"Động từ năng nguyện \"能\" đứng trước động từ, biểu thị có năng lực, có điều kiện hoặc có khả năng làm việc gì đó.","examples":[{"cn":"下午两点你能到吗？","pinyin":"Xiàwǔ liǎng diǎn nǐ néng dào ma?","vn":"Hai giờ chiều bạn đến được không?"},{"cn":"爸爸能去。","pinyin":"Bàba néng qù.","vn":"Bố có thể đi được."},{"cn":"我不能去学校吃午饭。","pinyin":"Wǒ bù néng qù xuéxiào chī wǔfàn.","vn":"Tôi không thể đến trường ăn trưa được."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"房间外有一只小猫。","pinyin":"Fángjiān wài yǒu yì zhī xiǎo māo."},{"speaker":"陈天中","cn":"我没看见，它在哪儿呢？","pinyin":"Wǒ méi kànjiàn, tā zài nǎr ne?"},{"speaker":"白家月","cn":"它在桌子下呢。","pinyin":"Tā zài zhuōzi xià ne."},{"speaker":"陈天中","cn":"这只小猫真漂亮！","pinyin":"Zhè zhī xiǎo māo zhēn piàoliang!"}],"translation_vn":"Bạch Gia Nguyệt: Ngoài phòng có một con mèo nhỏ.\nTrần Thiên Trung: Tôi không nhìn thấy, nó ở đâu vậy?\nBạch Gia Nguyệt: Nó đang ở dưới bàn kìa.\nTrần Thiên Trung: Con mèo này thật đáng yêu!","audio_dialogue":"8-1.mp3","audio_vocab":"8-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"白家月","cn":"我们在哪儿见呢？","pinyin":"Wǒmen zài nǎr jiàn ne?"},{"speaker":"李文","cn":"在学校书店前见吧。","pinyin":"Zài xuéxiào shūdiàn qián jiàn ba."},{"speaker":"白家月","cn":"好的。下午两点你能到吗？","pinyin":"Hǎo de. Xiàwǔ liǎng diǎn nǐ néng dào ma?"},{"speaker":"李文","cn":"我能到。我在学校吃午饭。","pinyin":"Wǒ néng dào. Wǒ zài xuéxiào chī wǔfàn."}],"translation_vn":"Bạch Gia Nguyệt: Chúng ta gặp nhau ở đâu nhỉ?\nLý Văn: Gặp nhau trước hiệu sách của trường nhé.\nBạch Gia Nguyệt: Được. Hai giờ chiều bạn đến được không?\nLý Văn: Tôi đến được. Tôi ăn trưa ở trường.","audio_dialogue":"8-3.mp3","audio_vocab":"8-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"刘明","cn":"小胡，还没吃饭呢？","pinyin":"Xiǎo Hú, hái méi chī fàn ne?"},{"speaker":"胡医生","cn":"没吃呢。","pinyin":"Méi chī ne."},{"speaker":"刘明","cn":"大医院病人多，医生非常忙。","pinyin":"Dà yīyuàn bìngrén duō, yīshēng fēicháng máng."},{"speaker":"胡医生","cn":"是的。我爸爸也在医院工作，他也非常忙。","pinyin":"Shì de. Wǒ bàba yě zài yīyuàn gōngzuò, tā yě fēicháng máng."},{"speaker":"刘明","cn":"你家有两个医生？","pinyin":"Nǐ jiā yǒu liǎng gè yīshēng?"},{"speaker":"胡医生","cn":"对。","pinyin":"Duì."}],"translation_vn":"Lưu Minh: Tiểu Hồ, vẫn chưa ăn cơm à?\nBác sĩ Hồ: Chưa ăn.\nLưu Minh: Bệnh viện lớn nhiều bệnh nhân, bác sĩ rất bận rộn.\nBác sĩ Hồ: Đúng vậy. Bố tôi cũng làm việc ở bệnh viện, ông ấy cũng rất bận.\nLưu Minh: Nhà bạn có hai bác sĩ à?\nBác sĩ Hồ: Đúng vậy.","audio_dialogue":"8-5.mp3","audio_vocab":"8-6.mp3"}]},{"id":9,"title_cn":"我明天上午在学校学习","title_pinyin":"Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí","title_vn":"Ngày mai sáng tôi học ở trường","goals":["Có thể nghe hiểu và sử dụng \"有/是\" để biểu thị sự tồn tại.","Nắm vững trật tự khi từ ngữ chỉ thời gian và từ ngữ chỉ nơi chốn cùng xuất hiện làm trạng ngữ.","Nắm vững cách dùng \"第\".","Hiểu biết về các hoạt động giải trí của người Trung Quốc hiện đại."],"vocab":[{"hanzi":"前边","pinyin":"qiánbian","pos":"dt.","vn":"phía trước","examples":[{"cn":"学校前边有书店。","pinyin":"Xuéxiào qiánbian yǒu shūdiàn.","vn":"Trước trường học có hiệu sách."},{"cn":"他在我前边。","pinyin":"Tā zài wǒ qiánbian.","vn":"Anh ấy ở phía trước tôi."},{"cn":"前边有一只猫。","pinyin":"Qiánbian yǒu yì zhī māo.","vn":"Phía trước có một con mèo."}]},{"hanzi":"边","pinyin":"bian/biān","pos":"htố.","vn":"bên, phía","examples":[{"cn":"桌子上边有书。","pinyin":"Zhuōzi shàngbian yǒu shū.","vn":"Trên bàn có sách."},{"cn":"猫在桌子下边。","pinyin":"Māo zài zhuōzi xiàbian.","vn":"Con mèo ở dưới bàn."},{"cn":"他在我旁边。","pinyin":"Tā zài wǒ pángbiān.","vn":"Anh ấy ở bên cạnh tôi."}]},{"hanzi":"家","pinyin":"jiā","pos":"lượng.","vn":"lượng từ dùng cho gia đình, cơ sở kinh doanh","examples":[{"cn":"这家店很大。","pinyin":"Zhè jiā diàn hěn dà.","vn":"Cửa hàng này rất to."},{"cn":"那家书店很好。","pinyin":"Nà jiā shūdiàn hěn hǎo.","vn":"Hiệu sách đó rất tốt."},{"cn":"这家医院很大。","pinyin":"Zhè jiā yīyuàn hěn dà.","vn":"Bệnh viện này rất to."}]},{"hanzi":"那个","pinyin":"nàge","pos":"đt.","vn":"cái đó, cái kia","examples":[{"cn":"那个人是谁?","pinyin":"Nàge rén shì shéi?","vn":"Người kia là ai?"},{"cn":"我喜欢那个。","pinyin":"Wǒ xǐhuan nàge.","vn":"Tôi thích cái đó."},{"cn":"那个电影很好看。","pinyin":"Nàge diànyǐng hěn hǎokàn.","vn":"Bộ phim đó rất hay."}]},{"hanzi":"外边","pinyin":"wàibian","pos":"dt.","vn":"bên ngoài","examples":[{"cn":"猫在外边。","pinyin":"Māo zài wàibian.","vn":"Con mèo ở bên ngoài."},{"cn":"外边很冷。","pinyin":"Wàibian hěn lěng.","vn":"Bên ngoài trời lạnh."},{"cn":"朋友在外边等我。","pinyin":"Péngyou zài wàibian děng wǒ.","vn":"Bạn tôi đang đợi ở bên ngoài."}]},{"hanzi":"椅子","pinyin":"yǐzi","pos":"dt.","vn":"cái ghế","examples":[{"cn":"这把椅子很漂亮。","pinyin":"Zhè bǎ yǐzi hěn piàoliang.","vn":"Cái ghế này rất đẹp."},{"cn":"猫在椅子上。","pinyin":"Māo zài yǐzi shàng.","vn":"Con mèo ở trên ghế."},{"cn":"房间里有两把椅子。","pinyin":"Fángjiān lǐ yǒu liǎng bǎ yǐzi.","vn":"Trong phòng có 2 cái ghế."}]},{"hanzi":"上","pinyin":"shang/shàng","pos":"dt.","vn":"trên","examples":[{"cn":"书在桌子上。","pinyin":"Shū zài zhuōzi shàng.","vn":"Sách ở trên bàn."},{"cn":"猫在椅子上。","pinyin":"Māo zài yǐzi shàng.","vn":"Con mèo ở trên ghế."},{"cn":"他在楼上。","pinyin":"Tā zài lóu shàng.","vn":"Anh ấy ở trên tầng."}]},{"hanzi":"本","pinyin":"běn","pos":"lượng.","vn":"quyển, cuốn","examples":[{"cn":"一本书。","pinyin":"Yì běn shū.","vn":"Một quyển sách."},{"cn":"我买了两本书。","pinyin":"Wǒ mǎile liǎng běn shū.","vn":"Tôi đã mua 2 quyển sách."},{"cn":"这本书很好看。","pinyin":"Zhè běn shū hěn hǎokàn.","vn":"Quyển sách này rất hay."}]},{"hanzi":"书","pinyin":"shū","pos":"dt.","vn":"sách","examples":[{"cn":"我喜欢看书。","pinyin":"Wǒ xǐhuan kàn shū.","vn":"Tôi thích đọc sách."},{"cn":"这是我的书。","pinyin":"Zhè shì wǒ de shū.","vn":"Đây là sách của tôi."},{"cn":"书在桌子上。","pinyin":"Shū zài zhuōzi shàng.","vn":"Sách ở trên bàn."}]},{"hanzi":"那","pinyin":"nà","pos":"đt.","vn":"đó, kia","examples":[{"cn":"那是什么?","pinyin":"Nà shì shénme?","vn":"Đó là cái gì?"},{"cn":"那是我的猫。","pinyin":"Nà shì wǒ de māo.","vn":"Đó là con mèo của tôi."},{"cn":"那是他家。","pinyin":"Nà shì tā jiā.","vn":"Đó là nhà anh ấy."}]},{"hanzi":"第","pinyin":"dì","pos":"ttố.","vn":"thứ (tiền tố tạo số thứ tự)","examples":[{"cn":"这是第一本书。","pinyin":"Zhè shì dì-yī běn shū.","vn":"Đây là quyển sách thứ nhất."},{"cn":"他是第一名。","pinyin":"Tā shì dì-yī míng.","vn":"Anh ấy đứng thứ nhất."},{"cn":"今天是第二节课。","pinyin":"Jīntiān shì dì-èr jié kè.","vn":"Hôm nay là tiết học thứ hai."}]},{"hanzi":"学习","pinyin":"xuéxí","pos":"dgt.","vn":"học tập","examples":[{"cn":"我喜欢学习。","pinyin":"Wǒ xǐhuan xuéxí.","vn":"Tôi thích học tập."},{"cn":"他在学校学习。","pinyin":"Tā zài xuéxiào xuéxí.","vn":"Anh ấy học tập ở trường."},{"cn":"我们一起学习吧。","pinyin":"Wǒmen yìqǐ xuéxí ba.","vn":"Chúng ta cùng học tập đi."}]},{"hanzi":"做","pinyin":"zuò","pos":"dgt.","vn":"làm","examples":[{"cn":"你在做什么?","pinyin":"Nǐ zài zuò shénme?","vn":"Bạn đang làm gì?"},{"cn":"妈妈在做菜。","pinyin":"Māma zài zuò cài.","vn":"Mẹ đang nấu món ăn."},{"cn":"我做完了。","pinyin":"Wǒ zuò wán le.","vn":"Tôi làm xong rồi."}]},{"hanzi":"白天","pinyin":"báitiān","pos":"dt.","vn":"ban ngày","examples":[{"cn":"白天我上班。","pinyin":"Báitiān wǒ shàngbān.","vn":"Ban ngày tôi đi làm."},{"cn":"他白天学习,晚上工作。","pinyin":"Tā báitiān xuéxí, wǎnshang gōngzuò.","vn":"Ban ngày anh ấy học, buổi tối làm việc."},{"cn":"白天很热。","pinyin":"Báitiān hěn rè.","vn":"Ban ngày trời rất nóng."}]},{"hanzi":"读书","pinyin":"dúshū","pos":"dgt.","vn":"đọc sách","examples":[{"cn":"我喜欢读书。","pinyin":"Wǒ xǐhuan dúshū.","vn":"Tôi thích đọc sách."},{"cn":"他在家读书。","pinyin":"Tā zài jiā dúshū.","vn":"Anh ấy đọc sách ở nhà."},{"cn":"我们一起读书吧。","pinyin":"Wǒmen yìqǐ dúshū ba.","vn":"Chúng ta cùng đọc sách đi."}]},{"hanzi":"和","pinyin":"hé","pos":"giới.","vn":"với, và","examples":[{"cn":"我和朋友去看电影。","pinyin":"Wǒ hé péngyou qù kàn diànyǐng.","vn":"Tôi và bạn đi xem phim."},{"cn":"我喜欢猫和狗。","pinyin":"Wǒ xǐhuan māo hé gǒu.","vn":"Tôi thích mèo và chó."},{"cn":"他和医生说话。","pinyin":"Tā hé yīshēng shuōhuà.","vn":"Anh ấy nói chuyện với bác sĩ."}]},{"hanzi":"朋友","pinyin":"péngyou","pos":"dt.","vn":"bạn bè","examples":[{"cn":"他是我的朋友。","pinyin":"Tā shì wǒ de péngyou.","vn":"Anh ấy là bạn tôi."},{"cn":"我和朋友一起玩。","pinyin":"Wǒ hé péngyou yìqǐ wán.","vn":"Tôi chơi cùng bạn bè."},{"cn":"我有很多朋友。","pinyin":"Wǒ yǒu hěn duō péngyou.","vn":"Tôi có rất nhiều bạn bè."}]},{"hanzi":"唱","pinyin":"chàng","pos":"dgt.","vn":"hát","examples":[{"cn":"我喜欢唱歌。","pinyin":"Wǒ xǐhuan chàng gē.","vn":"Tôi thích hát."},{"cn":"她唱得很好听。","pinyin":"Tā chàng de hěn hǎotīng.","vn":"Cô ấy hát rất hay."},{"cn":"我们一起唱歌吧。","pinyin":"Wǒmen yìqǐ chàng gē ba.","vn":"Chúng ta cùng hát đi."}]},{"hanzi":"歌","pinyin":"gē","pos":"dt.","vn":"bài hát","examples":[{"cn":"这首歌很好听。","pinyin":"Zhè shǒu gē hěn hǎotīng.","vn":"Bài hát này rất hay."},{"cn":"我喜欢唱歌。","pinyin":"Wǒ xǐhuan chàng gē.","vn":"Tôi thích hát."},{"cn":"他在听歌。","pinyin":"Tā zài tīng gē.","vn":"Anh ấy đang nghe nhạc."}]},{"hanzi":"好听","pinyin":"hǎotīng","pos":"tt.","vn":"hay, dễ nghe","examples":[{"cn":"这首歌很好听。","pinyin":"Zhè shǒu gē hěn hǎotīng.","vn":"Bài hát này rất hay."},{"cn":"她的声音很好听。","pinyin":"Tā de shēngyīn hěn hǎotīng.","vn":"Giọng của cô ấy rất hay."},{"cn":"这个不好听。","pinyin":"Zhège bù hǎotīng.","vn":"Cái này không hay."}]},{"hanzi":"电视","pinyin":"diànshì","pos":"dt.","vn":"ti vi","examples":[{"cn":"我在看电视。","pinyin":"Wǒ zài kàn diànshì.","vn":"Tôi đang xem ti vi."},{"cn":"猫在电视前边。","pinyin":"Māo zài diànshì qiánbian.","vn":"Con mèo ở trước ti vi."},{"cn":"晚上我们看电视。","pinyin":"Wǎnshang wǒmen kàn diànshì.","vn":"Buổi tối chúng ta xem ti vi."}]},{"hanzi":"狗","pinyin":"gǒu","pos":"dt.","vn":"chó","examples":[{"cn":"我家有一只狗。","pinyin":"Wǒ jiā yǒu yì zhī gǒu.","vn":"Nhà tôi có một con chó."},{"cn":"这只狗很可爱。","pinyin":"Zhè zhī gǒu hěn kě'ài.","vn":"Con chó này rất đáng yêu."},{"cn":"狗在外边玩。","pinyin":"Gǒu zài wàibian wán.","vn":"Con chó chơi ở bên ngoài."}]},{"hanzi":"玩","pinyin":"wán","pos":"dgt.","vn":"chơi","examples":[{"cn":"我们一起玩吧。","pinyin":"Wǒmen yìqǐ wán ba.","vn":"Chúng ta cùng chơi đi."},{"cn":"猫在玩。","pinyin":"Māo zài wán.","vn":"Con mèo đang chơi."},{"cn":"我和朋友去玩。","pinyin":"Wǒ hé péngyou qù wán.","vn":"Tôi đi chơi cùng bạn."}]}],"grammar":[{"title":"存现句（1）","explanation_vn":"Câu tồn hiện là câu biểu thị một địa điểm hoặc vị trí nào đó tồn tại người hoặc vật, thường dùng \"有\" hoặc \"是\" làm dấu hiệu. Khi phủ định, không dùng số từ - lượng từ trước tân ngữ.","examples":[{"cn":"学校前边有一家电影院。","pinyin":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","vn":"Phía trước trường có một rạp chiếu phim."},{"cn":"电影院前边是一家超市。","pinyin":"Diànyǐngyuàn qiánbian shì yì jiā chāoshì.","vn":"Phía trước rạp chiếu phim là một siêu thị."},{"cn":"桌子上没有小猫。","pinyin":"Zhuōzi shang méiyǒu xiǎo māo.","vn":"Trên bàn không có con mèo nào."}]},{"title":"时间词语和处所词语同时作状语的顺序","explanation_vn":"Khi từ ngữ chỉ thời gian và từ ngữ chỉ nơi chốn cùng làm trạng ngữ, từ ngữ chỉ thời gian phải đứng trước từ ngữ chỉ nơi chốn.","examples":[{"cn":"我们七点在电影院外边见。","pinyin":"Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn.","vn":"Chúng ta gặp nhau lúc bảy giờ ở ngoài rạp chiếu phim."},{"cn":"安妮下午在家里学中文。","pinyin":"Ānnī xiàwǔ zài jiā li xué Zhōngwén.","vn":"Chiều nay Annie học tiếng Trung ở nhà."},{"cn":"陈天中明天中午在学校吃午饭。","pinyin":"Chén Tiānzhōng míngtiān zhōngwǔ zài xuéxiào chī wǔfàn.","vn":"Trưa mai Trần Thiên Trung ăn trưa ở trường."}]},{"title":"表示序数的“第”","explanation_vn":"\"第\" đứng trước số từ chỉ số nguyên, biểu thị số thứ tự. Cấu trúc cơ bản: (1) 第 + số từ; (2) 第 + số từ + lượng từ + (danh từ).","examples":[{"cn":"第一，第二，第三。","pinyin":"Dì-yī, dì-èr, dì-sān.","vn":"Thứ nhất, thứ hai, thứ ba."},{"cn":"第一个，第二个，第一本。","pinyin":"Dì-yī gè, dì-èr gè, dì-yī běn.","vn":"Cái thứ nhất, cái thứ hai, quyển thứ nhất."},{"cn":"第一个学生，第一本书。","pinyin":"Dì-yī gè xuésheng, dì-yī běn shū.","vn":"Học sinh thứ nhất, quyển sách thứ nhất."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"李文","cn":"学校前边有一家电影院。","pinyin":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn."},{"speaker":"白家月","cn":"对。我们晚上去那个电影院看电影吧。","pinyin":"Duì. Wǒmen wǎnshang qù nàge diànyǐngyuàn kàn diànyǐng ba."},{"speaker":"李文","cn":"好！我们七点在电影院外边见，好吗？","pinyin":"Hǎo! Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn, hǎo ma?"},{"speaker":"白家月","cn":"好的，晚上七点见！","pinyin":"Hǎo de, wǎnshang qī diǎn jiàn!"}],"translation_vn":"Lý Văn: Phía trước trường có một rạp chiếu phim.\nBạch Gia Nguyệt: Đúng vậy. Tối nay chúng ta đi rạp đó xem phim nhé.\nLý Văn: Được! Chúng ta gặp nhau lúc bảy giờ ở ngoài rạp chiếu phim nhé?\nBạch Gia Nguyệt: Được, bảy giờ tối gặp nhau nhé!","audio_dialogue":"9-1.mp3","audio_vocab":"9-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"白家月","cn":"椅子上有一本中文书，那是谁的书？","pinyin":"Yǐzi shang yǒu yì běn Zhōngwén shū, nà shì shéi de shū?"},{"speaker":"陈天中","cn":"是我的书，谢谢。这是我的第二本中文书。","pinyin":"Shì wǒ de shū, xièxie. Zhè shì wǒ de dì-èr běn Zhōngwén shū."},{"speaker":"白家月","cn":"不客气。你明天上午在哪儿？","pinyin":"Bú kèqi. Nǐ míngtiān shàngwǔ zài nǎr?"},{"speaker":"陈天中","cn":"我明天上午在学校学习。","pinyin":"Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí."}],"translation_vn":"Bạch Gia Nguyệt: Trên ghế có một quyển sách tiếng Trung, đó là sách của ai vậy?\nTrần Thiên Trung: Là sách của tôi, cảm ơn bạn. Đây là quyển sách tiếng Trung thứ hai của tôi.\nBạch Gia Nguyệt: Không có gì. Sáng mai bạn ở đâu?\nTrần Thiên Trung: Sáng mai tôi học ở trường.","audio_dialogue":"9-3.mp3","audio_vocab":"9-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"明天星期六，你做什么？","pinyin":"Míngtiān xīngqīliù, nǐ zuò shénme?"},{"speaker":"杨同乐","cn":"我白天在家里读书，晚上和朋友们去外边唱歌。","pinyin":"Wǒ báitiān zài jiā li dúshū, wǎnshang hé péngyoumen qù wàibian chàng gē."},{"speaker":"王一雪","cn":"你唱歌很好听。","pinyin":"Nǐ chàng gē hěn hǎotīng."},{"speaker":"杨同乐","cn":"谢谢！您星期六做什么？","pinyin":"Xièxie! Nín xīngqīliù zuò shénme?"},{"speaker":"王一雪","cn":"我在家里做饭、看电视，和孩子们、小狗玩。","pinyin":"Wǒ zài jiā li zuò fàn, kàn diànshì, hé háizimen, xiǎo gǒu wán."},{"speaker":"杨同乐","cn":"我也有一只小狗。","pinyin":"Wǒ yě yǒu yì zhī xiǎo gǒu."}],"translation_vn":"Vương Nhất Tuyết: Ngày mai là thứ Bảy, bạn định làm gì?\nDương Đồng Lạc: Ban ngày tôi ở nhà đọc sách, buổi tối cùng bạn bè ra ngoài hát.\nVương Nhất Tuyết: Bạn hát hay lắm.\nDương Đồng Lạc: Cảm ơn! Thứ Bảy chị làm gì?\nVương Nhất Tuyết: Tôi ở nhà nấu cơm, xem ti vi, chơi với các con và chó con.\nDương Đồng Lạc: Tôi cũng có một chú chó con.","audio_dialogue":"9-5.mp3","audio_vocab":"9-6.mp3"}]},{"id":10,"title_cn":"这儿的苹果真便宜！","title_pinyin":"Zhèr de píngguǒ zhēn piányi!","title_vn":"Táo ở đây rẻ thật đấy!","goals":["Có thể nghe hiểu, đọc hiểu và nói đơn giản về giá cả hàng hóa.","Nắm vững cách dùng câu có vị ngữ là tính từ.","Nắm vững cách dùng đại từ nghi vấn \"怎么样\".","Nhận biết đồng Nhân dân tệ (RMB)."],"vocab":[{"hanzi":"杯子","pinyin":"bēizi","pos":"dt.","vn":"cốc, ly","examples":[{"cn":"这是我的杯子。","pinyin":"Zhè shì wǒ de bēizi.","vn":"Đây là cốc của tôi."},{"cn":"杯子里有水。","pinyin":"Bēizi lǐ yǒu shuǐ.","vn":"Trong cốc có nước."},{"cn":"给我一个杯子。","pinyin":"Gěi wǒ yí gè bēizi.","vn":"Đưa cho tôi một cái cốc."}]},{"hanzi":"售货员","pinyin":"shòuhuòyuán","pos":"dt.","vn":"nhân viên bán hàng","examples":[{"cn":"她是售货员。","pinyin":"Tā shì shòuhuòyuán.","vn":"Cô ấy là nhân viên bán hàng."},{"cn":"售货员很忙。","pinyin":"Shòuhuòyuán hěn máng.","vn":"Nhân viên bán hàng rất bận."},{"cn":"我问售货员。","pinyin":"Wǒ wèn shòuhuòyuán.","vn":"Tôi hỏi nhân viên bán hàng."}]},{"hanzi":"这边","pinyin":"zhèbiān","pos":"đt.","vn":"bên này","examples":[{"cn":"这边有商店。","pinyin":"Zhèbiān yǒu shāngdiàn.","vn":"Bên này có cửa hàng."},{"cn":"请到这边来。","pinyin":"Qǐng dào zhèbiān lái.","vn":"Mời đến bên này."},{"cn":"我在这边。","pinyin":"Wǒ zài zhèbiān.","vn":"Tôi ở bên này."}]},{"hanzi":"钱","pinyin":"qián","pos":"dt.","vn":"tiền","examples":[{"cn":"我没有钱。","pinyin":"Wǒ méiyǒu qián.","vn":"Tôi không có tiền."},{"cn":"这是你的钱。","pinyin":"Zhè shì nǐ de qián.","vn":"Đây là tiền của bạn."},{"cn":"多少钱？","pinyin":"Duōshao qián?","vn":"Bao nhiêu tiền?"}]},{"hanzi":"这些","pinyin":"zhèxiē","pos":"đt.","vn":"những cái này","examples":[{"cn":"这些是苹果。","pinyin":"Zhèxiē shì píngguǒ.","vn":"Những cái này là táo."},{"cn":"这些很贵。","pinyin":"Zhèxiē hěn guì.","vn":"Những cái này rất đắt."},{"cn":"我要这些。","pinyin":"Wǒ yào zhèxiē.","vn":"Tôi muốn những cái này."}]},{"hanzi":"块","pinyin":"kuài","pos":"lượng.","vn":"đồng, tệ (dùng khi nói về tiền)","examples":[{"cn":"这个三块钱。","pinyin":"Zhège sān kuài qián.","vn":"Cái này ba đồng."},{"cn":"五块一斤。","pinyin":"Wǔ kuài yì jīn.","vn":"Năm đồng một cân."},{"cn":"我有十块钱。","pinyin":"Wǒ yǒu shí kuài qián.","vn":"Tôi có mười đồng."}]},{"hanzi":"那些","pinyin":"nàxiē","pos":"đt.","vn":"những cái kia","examples":[{"cn":"那些是衣服。","pinyin":"Nàxiē shì yīfu.","vn":"Những cái kia là quần áo."},{"cn":"那些很便宜。","pinyin":"Nàxiē hěn piányi.","vn":"Những cái kia rất rẻ."},{"cn":"我不要那些。","pinyin":"Wǒ bú yào nàxiē.","vn":"Tôi không muốn những cái kia."}]},{"hanzi":"这儿","pinyin":"zhèr","pos":"đt.","vn":"ở đây","examples":[{"cn":"我在这儿。","pinyin":"Wǒ zài zhèr.","vn":"Tôi ở đây."},{"cn":"这儿有水果。","pinyin":"Zhèr yǒu shuǐguǒ.","vn":"Ở đây có hoa quả."},{"cn":"请坐这儿。","pinyin":"Qǐng zuò zhèr.","vn":"Mời ngồi ở đây."}]},{"hanzi":"水果","pinyin":"shuǐguǒ","pos":"dt.","vn":"hoa quả, trái cây","examples":[{"cn":"我喜欢水果。","pinyin":"Wǒ xǐhuan shuǐguǒ.","vn":"Tôi thích hoa quả."},{"cn":"这儿有很多水果。","pinyin":"Zhèr yǒu hěn duō shuǐguǒ.","vn":"Ở đây có nhiều hoa quả."},{"cn":"水果很便宜。","pinyin":"Shuǐguǒ hěn piányi.","vn":"Hoa quả rất rẻ."}]},{"hanzi":"少","pinyin":"shǎo","pos":"tt.","vn":"ít","examples":[{"cn":"钱有点儿少。","pinyin":"Qián yǒudiǎnr shǎo.","vn":"Tiền hơi ít."},{"cn":"这个不少。","pinyin":"Zhège bù shǎo.","vn":"Cái này không ít."},{"cn":"我吃得很少。","pinyin":"Wǒ chī de hěn shǎo.","vn":"Tôi ăn rất ít."}]},{"hanzi":"斤","pinyin":"jīn","pos":"lượng.","vn":"cân (jin, đơn vị trọng lượng Trung Quốc)","examples":[{"cn":"我要一斤苹果。","pinyin":"Wǒ yào yì jīn píngguǒ.","vn":"Tôi muốn một cân táo."},{"cn":"一斤多少钱？","pinyin":"Yì jīn duōshao qián?","vn":"Một cân bao nhiêu tiền?"},{"cn":"这是两斤水果。","pinyin":"Zhè shì liǎng jīn shuǐguǒ.","vn":"Đây là hai cân hoa quả."}]},{"hanzi":"苹果","pinyin":"píngguǒ","pos":"dt.","vn":"táo","examples":[{"cn":"我爱吃苹果。","pinyin":"Wǒ ài chī píngguǒ.","vn":"Tôi thích ăn táo."},{"cn":"这个苹果很甜。","pinyin":"Zhège píngguǒ hěn tián.","vn":"Quả táo này rất ngọt."},{"cn":"苹果多少钱一斤？","pinyin":"Píngguǒ duōshao qián yì jīn?","vn":"Táo bao nhiêu tiền một cân?"}]},{"hanzi":"便宜","pinyin":"piányi","pos":"tt.","vn":"rẻ","examples":[{"cn":"这个很便宜。","pinyin":"Zhège hěn piányi.","vn":"Cái này rất rẻ."},{"cn":"水果很便宜。","pinyin":"Shuǐguǒ hěn piányi.","vn":"Hoa quả rất rẻ."},{"cn":"便宜一点儿吧。","pinyin":"Piányi yìdiǎnr ba.","vn":"Rẻ một chút đi."}]},{"hanzi":"商店","pinyin":"shāngdiàn","pos":"dt.","vn":"cửa hàng","examples":[{"cn":"我去商店。","pinyin":"Wǒ qù shāngdiàn.","vn":"Tôi đi cửa hàng."},{"cn":"商店在那儿。","pinyin":"Shāngdiàn zài nàr.","vn":"Cửa hàng ở đó."},{"cn":"这个商店很大。","pinyin":"Zhège shāngdiàn hěn dà.","vn":"Cửa hàng này rất to."}]},{"hanzi":"衣服","pinyin":"yīfu","pos":"dt.","vn":"quần áo","examples":[{"cn":"我买衣服。","pinyin":"Wǒ mǎi yīfu.","vn":"Tôi mua quần áo."},{"cn":"这件衣服很漂亮。","pinyin":"Zhè jiàn yīfu hěn piàoliang.","vn":"Chiếc áo này rất đẹp."},{"cn":"衣服很贵。","pinyin":"Yīfu hěn guì.","vn":"Quần áo rất đắt."}]},{"hanzi":"件","pinyin":"jiàn","pos":"lượng.","vn":"cái, chiếc (dùng cho quần áo)","examples":[{"cn":"这件衣服好看。","pinyin":"Zhè jiàn yīfu hǎokàn.","vn":"Chiếc áo này đẹp."},{"cn":"我买一件衣服。","pinyin":"Wǒ mǎi yí jiàn yīfu.","vn":"Tôi mua một chiếc áo."},{"cn":"那件多少钱？","pinyin":"Nà jiàn duōshao qián?","vn":"Chiếc kia bao nhiêu tiền?"}]},{"hanzi":"元","pinyin":"yuán","pos":"lượng.","vn":"tệ, nguyên (đơn vị tiền tệ)","examples":[{"cn":"这个十元。","pinyin":"Zhège shí yuán.","vn":"Cái này mười tệ."},{"cn":"我有五十元。","pinyin":"Wǒ yǒu wǔshí yuán.","vn":"Tôi có năm mươi tệ."},{"cn":"一件衣服一百元。","pinyin":"Yí jiàn yīfu yìbǎi yuán.","vn":"Một chiếc áo một trăm tệ."}]},{"hanzi":"怎么样","pinyin":"zěnmeyàng","pos":"đt.","vn":"thế nào, như thế nào","examples":[{"cn":"这个怎么样？","pinyin":"Zhège zěnmeyàng?","vn":"Cái này thế nào?"},{"cn":"你今天怎么样？","pinyin":"Nǐ jīntiān zěnmeyàng?","vn":"Hôm nay bạn thế nào?"},{"cn":"天气怎么样？","pinyin":"Tiānqì zěnmeyàng?","vn":"Thời tiết thế nào?"}]},{"hanzi":"贵","pinyin":"guì","pos":"tt.","vn":"đắt","examples":[{"cn":"这个太贵了。","pinyin":"Zhège tài guì le.","vn":"Cái này quá đắt."},{"cn":"衣服很贵。","pinyin":"Yīfu hěn guì.","vn":"Quần áo rất đắt."},{"cn":"商店里东西很贵。","pinyin":"Shāngdiàn lǐ dōngxi hěn guì.","vn":"Đồ trong cửa hàng rất đắt."}]},{"hanzi":"穿","pinyin":"chuān","pos":"dgt.","vn":"mặc","examples":[{"cn":"我穿衣服。","pinyin":"Wǒ chuān yīfu.","vn":"Tôi mặc quần áo."},{"cn":"她穿得很漂亮。","pinyin":"Tā chuān de hěn piàoliang.","vn":"Cô ấy mặc rất đẹp."},{"cn":"今天穿什么？","pinyin":"Jīntiān chuān shénme?","vn":"Hôm nay mặc gì?"}]},{"hanzi":"女","pinyin":"nǚ","pos":"tt.","vn":"nữ, con gái","examples":[{"cn":"她是女的。","pinyin":"Tā shì nǚ de.","vn":"Cô ấy là nữ."},{"cn":"这是女衣服。","pinyin":"Zhè shì nǚ yīfu.","vn":"Đây là quần áo nữ."},{"cn":"我有一个女朋友。","pinyin":"Wǒ yǒu yí gè nǚ péngyou.","vn":"Tôi có bạn gái."}]},{"hanzi":"男","pinyin":"nán","pos":"tt.","vn":"nam, con trai","examples":[{"cn":"他是男的。","pinyin":"Tā shì nán de.","vn":"Anh ấy là nam."},{"cn":"那是男衣服。","pinyin":"Nà shì nán yīfu.","vn":"Đó là quần áo nam."},{"cn":"我弟弟是男孩。","pinyin":"Wǒ dìdi shì nánhái.","vn":"Em trai tôi là con trai."}]},{"hanzi":"那儿","pinyin":"nàr","pos":"đt.","vn":"ở đó, đằng kia","examples":[{"cn":"他在那儿。","pinyin":"Tā zài nàr.","vn":"Anh ấy ở đó."},{"cn":"那儿有商店。","pinyin":"Nàr yǒu shāngdiàn.","vn":"Ở đó có cửa hàng."},{"cn":"你去那儿吗？","pinyin":"Nǐ qù nàr ma?","vn":"Bạn đi đó không?"}]}],"grammar":[{"title":"钱数的表达","explanation_vn":"Tiền tệ Trung Quốc gọi là Nhân dân tệ (人民币). Đơn vị tiền tệ từ lớn đến nhỏ là \"元, 角, 分\", trong khẩu ngữ lần lượt gọi là \"块, 毛, 分\". Thứ tự biểu đạt là: 元/块 → 角/毛 → 分.","examples":[{"cn":"3元 / 三块","pinyin":"sān kuài","vn":"3 tệ (ba đồng)"},{"cn":"3.2元 / 三块二","pinyin":"sān kuài èr","vn":"3,2 tệ (ba đồng hai)"},{"cn":"6.02元 / 六块零两分","pinyin":"liù kuài líng liǎng fēn","vn":"6,02 tệ (sáu đồng lẻ hai xu)"},{"cn":"202.2元 / 二百零二块两毛","pinyin":"èrbǎi líng èr kuài liǎng máo","vn":"202,2 tệ (hai trăm lẻ hai đồng hai hào)"}]},{"title":"形容词谓语句","explanation_vn":"Tính từ có thể trực tiếp làm vị ngữ trong câu, phía trước có thể thêm phó từ chỉ mức độ hoặc phó từ phủ định.","examples":[{"cn":"这儿的水果真不少！","pinyin":"Zhèr de shuǐguǒ zhēn bù shǎo!","vn":"Hoa quả ở đây nhiều thật đấy!"},{"cn":"我的房间不大。","pinyin":"Wǒ de fángjiān bú dà.","vn":"Phòng của tôi không rộng."},{"cn":"那个苹果好吃。","pinyin":"Nàge píngguǒ hǎochī.","vn":"Quả táo đó ngon."}]},{"title":"疑问代词“怎么样”","explanation_vn":"Đại từ nghi vấn \"怎么样\" dùng để hỏi ý kiến, hỏi về tình trạng, v.v. Cấu trúc cơ bản: ……怎么样?","examples":[{"cn":"这个杯子怎么样？我很喜欢，也不贵。","pinyin":"Zhège bēizi zěnmeyàng? Wǒ hěn xǐhuan, yě bú guì.","vn":"Cái cốc này thế nào? Tôi rất thích, cũng không đắt."},{"cn":"这本书怎么样？很好看。","pinyin":"Zhè běn shū zěnmeyàng? Hěn hǎokàn.","vn":"Quyển sách này thế nào? Rất hay."},{"cn":"这个菜怎么样？这个菜不太好吃，我不喜欢。","pinyin":"Zhège cài zěnmeyàng? Zhège cài bú tài hǎochī, wǒ bù xǐhuan.","vn":"Món này thế nào? Món này không ngon lắm, tôi không thích."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"请问，有杯子吗？","pinyin":"Qǐngwèn, yǒu bēizi ma?"},{"speaker":"售货员","cn":"有，杯子在这边。","pinyin":"Yǒu, bēizi zài zhèbiān."},{"speaker":"王一雪","cn":"多少钱一个？","pinyin":"Duōshao qián yí gè?"},{"speaker":"售货员","cn":"这些五块钱一个，那些十块钱一个。","pinyin":"Zhèxiē wǔ kuài qián yí gè, nàxiē shí kuài qián yí gè."},{"speaker":"王一雪","cn":"我买这个吧。","pinyin":"Wǒ mǎi zhège ba."}],"translation_vn":"Vương Nhất Tuyết: Xin hỏi, ở đây có cốc không ạ?\nNhân viên bán hàng: Có, cốc ở bên này ạ.\nVương Nhất Tuyết: Bao nhiêu tiền một cái?\nNhân viên bán hàng: Những cái này năm tệ một cái, những cái kia mười tệ một cái.\nVương Nhất Tuyết: Tôi mua cái này vậy.","audio_dialogue":"10-1.mp3","audio_vocab":"10-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"这儿的水果真不少！","pinyin":"Zhèr de shuǐguǒ zhēn bù shǎo!"},{"speaker":"售货员","cn":"您想买什么？","pinyin":"Nín xiǎng mǎi shénme?"},{"speaker":"王一雪","cn":"我想买两斤苹果。","pinyin":"Wǒ xiǎng mǎi liǎng jīn píngguǒ."},{"speaker":"售货员","cn":"苹果三块五一斤。这些七块二，七块钱吧。","pinyin":"Píngguǒ sān kuài wǔ yì jīn. Zhèxiē qī kuài èr, qī kuài qián ba."},{"speaker":"王一雪","cn":"好的，这儿的苹果真便宜！","pinyin":"Hǎo de, zhèr de píngguǒ zhēn piányi!"}],"translation_vn":"Vương Nhất Tuyết: Ở đây hoa quả nhiều thật đấy!\nNhân viên bán hàng: Chị muốn mua gì ạ?\nVương Nhất Tuyết: Tôi muốn mua hai cân táo.\nNhân viên bán hàng: Táo ba tệ năm một cân. Số này là bảy tệ hai, thôi lấy bảy tệ vậy.\nVương Nhất Tuyết: Được, táo ở đây rẻ thật đấy!","audio_dialogue":"10-3.mp3","audio_vocab":"10-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪","cn":"这家商店衣服真多！这件一百元，怎么样？","pinyin":"Zhè jiā shāngdiàn yīfu zhēn duō! Zhè jiàn yìbǎi yuán, zěnmeyàng?"},{"speaker":"刘明","cn":"好看，也不贵。","pinyin":"Hǎokàn, yě bú guì."},{"speaker":"王一雪","cn":"小雪能穿，买一件吧。","pinyin":"Xiǎoxuě néng chuān, mǎi yí jiàn ba."},{"speaker":"刘明","cn":"好的。小明能穿吗？","pinyin":"Hǎo de. Xiǎomíng néng chuān ma?"},{"speaker":"王一雪","cn":"不能。这些是女孩子穿的衣服，男孩子的衣服在那儿。","pinyin":"Bù néng. Zhèxiē shì nǚ háizi chuān de yīfu, nán háizi de yīfu zài nàr."},{"speaker":"刘明","cn":"好的。","pinyin":"Hǎo de."}],"translation_vn":"Vương Nhất Tuyết: Cửa hàng này quần áo nhiều thật đấy! Cái này một trăm tệ, anh thấy thế nào?\nLưu Minh: Đẹp đấy, cũng không đắt.\nVương Nhất Tuyết: Tiểu Tuyết mặc vừa, mua một cái đi.\nLưu Minh: Được. Tiểu Minh mặc được không?\nVương Nhất Tuyết: Không được. Đây là quần áo con gái mặc, quần áo con trai ở đằng kia.\nLưu Minh: Được rồi.","audio_dialogue":"10-5.mp3","audio_vocab":"10-6.mp3"}]},{"id":11,"title_cn":"我读大学呢","title_pinyin":"Wǒ dú dàxué ne","title_vn":"Em đang học đại học đây","goals":["Có thể nghe hiểu và sử dụng ba cấu trúc để diễn đạt việc đang làm.","Có thể nghe hiểu và sử dụng dạng câu hỏi chính phản (khẳng định - phủ định) để đặt câu hỏi.","Nắm vững cách dùng động từ năng nguyện \"要\" để diễn đạt ý muốn làm, dự định làm việc gì đó."],"vocab":[{"hanzi":"时候","pinyin":"shíhou","pos":"dt.","vn":"lúc, thời điểm","examples":[{"cn":"什么时候？","pinyin":"Shénme shíhou?","vn":"Lúc nào?"},{"cn":"我吃饭的时候看电视。","pinyin":"Wǒ chīfàn de shíhou kàn diànshì.","vn":"Lúc tôi ăn cơm tôi xem ti vi."},{"cn":"那时候我很小。","pinyin":"Nà shíhou wǒ hěn xiǎo.","vn":"Lúc đó tôi còn nhỏ."}]},{"hanzi":"饭店","pinyin":"fàndiàn","pos":"dt.","vn":"nhà hàng, khách sạn","examples":[{"cn":"我们去饭店吃饭。","pinyin":"Wǒmen qù fàndiàn chīfàn.","vn":"Chúng tôi đi nhà hàng ăn cơm."},{"cn":"饭店在这儿。","pinyin":"Fàndiàn zài zhèr.","vn":"Nhà hàng ở đây."},{"cn":"这个饭店很好。","pinyin":"Zhège fàndiàn hěn hǎo.","vn":"Nhà hàng này rất tốt."}]},{"hanzi":"知道","pinyin":"zhīdào","pos":"dgt.","vn":"biết","examples":[{"cn":"我知道了。","pinyin":"Wǒ zhīdào le.","vn":"Tôi biết rồi."},{"cn":"你知道吗？","pinyin":"Nǐ zhīdào ma?","vn":"Bạn biết không?"},{"cn":"我不知道。","pinyin":"Wǒ bù zhīdào.","vn":"Tôi không biết."}]},{"hanzi":"正在","pinyin":"zhèngzài","pos":"phó.","vn":"đang","examples":[{"cn":"他正在睡觉。","pinyin":"Tā zhèngzài shuìjiào.","vn":"Anh ấy đang ngủ."},{"cn":"我正在吃饭。","pinyin":"Wǒ zhèngzài chīfàn.","vn":"Tôi đang ăn cơm."},{"cn":"她正在看书。","pinyin":"Tā zhèngzài kàn shū.","vn":"Cô ấy đang đọc sách."}]},{"hanzi":"找","pinyin":"zhǎo","pos":"dgt.","vn":"tìm","examples":[{"cn":"我找你呢。","pinyin":"Wǒ zhǎo nǐ ne.","vn":"Tôi đang tìm bạn."},{"cn":"你找谁？","pinyin":"Nǐ zhǎo shéi?","vn":"Bạn tìm ai?"},{"cn":"我找不到钱包。","pinyin":"Wǒ zhǎo bú dào qiánbāo.","vn":"Tôi không tìm thấy ví."}]},{"hanzi":"开车","pinyin":"kāichē","pos":"dgt.","vn":"lái xe","examples":[{"cn":"他在开车。","pinyin":"Tā zài kāichē.","vn":"Anh ấy đang lái xe."},{"cn":"我不会开车。","pinyin":"Wǒ bú huì kāichē.","vn":"Tôi không biết lái xe."},{"cn":"爸爸每天开车上班。","pinyin":"Bàba měitiān kāichē shàngbān.","vn":"Bố hàng ngày lái xe đi làm."}]},{"hanzi":"车","pinyin":"chē","pos":"dt.","vn":"xe","examples":[{"cn":"这是我的车。","pinyin":"Zhè shì wǒ de chē.","vn":"Đây là xe của tôi."},{"cn":"车在那儿。","pinyin":"Chē zài nàr.","vn":"Xe ở đó."},{"cn":"我没有车。","pinyin":"Wǒ méiyǒu chē.","vn":"Tôi không có xe."}]},{"hanzi":"在","pinyin":"zài","pos":"phó.","vn":"đang","examples":[{"cn":"他在睡觉。","pinyin":"Tā zài shuìjiào.","vn":"Anh ấy đang ngủ."},{"cn":"我在吃饭。","pinyin":"Wǒ zài chīfàn.","vn":"Tôi đang ăn cơm."},{"cn":"她在看书。","pinyin":"Tā zài kàn shū.","vn":"Cô ấy đang đọc sách."}]},{"hanzi":"读","pinyin":"dú","pos":"dgt.","vn":"học, theo học","examples":[{"cn":"我在读大学。","pinyin":"Wǒ zài dú dàxué.","vn":"Tôi đang học đại học."},{"cn":"他读医科。","pinyin":"Tā dú yīkē.","vn":"Anh ấy học y khoa."},{"cn":"弟弟在读书。","pinyin":"Dìdi zài dú shū.","vn":"Em trai đang đọc sách."}]},{"hanzi":"大学","pinyin":"dàxué","pos":"dt.","vn":"đại học","examples":[{"cn":"我上大学。","pinyin":"Wǒ shàng dàxué.","vn":"Tôi học đại học."},{"cn":"这是一个大学。","pinyin":"Zhè shì yí gè dàxué.","vn":"Đây là một trường đại học."},{"cn":"他在大学工作。","pinyin":"Tā zài dàxué gōngzuò.","vn":"Anh ấy làm việc ở trường đại học."}]},{"hanzi":"大学生","pinyin":"dàxuéshēng","pos":"dt.","vn":"sinh viên đại học","examples":[{"cn":"我是大学生。","pinyin":"Wǒ shì dàxuéshēng.","vn":"Tôi là sinh viên đại học."},{"cn":"他是大学生吗？","pinyin":"Tā shì dàxuéshēng ma?","vn":"Anh ấy là sinh viên đại học à?"},{"cn":"大学生很忙。","pinyin":"Dàxuéshēng hěn máng.","vn":"Sinh viên đại học rất bận."}]},{"hanzi":"学","pinyin":"xué","pos":"dgt.","vn":"học","examples":[{"cn":"我学中文。","pinyin":"Wǒ xué Zhōngwén.","vn":"Tôi học tiếng Trung."},{"cn":"他学开车。","pinyin":"Tā xué kāichē.","vn":"Anh ấy học lái xe."},{"cn":"弟弟在学说话。","pinyin":"Dìdi zài xué shuōhuà.","vn":"Em trai đang học nói."}]},{"hanzi":"医","pinyin":"yī","pos":"dt.","vn":"y, y học","examples":[{"cn":"他学医。","pinyin":"Tā xué yī.","vn":"Anh ấy học y."},{"cn":"她是学医的。","pinyin":"Tā shì xué yī de.","vn":"Cô ấy học y."},{"cn":"我哥哥学医。","pinyin":"Wǒ gēge xué yī.","vn":"Anh trai tôi học y."}]},{"hanzi":"弟弟","pinyin":"dìdi","pos":"dt.","vn":"em trai","examples":[{"cn":"这是我弟弟。","pinyin":"Zhè shì wǒ dìdi.","vn":"Đây là em trai tôi."},{"cn":"我弟弟在读大学。","pinyin":"Wǒ dìdi zài dú dàxué.","vn":"Em trai tôi đang học đại học."},{"cn":"弟弟在睡觉。","pinyin":"Dìdi zài shuìjiào.","vn":"Em trai đang ngủ."}]},{"hanzi":"起床","pinyin":"qǐchuáng","pos":"dgt.","vn":"dậy, thức dậy","examples":[{"cn":"我七点起床。","pinyin":"Wǒ qī diǎn qǐchuáng.","vn":"Tôi dậy lúc bảy giờ."},{"cn":"他还没起床。","pinyin":"Tā hái méi qǐchuáng.","vn":"Anh ấy vẫn chưa dậy."},{"cn":"快起床吧。","pinyin":"Kuài qǐchuáng ba.","vn":"Mau dậy đi."}]},{"hanzi":"睡觉","pinyin":"shuìjiào","pos":"dgt.","vn":"ngủ","examples":[{"cn":"我要睡觉了。","pinyin":"Wǒ yào shuìjiào le.","vn":"Tôi sắp đi ngủ rồi."},{"cn":"他在睡觉。","pinyin":"Tā zài shuìjiào.","vn":"Anh ấy đang ngủ."},{"cn":"弟弟还在睡觉。","pinyin":"Dìdi hái zài shuìjiào.","vn":"Em trai vẫn đang ngủ."}]},{"hanzi":"睡","pinyin":"shuì","pos":"dgt.","vn":"ngủ","examples":[{"cn":"我睡了八个小时。","pinyin":"Wǒ shuì le bā gè xiǎoshí.","vn":"Tôi đã ngủ tám tiếng."},{"cn":"他睡得很好。","pinyin":"Tā shuì de hěn hǎo.","vn":"Anh ấy ngủ rất ngon."},{"cn":"我没睡好。","pinyin":"Wǒ méi shuì hǎo.","vn":"Tôi ngủ không ngon."}]},{"hanzi":"那里","pinyin":"nàlǐ","pos":"đt.","vn":"ở đó","examples":[{"cn":"他在那里。","pinyin":"Tā zài nàlǐ.","vn":"Anh ấy ở đó."},{"cn":"那里有大学。","pinyin":"Nàlǐ yǒu dàxué.","vn":"Ở đó có trường đại học."},{"cn":"我们去那里吧。","pinyin":"Wǒmen qù nàlǐ ba.","vn":"Chúng ta đi đó đi."}]},{"hanzi":"哪里","pinyin":"nǎlǐ","pos":"đt.","vn":"ở đâu","examples":[{"cn":"你在哪里？","pinyin":"Nǐ zài nǎlǐ?","vn":"Bạn đang ở đâu?"},{"cn":"饭店在哪里？","pinyin":"Fàndiàn zài nǎlǐ?","vn":"Nhà hàng ở đâu?"},{"cn":"他去哪里了？","pinyin":"Tā qù nǎlǐ le?","vn":"Anh ấy đi đâu rồi?"}]},{"hanzi":"昨天","pinyin":"zuótiān","pos":"dt.","vn":"hôm qua","examples":[{"cn":"昨天我很忙。","pinyin":"Zuótiān wǒ hěn máng.","vn":"Hôm qua tôi rất bận."},{"cn":"昨天下雨了。","pinyin":"Zuótiān xià yǔ le.","vn":"Hôm qua trời mưa."},{"cn":"他昨天来了。","pinyin":"Tā zuótiān lái le.","vn":"Anh ấy hôm qua đã đến."}]},{"hanzi":"问","pinyin":"wèn","pos":"dgt.","vn":"hỏi","examples":[{"cn":"我问他一个问题。","pinyin":"Wǒ wèn tā yí gè wèntí.","vn":"Tôi hỏi anh ấy một câu hỏi."},{"cn":"你问老师吧。","pinyin":"Nǐ wèn lǎoshī ba.","vn":"Bạn hỏi thầy giáo đi."},{"cn":"我想问你。","pinyin":"Wǒ xiǎng wèn nǐ.","vn":"Tôi muốn hỏi bạn."}]},{"hanzi":"对","pinyin":"duì","pos":"giới.","vn":"đối với, với","examples":[{"cn":"他对我很好。","pinyin":"Tā duì wǒ hěn hǎo.","vn":"Anh ấy đối với tôi rất tốt."},{"cn":"这对你很重要。","pinyin":"Zhè duì nǐ hěn zhòngyào.","vn":"Cái này đối với bạn rất quan trọng."},{"cn":"老师对学生很好。","pinyin":"Lǎoshī duì xuéshēng hěn hǎo.","vn":"Thầy giáo đối với học sinh rất tốt."}]},{"hanzi":"说","pinyin":"shuō","pos":"dgt.","vn":"nói","examples":[{"cn":"他在说话。","pinyin":"Tā zài shuōhuà.","vn":"Anh ấy đang nói chuyện."},{"cn":"我说中文。","pinyin":"Wǒ shuō Zhōngwén.","vn":"Tôi nói tiếng Trung."},{"cn":"你说什么？","pinyin":"Nǐ shuō shénme?","vn":"Bạn nói gì?"}]},{"hanzi":"要","pinyin":"yào","pos":"đtnn.","vn":"muốn, định","examples":[{"cn":"我要吃饭。","pinyin":"Wǒ yào chīfàn.","vn":"Tôi muốn ăn cơm."},{"cn":"他要去商店。","pinyin":"Tā yào qù shāngdiàn.","vn":"Anh ấy định đi cửa hàng."},{"cn":"你要什么？","pinyin":"Nǐ yào shénme?","vn":"Bạn muốn gì?"}]},{"hanzi":"小朋友","pinyin":"xiǎopéngyǒu","pos":"dt.","vn":"bạn nhỏ, trẻ con","examples":[{"cn":"小朋友在玩儿。","pinyin":"Xiǎopéngyǒu zài wánr.","vn":"Trẻ con đang chơi."},{"cn":"这个小朋友很可爱。","pinyin":"Zhège xiǎopéngyǒu hěn kě'ài.","vn":"Bạn nhỏ này rất dễ thương."},{"cn":"小朋友们好。","pinyin":"Xiǎopéngyǒumen hǎo.","vn":"Chào các bạn nhỏ."}]}],"grammar":[{"title":"正反问","explanation_vn":"Câu hỏi chính phản có cấu trúc \"×+不/没+×\", trong đó \"×\" là động từ hoặc tính từ. Câu hỏi chính phản với động từ dùng \"不/没\", còn với tính từ dùng \"不\".","examples":[{"cn":"它是不是在超市后边？","pinyin":"Tā shì bu shì zài chāoshì hòubian?","vn":"Nó có phải ở phía sau siêu thị không?"},{"cn":"你去没去学校？","pinyin":"Nǐ qù méi qù xuéxiào?","vn":"Anh đã đi học chưa?"},{"cn":"这件衣服好看不好看？","pinyin":"Zhè jiàn yīfu hǎokàn bu hǎokàn?","vn":"Cái áo này có đẹp không?"},{"cn":"他去哪儿了？你知道不知道？","pinyin":"Tā qù nǎr le? Nǐ zhīdào bu zhīdào?","vn":"Anh ấy đi đâu rồi? Em có biết không?"},{"cn":"昨天你去没去书店？","pinyin":"Zuótiān nǐ qù méi qù shūdiàn?","vn":"Hôm qua anh có đi hiệu sách không?"},{"cn":"这件衣服贵不贵？","pinyin":"Zhè jiàn yīfu guì bu guì?","vn":"Cái áo này có đắt không?"}]},{"title":"时间副词“在/正在”","explanation_vn":"Phó từ chỉ thời gian \"在/正在\" đặt trước động từ, biểu thị động tác đang diễn ra hoặc tình huống đang tiếp diễn. Bài học này giới thiệu hai cấu trúc: (1) 在/正在 + động từ; (2) 在/正在 + động từ + 呢. Ngoài ra còn có cấu trúc thứ ba để diễn đạt việc đang làm: (3) động từ + 呢. Khi trả lời phủ định, dùng phó từ \"没(有)\".","examples":[{"cn":"你还在读大学吗？","pinyin":"Nǐ hái zài dú dàxué ma?","vn":"Anh vẫn đang học đại học à?"},{"cn":"学生们在/正在上课呢。","pinyin":"Xuéshengmen zài/zhèngzài shàngkè ne.","vn":"Các học sinh đang học trên lớp."},{"cn":"我们读书呢。","pinyin":"Wǒmen dúshū ne.","vn":"Chúng tôi đang đọc sách."},{"cn":"你在做什么呢？我正在看电视。","pinyin":"Nǐ zài zuò shénme ne? Wǒ zhèngzài kàn diànshì.","vn":"Anh đang làm gì vậy? Tôi đang xem ti vi."},{"cn":"我去看电影，你去不去？我在学习呢，不想去。","pinyin":"Wǒ qù kàn diànyǐng, nǐ qù bu qù? Wǒ zài xuéxí ne, bù xiǎng qù.","vn":"Tôi đi xem phim, anh đi không? Tôi đang học, không muốn đi."},{"cn":"你在买菜吗？我没买菜，买水果呢。","pinyin":"Nǐ zài mǎi cài ma? Wǒ méi mǎi cài, mǎi shuǐguǒ ne.","vn":"Anh đang mua rau à? Tôi không mua rau, đang mua hoa quả."}]},{"title":"能愿动词“要”","explanation_vn":"Động từ năng nguyện \"要\" đứng trước động từ, biểu thị ý muốn làm hoặc dự định làm việc gì đó.","examples":[{"cn":"他今天要和小朋友玩。","pinyin":"Tā jīntiān yào hé xiǎopéngyǒu wán.","vn":"Hôm nay nó định chơi với các bạn."},{"cn":"妈妈要去超市。","pinyin":"Māma yào qù chāoshì.","vn":"Mẹ định đi siêu thị."},{"cn":"白家月要在家里学中文。","pinyin":"Bái Jiāyuè yào zài jiā li xué Zhōngwén.","vn":"Bạch Gia Nguyệt định học tiếng Trung ở nhà."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一飞","cn":"喂，李文，你什么时候能到饭店？","pinyin":"Wèi, Lǐ Wén, nǐ shénme shíhou néng dào fàndiàn?"},{"speaker":"李文","cn":"还不知道，正在找呢。它是不是在超市后边？","pinyin":"Hái bù zhīdào, zhèngzài zhǎo ne. Tā shì bu shì zài chāoshì hòubian?"},{"speaker":"王一飞","cn":"是的。你开车没开车？","pinyin":"Shì de. Nǐ kāichē méi kāichē?"},{"speaker":"李文","cn":"我没开车，坐车呢。","pinyin":"Wǒ méi kāichē, zuò chē ne."}],"translation_vn":"Vương Nhất Phi: Alô, Lý Văn, khi nào anh đến được nhà hàng?\nLý Văn: Vẫn chưa biết, đang tìm đây. Nó có phải ở phía sau siêu thị không?\nVương Nhất Phi: Đúng vậy. Anh có lái xe không?\nLý Văn: Tôi không lái xe, đang ngồi xe đây.","audio_dialogue":"11-1.mp3","audio_vocab":"11-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一飞","cn":"你还在读大学吗？","pinyin":"Nǐ hái zài dú dàxué ma?"},{"speaker":"李文","cn":"对，我读大学呢，还是大学生。","pinyin":"Duì, wǒ dú dàxué ne, hái shì dàxuéshēng."},{"speaker":"王一飞","cn":"你们学习忙不忙？","pinyin":"Nǐmen xuéxí máng bu máng?"},{"speaker":"李文","cn":"非常忙，我学医，我们的课很多。","pinyin":"Fēicháng máng, wǒ xué yī, wǒmen de kè hěn duō."}],"translation_vn":"Vương Nhất Phi: Anh vẫn đang học đại học à?\nLý Văn: Đúng vậy, tôi đang học đại học, vẫn còn là sinh viên.\nVương Nhất Phi: Các bạn học hành có bận không?\nLý Văn: Bận lắm, tôi học y, lớp chúng tôi có rất nhiều tiết học.","audio_dialogue":"11-3.mp3","audio_vocab":"11-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"刘明","cn":"弟弟起床没起床呢？","pinyin":"Dìdi qǐchuáng méi qǐchuáng ne?"},{"speaker":"刘小雪","cn":"没起床呢，还在睡觉。","pinyin":"Méi qǐchuáng ne, hái zài shuìjiào."},{"speaker":"刘明","cn":"还睡呢？他今天去不去那里？","pinyin":"Hái shuì ne? Tā jīntiān qù bu qù nàlǐ?"},{"speaker":"刘小雪","cn":"去哪里？","pinyin":"Qù nǎlǐ?"},{"speaker":"刘明","cn":"去超市。","pinyin":"Qù chāoshì."},{"speaker":"刘小雪","cn":"我昨天问他，他对我说，他不去，他今天要和小朋友玩。","pinyin":"Wǒ zuótiān wèn tā, tā duì wǒ shuō, tā bú qù, tā jīntiān yào hé xiǎopéngyǒu wán."}],"translation_vn":"Lưu Minh: Em trai dậy chưa?\nLưu Tiểu Tuyết: Chưa dậy đâu, vẫn đang ngủ.\nLưu Minh: Vẫn còn ngủ à? Hôm nay nó có đi đến đó không?\nLưu Tiểu Tuyết: Đi đâu cơ?\nLưu Minh: Đi siêu thị.\nLưu Tiểu Tuyết: Hôm qua con hỏi nó rồi, nó bảo con là nó không đi, hôm nay nó định chơi với bạn.","audio_dialogue":"11-5.mp3","audio_vocab":"11-6.mp3"}]},{"id":12,"title_cn":"昨天下雪了","title_pinyin":"Zuótiān xià xuě le","title_vn":"Hôm qua trời đã có tuyết","goals":["Có thể nghe hiểu và miêu tả tình hình thời tiết.","Có thể nghe hiểu và miêu tả đơn giản về tình trạng bệnh.","Nắm vững cách dùng trợ từ ngữ khí \"了(1)\".","Nắm vững cách dùng cấu trúc \"太……了\".","Hiểu được lợi ích của việc \"uống nước ấm\" mà người Trung Quốc thường khuyên khi bị ốm."],"vocab":[{"hanzi":"天气","pinyin":"tiānqì","pos":"dt.","vn":"thời tiết","examples":[{"cn":"今天天气很好。","pinyin":"Jīntiān tiānqì hěn hǎo.","vn":"Hôm nay thời tiết rất đẹp."},{"cn":"天气怎么样？","pinyin":"Tiānqì zěnmeyàng?","vn":"Thời tiết thế nào?"},{"cn":"天气很冷。","pinyin":"Tiānqì hěn lěng.","vn":"Thời tiết rất lạnh."}]},{"hanzi":"这里","pinyin":"zhèlǐ","pos":"đt.","vn":"ở đây","examples":[{"cn":"我在这里。","pinyin":"Wǒ zài zhèlǐ.","vn":"Tôi ở đây."},{"cn":"这里有水果。","pinyin":"Zhèlǐ yǒu shuǐguǒ.","vn":"Ở đây có hoa quả."},{"cn":"请到这里来。","pinyin":"Qǐng dào zhèlǐ lái.","vn":"Mời đến đây."}]},{"hanzi":"天","pinyin":"tiān","pos":"dt.","vn":"trời, thời tiết","examples":[{"cn":"今天天很冷。","pinyin":"Jīntiān tiān hěn lěng.","vn":"Hôm nay trời rất lạnh."},{"cn":"天要下雨了。","pinyin":"Tiān yào xià yǔ le.","vn":"Trời sắp mưa rồi."},{"cn":"今天天很好。","pinyin":"Jīntiān tiān hěn hǎo.","vn":"Hôm nay trời đẹp."}]},{"hanzi":"下雨","pinyin":"xià yǔ","pos":"","vn":"trời mưa, đổ mưa","examples":[{"cn":"外面在下雨。","pinyin":"Wàimiàn zài xià yǔ.","vn":"Bên ngoài đang mưa."},{"cn":"昨天下雨了。","pinyin":"Zuótiān xià yǔ le.","vn":"Hôm qua trời mưa."},{"cn":"明天会下雨吗？","pinyin":"Míngtiān huì xià yǔ ma?","vn":"Ngày mai có mưa không?"}]},{"hanzi":"了","pinyin":"le","pos":"trợ.","vn":"trợ từ ngữ khí, đặt cuối câu biểu thị có sự thay đổi hoặc xuất hiện tình huống mới","examples":[{"cn":"我吃饭了。","pinyin":"Wǒ chīfàn le.","vn":"Tôi ăn cơm rồi."},{"cn":"他来了。","pinyin":"Tā lái le.","vn":"Anh ấy đến rồi."},{"cn":"下雨了。","pinyin":"Xià yǔ le.","vn":"Trời mưa rồi."}]},{"hanzi":"雨","pinyin":"yǔ","pos":"dt.","vn":"mưa","examples":[{"cn":"雨很大。","pinyin":"Yǔ hěn dà.","vn":"Mưa rất to."},{"cn":"外面有雨。","pinyin":"Wàimiàn yǒu yǔ.","vn":"Bên ngoài có mưa."},{"cn":"我喜欢雨天。","pinyin":"Wǒ xǐhuan yǔtiān.","vn":"Tôi thích ngày mưa."}]},{"hanzi":"有点儿","pinyin":"yǒudiǎnr","pos":"phó.","vn":"hơi, một chút","examples":[{"cn":"今天有点儿冷。","pinyin":"Jīntiān yǒudiǎnr lěng.","vn":"Hôm nay hơi lạnh."},{"cn":"这个有点儿贵。","pinyin":"Zhège yǒudiǎnr guì.","vn":"Cái này hơi đắt."},{"cn":"我有点儿累。","pinyin":"Wǒ yǒudiǎnr lèi.","vn":"Tôi hơi mệt."}]},{"hanzi":"觉得","pinyin":"juéde","pos":"dgt.","vn":"cảm thấy","examples":[{"cn":"我觉得很冷。","pinyin":"Wǒ juéde hěn lěng.","vn":"Tôi cảm thấy rất lạnh."},{"cn":"你觉得怎么样？","pinyin":"Nǐ juéde zěnmeyàng?","vn":"Bạn cảm thấy thế nào?"},{"cn":"他觉得很累。","pinyin":"Tā juéde hěn lèi.","vn":"Anh ấy cảm thấy rất mệt."}]},{"hanzi":"冷","pinyin":"lěng","pos":"tt.","vn":"lạnh","examples":[{"cn":"今天很冷。","pinyin":"Jīntiān hěn lěng.","vn":"Hôm nay rất lạnh."},{"cn":"水很冷。","pinyin":"Shuǐ hěn lěng.","vn":"Nước rất lạnh."},{"cn":"我觉得有点儿冷。","pinyin":"Wǒ juéde yǒudiǎnr lěng.","vn":"Tôi cảm thấy hơi lạnh."}]},{"hanzi":"下","pinyin":"xià","pos":"dgt.","vn":"rơi, đổ xuống (mưa, tuyết...)","examples":[{"cn":"下雪了。","pinyin":"Xià xuě le.","vn":"Trời có tuyết rơi."},{"cn":"外面在下雨。","pinyin":"Wàimiàn zài xià yǔ.","vn":"Bên ngoài đang mưa."},{"cn":"雪下得很大。","pinyin":"Xuě xià de hěn dà.","vn":"Tuyết rơi rất to."}]},{"hanzi":"雪","pinyin":"xuě","pos":"dt.","vn":"tuyết","examples":[{"cn":"外面下雪了。","pinyin":"Wàimiàn xià xuě le.","vn":"Bên ngoài có tuyết rơi."},{"cn":"雪很白。","pinyin":"Xuě hěn bái.","vn":"Tuyết rất trắng."},{"cn":"我喜欢雪。","pinyin":"Wǒ xǐhuan xuě.","vn":"Tôi thích tuyết."}]},{"hanzi":"来","pinyin":"lái","pos":"dgt.","vn":"đến","examples":[{"cn":"他明天来。","pinyin":"Tā míngtiān lái.","vn":"Anh ấy ngày mai đến."},{"cn":"你来这儿。","pinyin":"Nǐ lái zhèr.","vn":"Bạn đến đây."},{"cn":"我来了。","pinyin":"Wǒ lái le.","vn":"Tôi đến rồi."}]},{"hanzi":"公司","pinyin":"gōngsī","pos":"dt.","vn":"công ty","examples":[{"cn":"我在公司工作。","pinyin":"Wǒ zài gōngsī gōngzuò.","vn":"Tôi làm việc ở công ty."},{"cn":"他的公司很大。","pinyin":"Tā de gōngsī hěn dà.","vn":"Công ty của anh ấy rất lớn."},{"cn":"公司在哪里？","pinyin":"Gōngsī zài nǎlǐ?","vn":"Công ty ở đâu?"}]},{"hanzi":"生病","pinyin":"shēngbìng","pos":"dgt.","vn":"bị ốm, bị bệnh","examples":[{"cn":"我生病了。","pinyin":"Wǒ shēngbìng le.","vn":"Tôi bị ốm rồi."},{"cn":"他昨天生病了。","pinyin":"Tā zuótiān shēngbìng le.","vn":"Hôm qua anh ấy bị ốm."},{"cn":"弟弟生病了。","pinyin":"Dìdi shēngbìng le.","vn":"Em trai bị ốm rồi."}]},{"hanzi":"看病","pinyin":"kànbìng","pos":"dgt.","vn":"khám bệnh","examples":[{"cn":"我去医院看病。","pinyin":"Wǒ qù yīyuàn kànbìng.","vn":"Tôi đi bệnh viện khám bệnh."},{"cn":"他在看病。","pinyin":"Tā zài kànbìng.","vn":"Anh ấy đang khám bệnh."},{"cn":"妈妈带我看病。","pinyin":"Māma dài wǒ kànbìng.","vn":"Mẹ đưa tôi đi khám bệnh."}]},{"hanzi":"病","pinyin":"bìng","pos":"dgt.","vn":"ốm, bị bệnh","examples":[{"cn":"他病了。","pinyin":"Tā bìng le.","vn":"Anh ấy bị ốm rồi."},{"cn":"我病得很重。","pinyin":"Wǒ bìng de hěn zhòng.","vn":"Tôi ốm nặng."},{"cn":"她病了三天。","pinyin":"Tā bìng le sān tiān.","vn":"Cô ấy ốm ba ngày rồi."}]},{"hanzi":"一点儿","pinyin":"yìdiǎnr","pos":"sl.","vn":"một chút, một ít","examples":[{"cn":"我要一点儿水。","pinyin":"Wǒ yào yìdiǎnr shuǐ.","vn":"Tôi muốn một chút nước."},{"cn":"吃一点儿吧。","pinyin":"Chī yìdiǎnr ba.","vn":"Ăn một chút đi."},{"cn":"我会说一点儿中文。","pinyin":"Wǒ huì shuō yìdiǎnr Zhōngwén.","vn":"Tôi biết nói một chút tiếng Trung."}]},{"hanzi":"药","pinyin":"yào","pos":"dt.","vn":"thuốc","examples":[{"cn":"我吃药了。","pinyin":"Wǒ chī yào le.","vn":"Tôi uống thuốc rồi."},{"cn":"这是什么药？","pinyin":"Zhè shì shénme yào?","vn":"Đây là thuốc gì?"},{"cn":"你得吃药。","pinyin":"Nǐ děi chī yào.","vn":"Bạn phải uống thuốc."}]},{"hanzi":"天","pinyin":"tiān","pos":"lượng.","vn":"ngày (lượng từ chỉ ngày)","examples":[{"cn":"我去了三天。","pinyin":"Wǒ qù le sān tiān.","vn":"Tôi đã đi ba ngày."},{"cn":"他病了两天。","pinyin":"Tā bìng le liǎng tiān.","vn":"Anh ấy ốm hai ngày."},{"cn":"一天有二十四个小时。","pinyin":"Yì tiān yǒu èrshísì gè xiǎoshí.","vn":"Một ngày có hai mươi tư tiếng."}]},{"hanzi":"回","pinyin":"huí","pos":"dgt.","vn":"trở về, quay về","examples":[{"cn":"我要回家了。","pinyin":"Wǒ yào huí jiā le.","vn":"Tôi sắp về nhà rồi."},{"cn":"他回公司了。","pinyin":"Tā huí gōngsī le.","vn":"Anh ấy quay về công ty rồi."},{"cn":"几点回来？","pinyin":"Jǐ diǎn huílai?","vn":"Mấy giờ về?"}]},{"hanzi":"再","pinyin":"zài","pos":"phó.","vn":"rồi hãy, mới (sau đó mới)","examples":[{"cn":"你先吃饭，再睡觉。","pinyin":"Nǐ xiān chīfàn, zài shuìjiào.","vn":"Bạn ăn cơm trước, rồi hãy ngủ."},{"cn":"吃了药再去上班。","pinyin":"Chī le yào zài qù shàngbān.","vn":"Uống thuốc xong rồi hãy đi làm."},{"cn":"做完作业再玩。","pinyin":"Zuò wán zuòyè zài wán.","vn":"Làm xong bài tập rồi hãy chơi."}]},{"hanzi":"喝","pinyin":"hē","pos":"dgt.","vn":"uống","examples":[{"cn":"我喝水。","pinyin":"Wǒ hē shuǐ.","vn":"Tôi uống nước."},{"cn":"你喝什么？","pinyin":"Nǐ hē shénme?","vn":"Bạn uống gì?"},{"cn":"他喜欢喝茶。","pinyin":"Tā xǐhuan hē chá.","vn":"Anh ấy thích uống trà."}]},{"hanzi":"热","pinyin":"rè","pos":"tt.","vn":"nóng, ấm","examples":[{"cn":"今天很热。","pinyin":"Jīntiān hěn rè.","vn":"Hôm nay rất nóng."},{"cn":"水很热。","pinyin":"Shuǐ hěn rè.","vn":"Nước rất nóng."},{"cn":"我觉得有点儿热。","pinyin":"Wǒ juéde yǒudiǎnr rè.","vn":"Tôi cảm thấy hơi nóng."}]},{"hanzi":"水","pinyin":"shuǐ","pos":"dt.","vn":"nước","examples":[{"cn":"我喝水。","pinyin":"Wǒ hē shuǐ.","vn":"Tôi uống nước."},{"cn":"这是热水。","pinyin":"Zhè shì rè shuǐ.","vn":"Đây là nước nóng."},{"cn":"杯子里有水。","pinyin":"Bēizi lǐ yǒu shuǐ.","vn":"Trong cốc có nước."}]}],"grammar":[{"title":"非主谓句","explanation_vn":"Câu phi chủ vị là loại câu được cấu tạo bởi từ hoặc cụm từ, không phân biệt rõ chủ ngữ và vị ngữ, thường được dùng trong khẩu ngữ.","examples":[{"cn":"下雨了。","pinyin":"Xià yǔ le.","vn":"Trời mưa rồi."},{"cn":"下雪了。","pinyin":"Xià xuě le.","vn":"Trời có tuyết rồi."},{"cn":"上课了。","pinyin":"Shàng kè le.","vn":"Đến giờ học rồi."},{"cn":"真漂亮！","pinyin":"Zhēn piàoliang!","vn":"Đẹp quá!"},{"cn":"对不起！","pinyin":"Duìbuqǐ!","vn":"Xin lỗi!"},{"cn":"没关系！","pinyin":"Méi guānxi!","vn":"Không sao!"}]},{"title":"语气助词“了(1)”","explanation_vn":"Trợ từ ngữ khí \"了(1)\" đặt ở cuối câu hoặc chỗ ngắt trong câu, biểu thị có sự thay đổi hoặc xuất hiện tình huống mới. Khi trả lời phủ định, dùng phó từ \"没\", cuối câu không dùng \"了\".","examples":[{"cn":"下雨了。","pinyin":"Xià yǔ le.","vn":"Trời mưa rồi."},{"cn":"十二点了，吃午饭吧。","pinyin":"Shí'èr diǎn le, chī wǔfàn ba.","vn":"12 giờ rồi, ăn cơm trưa thôi."},{"cn":"弟弟起床了吗？没起床呢。","pinyin":"Dìdi qǐchuáng le ma? Méi qǐchuáng ne.","vn":"Em trai dậy chưa? Chưa dậy đâu."}]},{"title":"“太……了”格式","explanation_vn":"Cấu trúc \"太……了\" dùng để diễn tả cảm thán với mức độ rất cao hoặc rất sâu sắc.","examples":[{"cn":"太冷了！","pinyin":"Tài lěng le!","vn":"Lạnh quá!"},{"cn":"这个杯子太小了。","pinyin":"Zhège bēizi tài xiǎo le.","vn":"Cái cốc này nhỏ quá."},{"cn":"我们今天太高兴了！","pinyin":"Wǒmen jīntiān tài gāoxìng le!","vn":"Hôm nay chúng tôi vui quá!"}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"今天天气怎么样？","pinyin":"Jīntiān tiānqì zěnmeyàng?"},{"speaker":"王一飞","cn":"这里的天不太好，下雨了。","pinyin":"Zhèlǐ de tiān bú tài hǎo, xià yǔ le."},{"speaker":"王一雪","cn":"雨大吗？","pinyin":"Yǔ dà ma?"},{"speaker":"王一飞","cn":"有点儿大，我觉得很冷。","pinyin":"Yǒudiǎnr dà, wǒ juéde hěn lěng."}],"translation_vn":"Vương Nhất Tuyết: Hôm nay thời tiết thế nào?\nVương Nhất Phi: Thời tiết ở đây không tốt lắm, trời đang mưa.\nVương Nhất Tuyết: Mưa to không?\nVương Nhất Phi: Hơi to, anh thấy lạnh lắm.","audio_dialogue":"12-1.mp3","audio_vocab":"12-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"昨天下雪了。","pinyin":"Zuótiān xià xuě le."},{"speaker":"杨同乐","cn":"是的，太冷了。","pinyin":"Shì de, tài lěng le."},{"speaker":"王一雪","cn":"你昨天没来公司，生病了？","pinyin":"Nǐ zuótiān méi lái gōngsī, shēngbìng le?"},{"speaker":"杨同乐","cn":"对，我昨天去医院看病了。","pinyin":"Duì, wǒ zuótiān qù yīyuàn kànbìng le."}],"translation_vn":"Vương Nhất Tuyết: Hôm qua trời có tuyết.\nDương Đồng Lạc: Đúng vậy, lạnh quá.\nVương Nhất Tuyết: Hôm qua anh không đến công ty, bị ốm à?\nDương Đồng Lạc: Đúng, hôm qua tôi đi bệnh viện khám bệnh.","audio_dialogue":"12-3.mp3","audio_vocab":"12-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"杨同乐","cn":"医生，我病了。","pinyin":"Yīshēng, wǒ bìng le."},{"speaker":"胡医生","cn":"我看看。你觉得怎么样？","pinyin":"Wǒ kànkan. Nǐ juéde zěnmeyàng?"},{"speaker":"杨同乐","cn":"我很冷。","pinyin":"Wǒ hěn lěng."},{"speaker":"胡医生","cn":"好的，吃一点儿药，今天休息半天吧。","pinyin":"Hǎo de, chī yìdiǎnr yào, jīntiān xiūxi bàn tiān ba."},{"speaker":"杨同乐","cn":"好的。","pinyin":"Hǎo de."},{"speaker":"胡医生","cn":"回家后再喝些热水。","pinyin":"Huí jiā hòu zài hē xiē rè shuǐ."}],"translation_vn":"Dương Đồng Lạc: Bác sĩ ơi, tôi bị ốm rồi.\nBác sĩ Hồ: Để tôi xem nào. Anh thấy thế nào?\nDương Đồng Lạc: Tôi thấy lạnh lắm.\nBác sĩ Hồ: Được rồi, uống một ít thuốc, hôm nay nghỉ nửa ngày nhé.\nDương Đồng Lạc: Vâng ạ.\nBác sĩ Hồ: Về nhà rồi uống thêm ít nước ấm nhé.","audio_dialogue":"12-5.mp3","audio_vocab":"12-6.mp3"}]},{"id":13,"title_cn":"请给我一杯茶","title_pinyin":"Qǐng gěi wǒ yì bēi chá","title_vn":"Làm ơn cho tôi một cốc trà","goals":["Có thể nghe hiểu và sử dụng câu song tân ngữ (1) để diễn đạt việc hỏi người khác hoặc cho người khác đồ vật, v.v.","Nắm vững cách dùng động từ năng nguyện \"可以\".","Nắm vững cách dùng cấu trúc \"động từ + 一下\".","Hiểu các cách diễn đạt thường dùng khi gọi món ăn."],"vocab":[{"hanzi":"可以","pinyin":"kěyǐ","pos":"đtnn.","vn":"có thể, được phép","examples":[{"cn":"我可以坐这儿吗？","pinyin":"Wǒ kěyǐ zuò zhèr ma?","vn":"Tôi có thể ngồi đây được không?"},{"cn":"你可以进来。","pinyin":"Nǐ kěyǐ jìnlái.","vn":"Bạn có thể vào."},{"cn":"这儿可以喝茶。","pinyin":"Zhèr kěyǐ hē chá.","vn":"Ở đây có thể uống trà."}]},{"hanzi":"再","pinyin":"zài","pos":"phó.","vn":"lại, thêm nữa","examples":[{"cn":"请再说一次。","pinyin":"Qǐng zài shuō yí cì.","vn":"Xin nói lại một lần nữa."},{"cn":"我想再要一杯。","pinyin":"Wǒ xiǎng zài yào yì bēi.","vn":"Tôi muốn gọi thêm một ly nữa."},{"cn":"明天再来。","pinyin":"Míngtiān zài lái.","vn":"Mai lại đến."}]},{"hanzi":"问题","pinyin":"wèntí","pos":"dt.","vn":"câu hỏi, vấn đề","examples":[{"cn":"我有一个问题。","pinyin":"Wǒ yǒu yí ge wèntí.","vn":"Tôi có một câu hỏi."},{"cn":"这不是问题。","pinyin":"Zhè bú shì wèntí.","vn":"Đây không phải vấn đề."},{"cn":"你问题很多。","pinyin":"Nǐ wèntí hěn duō.","vn":"Bạn có nhiều câu hỏi quá."}]},{"hanzi":"卖","pinyin":"mài","pos":"dgt.","vn":"bán","examples":[{"cn":"这儿卖面包。","pinyin":"Zhèr mài miànbāo.","vn":"Ở đây bán bánh mì."},{"cn":"他卖茶。","pinyin":"Tā mài chá.","vn":"Anh ấy bán trà."},{"cn":"你们卖鸡蛋吗？","pinyin":"Nǐmen mài jīdàn ma?","vn":"Các bạn có bán trứng gà không?"}]},{"hanzi":"打电话","pinyin":"dǎ diànhuà","pos":"","vn":"gọi điện thoại","examples":[{"cn":"我给你打电话。","pinyin":"Wǒ gěi nǐ dǎ diànhuà.","vn":"Tôi gọi điện thoại cho bạn."},{"cn":"他在打电话。","pinyin":"Tā zài dǎ diànhuà.","vn":"Anh ấy đang gọi điện thoại."},{"cn":"请再给我打电话。","pinyin":"Qǐng zài gěi wǒ dǎ diànhuà.","vn":"Xin hãy gọi lại cho tôi."}]},{"hanzi":"一下","pinyin":"yíxià","pos":"sl.","vn":"một chút, một lát, thử xem","examples":[{"cn":"请等一下。","pinyin":"Qǐng děng yíxià.","vn":"Xin đợi một chút."},{"cn":"我看一下。","pinyin":"Wǒ kàn yíxià.","vn":"Tôi xem một chút."},{"cn":"你坐一下。","pinyin":"Nǐ zuò yíxià.","vn":"Bạn ngồi một lát."}]},{"hanzi":"服务员","pinyin":"fúwùyuán","pos":"dt.","vn":"nhân viên phục vụ","examples":[{"cn":"服务员，这个多少钱？","pinyin":"Fúwùyuán, zhège duōshao qián?","vn":"Phục vụ ơi, cái này bao nhiêu tiền?"},{"cn":"服务员很忙。","pinyin":"Fúwùyuán hěn máng.","vn":"Nhân viên phục vụ rất bận."},{"cn":"他是服务员。","pinyin":"Tā shì fúwùyuán.","vn":"Anh ấy là nhân viên phục vụ."}]},{"hanzi":"女士","pinyin":"nǚshì","pos":"dt.","vn":"quý bà, cô","examples":[{"cn":"这位女士是谁？","pinyin":"Zhè wèi nǚshì shì shéi?","vn":"Vị quý bà này là ai?"},{"cn":"女士，请坐。","pinyin":"Nǚshì, qǐng zuò.","vn":"Thưa quý bà, mời ngồi."},{"cn":"那位女士很好。","pinyin":"Nà wèi nǚshì hěn hǎo.","vn":"Vị quý bà đó rất tốt."}]},{"hanzi":"请","pinyin":"qǐng","pos":"dgt.","vn":"mời, xin mời","examples":[{"cn":"请坐。","pinyin":"Qǐng zuò.","vn":"Mời ngồi."},{"cn":"请喝茶。","pinyin":"Qǐng hē chá.","vn":"Mời uống trà."},{"cn":"我请你吃饭。","pinyin":"Wǒ qǐng nǐ chīfàn.","vn":"Tôi mời bạn ăn cơm."}]},{"hanzi":"坐","pinyin":"zuò","pos":"dgt.","vn":"ngồi","examples":[{"cn":"请坐这儿。","pinyin":"Qǐng zuò zhèr.","vn":"Mời ngồi đây."},{"cn":"他坐在那儿。","pinyin":"Tā zuò zài nàr.","vn":"Anh ấy ngồi ở đó."},{"cn":"我们坐火车。","pinyin":"Wǒmen zuò huǒchē.","vn":"Chúng tôi đi tàu hỏa."}]},{"hanzi":"给","pinyin":"gěi","pos":"dgt.","vn":"cho, đưa","examples":[{"cn":"请给我一杯茶。","pinyin":"Qǐng gěi wǒ yì bēi chá.","vn":"Xin cho tôi một ly trà."},{"cn":"我给你打电话。","pinyin":"Wǒ gěi nǐ dǎ diànhuà.","vn":"Tôi gọi điện cho bạn."},{"cn":"他给我面包。","pinyin":"Tā gěi wǒ miànbāo.","vn":"Anh ấy đưa cho tôi bánh mì."}]},{"hanzi":"杯","pinyin":"bēi","pos":"dt.","vn":"cốc, ly","examples":[{"cn":"我要一杯茶。","pinyin":"Wǒ yào yì bēi chá.","vn":"Tôi muốn một ly trà."},{"cn":"这杯茶很好喝。","pinyin":"Zhè bēi chá hěn hǎohē.","vn":"Ly trà này rất ngon."},{"cn":"再给我一杯。","pinyin":"Zài gěi wǒ yì bēi.","vn":"Cho tôi thêm một ly nữa."}]},{"hanzi":"要","pinyin":"yào","pos":"dgt.","vn":"muốn, gọi (món)","examples":[{"cn":"我要一个面包。","pinyin":"Wǒ yào yí ge miànbāo.","vn":"Tôi muốn một cái bánh mì."},{"cn":"你要什么？","pinyin":"Nǐ yào shénme?","vn":"Bạn muốn gì?"},{"cn":"他要喝茶。","pinyin":"Tā yào hē chá.","vn":"Anh ấy muốn uống trà."}]},{"hanzi":"早饭","pinyin":"zǎofàn","pos":"dt.","vn":"bữa sáng","examples":[{"cn":"我吃早饭了。","pinyin":"Wǒ chī zǎofàn le.","vn":"Tôi ăn sáng rồi."},{"cn":"早饭有鸡蛋。","pinyin":"Zǎofàn yǒu jīdàn.","vn":"Bữa sáng có trứng gà."},{"cn":"你吃早饭了吗？","pinyin":"Nǐ chī zǎofàn le ma?","vn":"Bạn ăn sáng chưa?"}]},{"hanzi":"这个","pinyin":"zhège","pos":"đt.","vn":"cái này","examples":[{"cn":"这个多少钱？","pinyin":"Zhège duōshao qián?","vn":"Cái này bao nhiêu tiền?"},{"cn":"我要这个。","pinyin":"Wǒ yào zhège.","vn":"Tôi muốn cái này."},{"cn":"这个很好吃。","pinyin":"Zhège hěn hǎochī.","vn":"Cái này rất ngon."}]},{"hanzi":"面包","pinyin":"miànbāo","pos":"dt.","vn":"bánh mì","examples":[{"cn":"我喜欢吃面包。","pinyin":"Wǒ xǐhuan chī miànbāo.","vn":"Tôi thích ăn bánh mì."},{"cn":"这个面包很好吃。","pinyin":"Zhège miànbāo hěn hǎochī.","vn":"Bánh mì này rất ngon."},{"cn":"早饭有面包。","pinyin":"Zǎofàn yǒu miànbāo.","vn":"Bữa sáng có bánh mì."}]},{"hanzi":"鸡蛋","pinyin":"jīdàn","pos":"dt.","vn":"trứng gà","examples":[{"cn":"我要两个鸡蛋。","pinyin":"Wǒ yào liǎng ge jīdàn.","vn":"Tôi muốn hai quả trứng."},{"cn":"早饭有鸡蛋。","pinyin":"Zǎofàn yǒu jīdàn.","vn":"Bữa sáng có trứng."},{"cn":"这个鸡蛋很好吃。","pinyin":"Zhège jīdàn hěn hǎochī.","vn":"Quả trứng này rất ngon."}]},{"hanzi":"先生","pinyin":"xiānsheng","pos":"dt.","vn":"ông, quý ông","examples":[{"cn":"先生，您好。","pinyin":"Xiānsheng, nín hǎo.","vn":"Chào ông."},{"cn":"这位先生是老师。","pinyin":"Zhè wèi xiānsheng shì lǎoshī.","vn":"Vị ông này là giáo viên."},{"cn":"先生，请坐。","pinyin":"Xiānsheng, qǐng zuò.","vn":"Mời ông ngồi."}]},{"hanzi":"一半","pinyin":"yíbàn","pos":"số.","vn":"một nửa","examples":[{"cn":"我吃了一半。","pinyin":"Wǒ chī le yíbàn.","vn":"Tôi ăn hết một nửa rồi."},{"cn":"给我一半。","pinyin":"Gěi wǒ yíbàn.","vn":"Đưa tôi một nửa."},{"cn":"这是一半。","pinyin":"Zhè shì yíbàn.","vn":"Đây là một nửa."}]},{"hanzi":"茶","pinyin":"chá","pos":"dt.","vn":"trà","examples":[{"cn":"我喜欢喝茶。","pinyin":"Wǒ xǐhuan hē chá.","vn":"Tôi thích uống trà."},{"cn":"请给我一杯茶。","pinyin":"Qǐng gěi wǒ yì bēi chá.","vn":"Xin cho tôi một ly trà."},{"cn":"这个茶很好喝。","pinyin":"Zhège chá hěn hǎohē.","vn":"Trà này rất ngon."}]}],"grammar":[{"title":"能愿动词“可以”","explanation_vn":"Động từ năng nguyện \"可以\" đứng trước động từ, biểu thị khả năng, năng lực hoặc sự cho phép.","examples":[{"cn":"我可以再问您一个问题吗？","pinyin":"Wǒ kěyǐ zài wèn nín yí gè wèntí ma?","vn":"Em có thể hỏi cô thêm một câu hỏi được không ạ?"},{"cn":"你们可以看这本书。","pinyin":"Nǐmen kěyǐ kàn zhè běn shū.","vn":"Các em có thể xem quyển sách này."},{"cn":"A：我可以坐吗？B：可以，请坐！","pinyin":"A: Wǒ kěyǐ zuò ma? B: Kěyǐ, qǐng zuò!","vn":"A: Tôi ngồi được không? B: Được, mời ngồi!"}]},{"title":"“动词+一下”结构","explanation_vn":"Trong bài này, cấu trúc \"động từ + 一下\" biểu thị một hành động được thực hiện thử hoặc diễn ra trong thời gian ngắn.","examples":[{"cn":"你可以打电话问一下。","pinyin":"Nǐ kěyǐ dǎ diànhuà wèn yíxià.","vn":"Bạn có thể gọi điện hỏi thử xem."},{"cn":"请休息一下。","pinyin":"Qǐng xiūxi yíxià.","vn":"Mời nghỉ một chút."},{"cn":"你看一下吧。","pinyin":"Nǐ kàn yíxià ba.","vn":"Bạn xem thử xem."}]},{"title":"双宾语句（1）","explanation_vn":"Câu song tân ngữ là câu mà một động từ mang theo hai tân ngữ. Trong quyển này, chúng ta học câu song tân ngữ được tạo thành bởi \"给\" và \"问\".","examples":[{"cn":"请给我一杯牛奶。","pinyin":"Qǐng gěi wǒ yì bēi niúnǎi.","vn":"Làm ơn cho tôi một cốc sữa."},{"cn":"白家月给安妮一个苹果。","pinyin":"Bái Jiāyuè gěi Ānnī yí gè píngguǒ.","vn":"Bạch Gia Nguyệt cho Annie một quả táo."},{"cn":"我问老师两个问题。","pinyin":"Wǒ wèn lǎoshī liǎng gè wèntí.","vn":"Tôi hỏi thầy/cô hai câu hỏi."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"王老师，我可以再问您一个问题吗？","pinyin":"Wáng lǎoshī, wǒ kěyǐ zài wèn nín yí gè wèntí ma?"},{"speaker":"王一飞","cn":"可以。你有什么问题？","pinyin":"Kěyǐ. Nǐ yǒu shénme wèntí?"},{"speaker":"白家月","cn":"那个小店卖不卖手机？","pinyin":"Nàge xiǎo diàn mài bu mài shǒujī?"},{"speaker":"王一飞","cn":"我不知道。你可以打电话问一下。","pinyin":"Wǒ bù zhīdào. Nǐ kěyǐ dǎ diànhuà wèn yíxià."}],"translation_vn":"Bạch Gia Nguyệt: Cô Vương ơi, em có thể hỏi cô thêm một câu được không ạ?\nVương Nhất Phi: Được chứ. Em có câu hỏi gì?\nBạch Gia Nguyệt: Cửa hàng nhỏ đó có bán điện thoại di động không ạ?\nVương Nhất Phi: Cô không biết. Em có thể gọi điện hỏi thử xem.","audio_dialogue":"13-1.mp3","audio_vocab":"13-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"服务员","cn":"女士，请坐！您喝什么？","pinyin":"Nǚshì, qǐng zuò! Nín hē shénme?"},{"speaker":"王一雪","cn":"我看一下。请给我一杯牛奶。","pinyin":"Wǒ kàn yíxià. Qǐng gěi wǒ yì bēi niúnǎi."},{"speaker":"服务员","cn":"好的。您还要什么？","pinyin":"Hǎo de. Nín hái yào shénme?"},{"speaker":"王一雪","cn":"我还没吃早饭，再要这个面包和鸡蛋吧。","pinyin":"Wǒ hái méi chī zǎofàn, zài yào zhège miànbāo hé jīdàn ba."}],"translation_vn":"Phục vụ: Thưa quý cô, mời ngồi! Cô muốn uống gì ạ?\nVương Nhất Tuyết: Để tôi xem đã. Cho tôi một cốc sữa.\nPhục vụ: Vâng ạ. Cô còn muốn dùng gì nữa không?\nVương Nhất Tuyết: Tôi vẫn chưa ăn sáng, cho tôi thêm bánh mì và trứng này nữa nhé.","audio_dialogue":"13-3.mp3","audio_vocab":"13-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"服务员","cn":"先生，请坐！您要什么？","pinyin":"Xiānsheng, qǐng zuò! Nín yào shénme?"},{"speaker":"刘明","cn":"我要一斤饺子。","pinyin":"Wǒ yào yì jīn jiǎozi."},{"speaker":"服务员","cn":"好的。一斤饺子40个。","pinyin":"Hǎo de. Yì jīn jiǎozi sìshí gè."},{"speaker":"刘明","cn":"40个太多了，我要一半吧。","pinyin":"Sìshí gè tài duō le, wǒ yào yíbàn ba."},{"speaker":"服务员","cn":"半斤20个。您想喝什么？","pinyin":"Bàn jīn èrshí gè. Nín xiǎng hē shénme?"},{"speaker":"刘明","cn":"请给我一杯茶吧。","pinyin":"Qǐng gěi wǒ yì bēi chá ba."}],"translation_vn":"Phục vụ: Thưa ông, mời ngồi! Ông muốn dùng gì ạ?\nLưu Minh: Tôi muốn một cân sủi cảo.\nPhục vụ: Vâng ạ. Một cân sủi cảo có 40 cái.\nLưu Minh: 40 cái nhiều quá, cho tôi nửa cân thôi.\nPhục vụ: Nửa cân là 20 cái ạ. Ông muốn uống gì?\nLưu Minh: Cho tôi một cốc trà nhé.","audio_dialogue":"13-5.mp3","audio_vocab":"13-6.mp3"}]},{"id":14,"title_cn":"我看了一个电影","title_pinyin":"Wǒ kànle yí gè diànyǐng","title_vn":"Tôi đã xem một bộ phim","goals":["Có thể nghe hiểu và sử dụng trợ từ động thái \"了(2)\" để diễn đạt hành động đã xảy ra hoặc đã hoàn thành.","Nắm vững cách dùng phó từ phạm vi \"都\".","Nắm vững cách dùng cơ bản của một số từ ly hợp.","Hiểu và có thể miêu tả tình hình học tập."],"vocab":[{"hanzi":"上","pinyin":"shàng","pos":"dgt.","vn":"lên (xe), lên (tàu)","examples":[{"cn":"我们上火车吧。","pinyin":"Wǒmen shàng huǒchē ba.","vn":"Chúng ta lên tàu hỏa thôi."},{"cn":"他上车了。","pinyin":"Tā shàng chē le.","vn":"Anh ấy lên xe rồi."},{"cn":"请快上车。","pinyin":"Qǐng kuài shàng chē.","vn":"Xin nhanh lên xe."}]},{"hanzi":"火车","pinyin":"huǒchē","pos":"dt.","vn":"tàu hỏa","examples":[{"cn":"我坐火车去北京。","pinyin":"Wǒ zuò huǒchē qù Běijīng.","vn":"Tôi đi tàu hỏa đến Bắc Kinh."},{"cn":"火车几点开？","pinyin":"Huǒchē jǐ diǎn kāi?","vn":"Mấy giờ tàu chạy?"},{"cn":"这是去西安的火车。","pinyin":"Zhè shì qù Xī'ān de huǒchē.","vn":"Đây là tàu đi Tây An."}]},{"hanzi":"中午","pinyin":"zhōngwǔ","pos":"dt.","vn":"buổi trưa","examples":[{"cn":"中午我们吃饭。","pinyin":"Zhōngwǔ wǒmen chīfàn.","vn":"Buổi trưa chúng ta ăn cơm."},{"cn":"火车中午开。","pinyin":"Huǒchē zhōngwǔ kāi.","vn":"Tàu chạy vào buổi trưa."},{"cn":"现在是中午。","pinyin":"Xiànzài shì zhōngwǔ.","vn":"Bây giờ là buổi trưa."}]},{"hanzi":"开","pinyin":"kāi","pos":"dgt.","vn":"khởi hành, chạy (xe)","examples":[{"cn":"火车几点开？","pinyin":"Huǒchē jǐ diǎn kāi?","vn":"Mấy giờ tàu chạy?"},{"cn":"他开车去机场。","pinyin":"Tā kāi chē qù jīchǎng.","vn":"Anh ấy lái xe đến sân bay."},{"cn":"飞机要开了。","pinyin":"Fēijī yào kāi le.","vn":"Máy bay sắp chạy rồi."}]},{"hanzi":"有些","pinyin":"yǒuxiē","pos":"đt.","vn":"một số, có người","examples":[{"cn":"有些人喜欢茶。","pinyin":"Yǒuxiē rén xǐhuan chá.","vn":"Một số người thích trà."},{"cn":"有些字很难。","pinyin":"Yǒuxiē zì hěn nán.","vn":"Một số chữ rất khó."},{"cn":"有些问题我不懂。","pinyin":"Yǒuxiē wèntí wǒ bù dǒng.","vn":"Một số câu hỏi tôi không hiểu."}]},{"hanzi":"有的","pinyin":"yǒude","pos":"đt.","vn":"có người, có cái","examples":[{"cn":"有的人上学，有的人工作。","pinyin":"Yǒude rén shàngxué, yǒude rén gōngzuò.","vn":"Có người đi học, có người đi làm."},{"cn":"有的字我认识。","pinyin":"Yǒude zì wǒ rènshi.","vn":"Có chữ tôi biết."},{"cn":"有的学生很忙。","pinyin":"Yǒude xuésheng hěn máng.","vn":"Có học sinh rất bận."}]},{"hanzi":"了","pinyin":"le","pos":"trợ.","vn":"rồi (trợ từ hoàn thành)","examples":[{"cn":"我吃饭了。","pinyin":"Wǒ chīfàn le.","vn":"Tôi ăn cơm rồi."},{"cn":"他走了。","pinyin":"Tā zǒu le.","vn":"Anh ấy đi rồi."},{"cn":"火车开了。","pinyin":"Huǒchē kāi le.","vn":"Tàu chạy rồi."}]},{"hanzi":"写","pinyin":"xiě","pos":"dgt.","vn":"viết","examples":[{"cn":"我在写字。","pinyin":"Wǒ zài xiě zì.","vn":"Tôi đang viết chữ."},{"cn":"你会写汉字吗？","pinyin":"Nǐ huì xiě Hànzì ma?","vn":"Bạn biết viết chữ Hán không?"},{"cn":"他写了一个字。","pinyin":"Tā xiě le yí ge zì.","vn":"Anh ấy viết một chữ."}]},{"hanzi":"都","pinyin":"dōu","pos":"phó.","vn":"đều","examples":[{"cn":"我们都是学生。","pinyin":"Wǒmen dōu shì xuésheng.","vn":"Chúng tôi đều là học sinh."},{"cn":"他们都喜欢茶。","pinyin":"Tāmen dōu xǐhuan chá.","vn":"Họ đều thích trà."},{"cn":"这些字我都认识。","pinyin":"Zhèxiē zì wǒ dōu rènshi.","vn":"Những chữ này tôi đều biết."}]},{"hanzi":"听见","pinyin":"tīngjiàn","pos":"dgt.","vn":"nghe thấy","examples":[{"cn":"我听见了。","pinyin":"Wǒ tīngjiàn le.","vn":"Tôi nghe thấy rồi."},{"cn":"你听见他说话了吗？","pinyin":"Nǐ tīngjiàn tā shuōhuà le ma?","vn":"Bạn có nghe thấy anh ấy nói không?"},{"cn":"我没听见。","pinyin":"Wǒ méi tīngjiàn.","vn":"Tôi không nghe thấy."}]},{"hanzi":"不要","pinyin":"búyào","pos":"phó.","vn":"đừng, không nên","examples":[{"cn":"不要说话。","pinyin":"Búyào shuōhuà.","vn":"Đừng nói chuyện."},{"cn":"不要走。","pinyin":"Búyào zǒu.","vn":"Đừng đi."},{"cn":"不要哭。","pinyin":"Búyào kū.","vn":"Đừng khóc."}]},{"hanzi":"说话","pinyin":"shuōhuà","pos":"dgt.","vn":"nói chuyện","examples":[{"cn":"请不要说话。","pinyin":"Qǐng búyào shuōhuà.","vn":"Xin đừng nói chuyện."},{"cn":"他在说话。","pinyin":"Tā zài shuōhuà.","vn":"Anh ấy đang nói chuyện."},{"cn":"我们说话吧。","pinyin":"Wǒmen shuōhuà ba.","vn":"Chúng ta nói chuyện đi."}]},{"hanzi":"听","pinyin":"tīng","pos":"dgt.","vn":"nghe","examples":[{"cn":"我喜欢听音乐。","pinyin":"Wǒ xǐhuan tīng yīnyuè.","vn":"Tôi thích nghe nhạc."},{"cn":"请听我说。","pinyin":"Qǐng tīng wǒ shuō.","vn":"Xin hãy nghe tôi nói."},{"cn":"你在听吗？","pinyin":"Nǐ zài tīng ma?","vn":"Bạn đang nghe không?"}]},{"hanzi":"哪些","pinyin":"nǎxiē","pos":"đt.","vn":"những...nào","examples":[{"cn":"哪些字是汉字？","pinyin":"Nǎxiē zì shì Hànzì?","vn":"Những chữ nào là chữ Hán?"},{"cn":"你喜欢哪些茶？","pinyin":"Nǐ xǐhuan nǎxiē chá?","vn":"Bạn thích những loại trà nào?"},{"cn":"哪些人上学？","pinyin":"Nǎxiē rén shàngxué?","vn":"Những người nào đi học?"}]},{"hanzi":"字","pinyin":"zì","pos":"dt.","vn":"chữ","examples":[{"cn":"这个字很难。","pinyin":"Zhège zì hěn nán.","vn":"Chữ này rất khó."},{"cn":"我会写这个字。","pinyin":"Wǒ huì xiě zhège zì.","vn":"Tôi biết viết chữ này."},{"cn":"这是什么字？","pinyin":"Zhè shì shénme zì?","vn":"Đây là chữ gì?"}]},{"hanzi":"汉语","pinyin":"Hànyǔ","pos":"danh từ riêng","vn":"tiếng Hán","examples":[{"cn":"我在学汉语。","pinyin":"Wǒ zài xué Hànyǔ.","vn":"Tôi đang học tiếng Hán."},{"cn":"你会说汉语吗？","pinyin":"Nǐ huì shuō Hànyǔ ma?","vn":"Bạn biết nói tiếng Hán không?"},{"cn":"汉语很有意思。","pinyin":"Hànyǔ hěn yǒu yìsi.","vn":"Tiếng Hán rất thú vị."}]},{"hanzi":"汉字","pinyin":"Hànzì","pos":"danh từ riêng","vn":"chữ Hán","examples":[{"cn":"汉字很难写。","pinyin":"Hànzì hěn nán xiě.","vn":"Chữ Hán rất khó viết."},{"cn":"我喜欢汉字。","pinyin":"Wǒ xǐhuan Hànzì.","vn":"Tôi thích chữ Hán."},{"cn":"他会写汉字。","pinyin":"Tā huì xiě Hànzì.","vn":"Anh ấy biết viết chữ Hán."}]},{"hanzi":"明年","pinyin":"míngnián","pos":"dt.","vn":"năm sau","examples":[{"cn":"明年我去北京。","pinyin":"Míngnián wǒ qù Běijīng.","vn":"Năm sau tôi đi Bắc Kinh."},{"cn":"明年他上中学。","pinyin":"Míngnián tā shàng zhōngxué.","vn":"Năm sau anh ấy học trung học."},{"cn":"我们明年见。","pinyin":"Wǒmen míngnián jiàn.","vn":"Sang năm gặp lại nhé."}]},{"hanzi":"上","pinyin":"shàng","pos":"dgt.","vn":"bắt đầu (một việc gì đó đúng giờ)","examples":[{"cn":"几点上课？","pinyin":"Jǐ diǎn shàngkè?","vn":"Mấy giờ vào học?"},{"cn":"我们八点上班。","pinyin":"Wǒmen bā diǎn shàngbān.","vn":"Chúng tôi 8 giờ bắt đầu làm việc."},{"cn":"他九点上课。","pinyin":"Tā jiǔ diǎn shàngkè.","vn":"Anh ấy 9 giờ vào lớp."}]},{"hanzi":"中学","pinyin":"zhōngxué","pos":"dt.","vn":"trường trung học","examples":[{"cn":"我在中学学习。","pinyin":"Wǒ zài zhōngxué xuéxí.","vn":"Tôi học ở trường trung học."},{"cn":"他是中学老师。","pinyin":"Tā shì zhōngxué lǎoshī.","vn":"Anh ấy là giáo viên trung học."},{"cn":"这是一所中学。","pinyin":"Zhè shì yì suǒ zhōngxué.","vn":"Đây là một trường trung học."}]},{"hanzi":"小学","pinyin":"xiǎoxué","pos":"dt.","vn":"trường tiểu học","examples":[{"cn":"我在小学学习。","pinyin":"Wǒ zài xiǎoxué xuéxí.","vn":"Tôi học ở trường tiểu học."},{"cn":"她是小学老师。","pinyin":"Tā shì xiǎoxué lǎoshī.","vn":"Cô ấy là giáo viên tiểu học."},{"cn":"这所小学很大。","pinyin":"Zhè suǒ xiǎoxué hěn dà.","vn":"Trường tiểu học này rất lớn."}]},{"hanzi":"中学生","pinyin":"zhōngxuéshēng","pos":"dt.","vn":"học sinh trung học","examples":[{"cn":"我是中学生。","pinyin":"Wǒ shì zhōngxuéshēng.","vn":"Tôi là học sinh trung học."},{"cn":"他是一个中学生。","pinyin":"Tā shì yí ge zhōngxuéshēng.","vn":"Anh ấy là một học sinh trung học."},{"cn":"中学生很忙。","pinyin":"Zhōngxuéshēng hěn máng.","vn":"Học sinh trung học rất bận."}]},{"hanzi":"小学生","pinyin":"xiǎoxuéshēng","pos":"dt.","vn":"học sinh tiểu học","examples":[{"cn":"我弟弟是小学生。","pinyin":"Wǒ dìdi shì xiǎoxuéshēng.","vn":"Em trai tôi là học sinh tiểu học."},{"cn":"小学生在上课。","pinyin":"Xiǎoxuéshēng zài shàngkè.","vn":"Học sinh tiểu học đang học."},{"cn":"她是小学生。","pinyin":"Tā shì xiǎoxuéshēng.","vn":"Cô bé là học sinh tiểu học."}]},{"hanzi":"上学","pinyin":"shàngxué","pos":"dgt.","vn":"đi học","examples":[{"cn":"我每天上学。","pinyin":"Wǒ měitiān shàngxué.","vn":"Tôi đi học mỗi ngày."},{"cn":"他八点上学。","pinyin":"Tā bā diǎn shàngxué.","vn":"Anh ấy 8 giờ đi học."},{"cn":"明天我不上学。","pinyin":"Míngtiān wǒ bú shàngxué.","vn":"Ngày mai tôi không đi học."}]},{"hanzi":"他们","pinyin":"tāmen","pos":"đt.","vn":"họ, bọn họ","examples":[{"cn":"他们是学生。","pinyin":"Tāmen shì xuésheng.","vn":"Họ là học sinh."},{"cn":"他们在说话。","pinyin":"Tāmen zài shuōhuà.","vn":"Họ đang nói chuyện."},{"cn":"我喜欢他们。","pinyin":"Wǒ xǐhuan tāmen.","vn":"Tôi thích họ."}]},{"hanzi":"她们","pinyin":"tāmen","pos":"đt.","vn":"họ (chỉ nữ giới)","examples":[{"cn":"她们是老师。","pinyin":"Tāmen shì lǎoshī.","vn":"Họ (nữ) là giáo viên."},{"cn":"她们在上课。","pinyin":"Tāmen zài shàngkè.","vn":"Các cô ấy đang học."},{"cn":"我认识她们。","pinyin":"Wǒ rènshi tāmen.","vn":"Tôi quen các cô ấy."}]},{"hanzi":"它们","pinyin":"tāmen","pos":"đt.","vn":"chúng nó","examples":[{"cn":"它们是我的书。","pinyin":"Tāmen shì wǒ de shū.","vn":"Chúng là sách của tôi."},{"cn":"我喜欢它们。","pinyin":"Wǒ xǐhuan tāmen.","vn":"Tôi thích chúng."},{"cn":"它们很小。","pinyin":"Tāmen hěn xiǎo.","vn":"Chúng rất nhỏ."}]},{"hanzi":"晚","pinyin":"wǎn","pos":"tt.","vn":"muộn","examples":[{"cn":"我来晚了。","pinyin":"Wǒ lái wǎn le.","vn":"Tôi đến muộn rồi."},{"cn":"现在很晚了。","pinyin":"Xiànzài hěn wǎn le.","vn":"Bây giờ đã muộn rồi."},{"cn":"火车开得很晚。","pinyin":"Huǒchē kāi de hěn wǎn.","vn":"Tàu chạy rất muộn."}]}],"grammar":[{"title":"动态助词“了（2）”","explanation_vn":"Trợ từ động thái \"了(2)\" đặt sau động từ, biểu thị hành động đã xảy ra hoặc đã hoàn thành. Khi phủ định, dùng \"没\" và bỏ \"了\".","examples":[{"cn":"我看了一个电影。","pinyin":"Wǒ kànle yí gè diànyǐng.","vn":"Tôi đã xem một bộ phim."},{"cn":"我买了一个新电脑。","pinyin":"Wǒ mǎile yí gè xīn diànnǎo.","vn":"Tôi đã mua một chiếc máy tính mới."},{"cn":"我昨天没去商店买东西。","pinyin":"Wǒ zuótiān méi qù shāngdiàn mǎi dōngxi.","vn":"Hôm qua tôi không đi cửa hàng mua đồ."}]},{"title":"离合词（1）","explanation_vn":"Các từ như \"上课、下课、上班、下班、说话、读书、睡觉、看病、生病\" trong quyển này thuộc một loại kết cấu động từ đặc biệt, có thể tách hoặc ghép: khi ghép lại thì là một từ, khi chèn thêm thành phần khác vào giữa thì trở thành cụm từ. Vì vậy chúng được gọi là từ ly hợp. Khi tách ra, thành phần có thể chèn vào bị hạn chế.","examples":[{"cn":"睡觉 → 睡了觉；睡了一觉","pinyin":"Shuìjiào → Shuìle jiào; shuìle yí jiào","vn":"ngủ → đã ngủ; đã ngủ một giấc"},{"cn":"上课 → 上了课；上中文课","pinyin":"Shàngkè → Shàngle kè; shàng Zhōngwén kè","vn":"lên lớp → đã lên lớp; học tiết tiếng Trung"},{"cn":"说话 → 说了话；说了很多话","pinyin":"Shuōhuà → Shuōle huà; shuōle hěn duō huà","vn":"nói chuyện → đã nói chuyện; đã nói rất nhiều"}]},{"title":"范围副词“都”","explanation_vn":"Phó từ phạm vi \"都\" biểu thị toàn bộ, tổng quát; đối tượng được tổng quát đặt trước \"都\". Khi phủ định, từ phủ định đặt sau \"都\".","examples":[{"cn":"我们都会写了。","pinyin":"Wǒmen dōu huì xiě le.","vn":"Chúng tôi đều biết viết rồi."},{"cn":"我和我的朋友们都去。","pinyin":"Wǒ hé wǒ de péngyoumen dōu qù.","vn":"Tôi và các bạn tôi đều đi."},{"cn":"同学们都没听见。","pinyin":"Tóngxuémen dōu méi tīngjiàn.","vn":"Các bạn học sinh đều không nghe thấy."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"你们上火车后看见王老师了吗？","pinyin":"Nǐmen shàng huǒchē hòu kànjiàn Wáng lǎoshī le ma?"},{"speaker":"陈天中","cn":"没看见。中午车开后，有些人在看书，有些人睡觉了。","pinyin":"Méi kànjiàn. Zhōngwǔ chē kāi hòu, yǒuxiē rén zài kàn shū, yǒuxiē rén shuìjiào le."},{"speaker":"白家月","cn":"你呢？","pinyin":"Nǐ ne?"},{"speaker":"陈天中","cn":"我看了一个电影。","pinyin":"Wǒ kànle yí gè diànyǐng."}],"translation_vn":"Bạch Gia Nguyệt: Sau khi lên tàu các bạn có nhìn thấy cô Vương không?\nTrần Thiên Trung: Không thấy. Sau khi tàu chạy vào buổi trưa, có người đọc sách, có người ngủ.\nBạch Gia Nguyệt: Còn bạn thì sao?\nTrần Thiên Trung: Mình đã xem một bộ phim.","audio_dialogue":"14-1.mp3","audio_vocab":"14-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一飞","cn":"你们会说汉语了，也会写汉字了吗？","pinyin":"Nǐmen huì shuō Hànyǔ le, yě huì xiě Hànzì le ma?"},{"speaker":"白家月","cn":"我们都会写了。","pinyin":"Wǒmen dōu huì xiě le."},{"speaker":"陈天中","cn":"老师，我听不见。","pinyin":"Lǎoshī, wǒ tīng bú jiàn."},{"speaker":"王一飞","cn":"请大家不要说话！请听老师的问题：你们都会写哪些汉字了？","pinyin":"Qǐng dàjiā búyào shuōhuà! Qǐng tīng lǎoshī de wèntí: Nǐmen dōu huì xiě nǎxiē Hànzì le?"},{"speaker":"陈天中","cn":"我会写这些字了，您看！","pinyin":"Wǒ huì xiě zhèxiē zì le, nín kàn!"}],"translation_vn":"Vương Nhất Phi: Các em đã biết nói tiếng Hán rồi, cũng biết viết chữ Hán rồi chứ?\nBạch Gia Nguyệt: Chúng em đều biết viết rồi ạ.\nTrần Thiên Trung: Thưa cô, em không nghe rõ ạ.\nVương Nhất Phi: Mời cả lớp đừng nói chuyện! Hãy nghe câu hỏi của cô: Các em biết viết những chữ Hán nào rồi?\nTrần Thiên Trung: Em biết viết những chữ này rồi, cô xem này!","audio_dialogue":"14-3.mp3","audio_vocab":"14-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"刘明","cn":"明年女儿上中学。","pinyin":"Míngnián nǚ'ér shàng zhōngxué."},{"speaker":"王一雪","cn":"对。儿子也上小学了。","pinyin":"Duì. Érzi yě shàng xiǎoxué le."},{"speaker":"刘明","cn":"我们家有了一个中学生。","pinyin":"Wǒmen jiā yǒule yí gè zhōngxuéshēng."},{"speaker":"王一雪","cn":"还有了一个小学生。","pinyin":"Hái yǒule yí gè xiǎoxuéshēng."},{"speaker":"刘明","cn":"上学后，他们都忙了。","pinyin":"Shàngxué hòu, tāmen dōu máng le."},{"speaker":"王一雪","cn":"是的。太晚了，睡觉吧。","pinyin":"Shì de. Tài wǎn le, shuìjiào ba."}],"translation_vn":"Lưu Minh: Năm sau con gái sẽ lên trung học.\nVương Nhất Tuyết: Đúng vậy. Con trai cũng sẽ vào tiểu học rồi.\nLưu Minh: Nhà mình sắp có một học sinh trung học rồi.\nVương Nhất Tuyết: Còn có thêm một học sinh tiểu học nữa.\nLưu Minh: Sau khi đi học, cả hai đứa đều sẽ bận rộn.\nVương Nhất Tuyết: Đúng vậy. Muộn rồi, đi ngủ thôi.","audio_dialogue":"14-5.mp3","audio_vocab":"14-6.mp3"}]},{"id":15,"title_cn":"大兴机场见！","title_pinyin":"Dàxīng Jīchǎng jiàn!","title_vn":"Hẹn gặp ở sân bay Đại Hưng!","goals":["Có thể nghe hiểu và sử dụng các từ ngữ liên quan để diễn đạt ý định, kế hoạch đi du lịch.","Nắm vững câu phức liên hợp \"……, 还/也……\".","Hiểu văn hóa bàn ăn và lễ nghi đãi khách của Trung Quốc.","Hiểu về thủ đô của Trung Quốc — Bắc Kinh."],"vocab":[{"hanzi":"爱","pinyin":"ài","pos":"dgt.","vn":"yêu thích, thích","examples":[{"cn":"我爱我的家人。","pinyin":"Wǒ ài wǒ de jiārén.","vn":"Tôi yêu gia đình tôi."},{"cn":"他爱她。","pinyin":"Tā ài tā.","vn":"Anh ấy yêu cô ấy."},{"cn":"我爱喝茶。","pinyin":"Wǒ ài hē chá.","vn":"Tôi rất thích uống trà."}]},{"hanzi":"哪个","pinyin":"nǎge","pos":"đt.","vn":"cái nào","examples":[{"cn":"你要哪个？","pinyin":"Nǐ yào nǎge?","vn":"Bạn muốn cái nào?"},{"cn":"哪个是你的？","pinyin":"Nǎge shì nǐ de?","vn":"Cái nào là của bạn?"},{"cn":"你喜欢哪个？","pinyin":"Nǐ xǐhuan nǎge?","vn":"Bạn thích cái nào?"}]},{"hanzi":"去年","pinyin":"qùnián","pos":"dt.","vn":"năm ngoái","examples":[{"cn":"去年我去了北京。","pinyin":"Qùnián wǒ qù le Běijīng.","vn":"Năm ngoái tôi đã đi Bắc Kinh."},{"cn":"去年他上中学。","pinyin":"Qùnián tā shàng zhōngxué.","vn":"Năm ngoái anh ấy học trung học."},{"cn":"我去年认识她。","pinyin":"Wǒ qùnián rènshi tā.","vn":"Năm ngoái tôi quen cô ấy."}]},{"hanzi":"男朋友","pinyin":"nánpéngyou","pos":"dt.","vn":"bạn trai","examples":[{"cn":"她有男朋友了。","pinyin":"Tā yǒu nánpéngyou le.","vn":"Cô ấy có bạn trai rồi."},{"cn":"这是我男朋友。","pinyin":"Zhè shì wǒ nánpéngyou.","vn":"Đây là bạn trai của tôi."},{"cn":"她男朋友很帅。","pinyin":"Tā nánpéngyou hěn shuài.","vn":"Bạn trai của cô ấy rất đẹp trai."}]},{"hanzi":"几","pinyin":"jǐ","pos":"số.","vn":"vài, mấy","examples":[{"cn":"现在几点？","pinyin":"Xiànzài jǐ diǎn?","vn":"Bây giờ mấy giờ?"},{"cn":"你家有几个人？","pinyin":"Nǐ jiā yǒu jǐ ge rén?","vn":"Nhà bạn có mấy người?"},{"cn":"我有几本书。","pinyin":"Wǒ yǒu jǐ běn shū.","vn":"Tôi có vài cuốn sách."}]},{"hanzi":"年","pinyin":"nián","pos":"dt.","vn":"năm","examples":[{"cn":"今年我二十岁。","pinyin":"Jīnnián wǒ èrshí suì.","vn":"Năm nay tôi hai mươi tuổi."},{"cn":"他在北京住了三年。","pinyin":"Tā zài Běijīng zhù le sān nián.","vn":"Anh ấy đã sống ở Bắc Kinh ba năm."},{"cn":"明年见。","pinyin":"Míngnián jiàn.","vn":"Sang năm gặp lại."}]},{"hanzi":"好玩儿","pinyin":"hǎowánr","pos":"tt.","vn":"thú vị, hay","examples":[{"cn":"北京很好玩儿。","pinyin":"Běijīng hěn hǎowánr.","vn":"Bắc Kinh rất thú vị."},{"cn":"这个很好玩儿。","pinyin":"Zhège hěn hǎowánr.","vn":"Cái này rất vui."},{"cn":"西安很好玩儿。","pinyin":"Xī'ān hěn hǎowánr.","vn":"Tây An rất thú vị."}]},{"hanzi":"西安","pinyin":"Xī'ān","pos":"danh từ riêng","vn":"Tây An","examples":[{"cn":"我想去西安。","pinyin":"Wǒ xiǎng qù Xī'ān.","vn":"Tôi muốn đi Tây An."},{"cn":"西安很好玩儿。","pinyin":"Xī'ān hěn hǎowánr.","vn":"Tây An rất thú vị."},{"cn":"他住在西安。","pinyin":"Tā zhù zài Xī'ān.","vn":"Anh ấy sống ở Tây An."}]},{"hanzi":"北京","pinyin":"Běijīng","pos":"danh từ riêng","vn":"Bắc Kinh","examples":[{"cn":"我在北京工作。","pinyin":"Wǒ zài Běijīng gōngzuò.","vn":"Tôi làm việc ở Bắc Kinh."},{"cn":"北京是中国的首都。","pinyin":"Běijīng shì Zhōngguó de shǒudū.","vn":"Bắc Kinh là thủ đô của Trung Quốc."},{"cn":"我想去北京。","pinyin":"Wǒ xiǎng qù Běijīng.","vn":"Tôi muốn đi Bắc Kinh."}]},{"hanzi":"飞机","pinyin":"fēijī","pos":"dt.","vn":"máy bay","examples":[{"cn":"我坐飞机去北京。","pinyin":"Wǒ zuò fēijī qù Běijīng.","vn":"Tôi đi máy bay đến Bắc Kinh."},{"cn":"飞机几点起飞？","pinyin":"Fēijī jǐ diǎn qǐfēi?","vn":"Mấy giờ máy bay cất cánh?"},{"cn":"这是去西安的飞机。","pinyin":"Zhè shì qù Xī'ān de fēijī.","vn":"Đây là máy bay đi Tây An."}]},{"hanzi":"要","pinyin":"yào","pos":"dgt.","vn":"cần, mất (thời gian)","examples":[{"cn":"坐飞机要两个小时。","pinyin":"Zuò fēijī yào liǎng ge xiǎoshí.","vn":"Đi máy bay mất hai tiếng."},{"cn":"去机场要多长时间？","pinyin":"Qù jīchǎng yào duō cháng shíjiān?","vn":"Đến sân bay mất bao lâu?"},{"cn":"这个要三天。","pinyin":"Zhège yào sān tiān.","vn":"Cái này cần ba ngày."}]},{"hanzi":"小时","pinyin":"xiǎoshí","pos":"dt.","vn":"giờ, tiếng đồng hồ","examples":[{"cn":"我等了一个小时。","pinyin":"Wǒ děng le yí ge xiǎoshí.","vn":"Tôi đã đợi một tiếng đồng hồ."},{"cn":"坐火车要三个小时。","pinyin":"Zuò huǒchē yào sān ge xiǎoshí.","vn":"Đi tàu hỏa mất ba tiếng."},{"cn":"还有一个小时。","pinyin":"Hái yǒu yí ge xiǎoshí.","vn":"Còn một tiếng nữa."}]},{"hanzi":"家人","pinyin":"jiārén","pos":"dt.","vn":"người nhà","examples":[{"cn":"我爱我的家人。","pinyin":"Wǒ ài wǒ de jiārén.","vn":"Tôi yêu gia đình tôi."},{"cn":"他的家人在北京。","pinyin":"Tā de jiārén zài Běijīng.","vn":"Gia đình anh ấy ở Bắc Kinh."},{"cn":"家人去机场接我。","pinyin":"Jiārén qù jīchǎng jiē wǒ.","vn":"Gia đình đến sân bay đón tôi."}]},{"hanzi":"时间","pinyin":"shíjiān","pos":"dt.","vn":"thời gian","examples":[{"cn":"我没有时间。","pinyin":"Wǒ méiyǒu shíjiān.","vn":"Tôi không có thời gian."},{"cn":"你有时间吗？","pinyin":"Nǐ yǒu shíjiān ma?","vn":"Bạn có thời gian không?"},{"cn":"时间不早了。","pinyin":"Shíjiān bù zǎo le.","vn":"Thời gian không còn sớm nữa."}]},{"hanzi":"机场","pinyin":"jīchǎng","pos":"dt.","vn":"sân bay","examples":[{"cn":"我在机场等你。","pinyin":"Wǒ zài jīchǎng děng nǐ.","vn":"Tôi đợi bạn ở sân bay."},{"cn":"他去机场接朋友。","pinyin":"Tā qù jīchǎng jiē péngyou.","vn":"Anh ấy đến sân bay đón bạn."},{"cn":"机场很大。","pinyin":"Jīchǎng hěn dà.","vn":"Sân bay rất lớn."}]},{"hanzi":"接","pinyin":"jiē","pos":"dgt.","vn":"đón","examples":[{"cn":"我去机场接你。","pinyin":"Wǒ qù jīchǎng jiē nǐ.","vn":"Tôi đến sân bay đón bạn."},{"cn":"谁接你？","pinyin":"Shéi jiē nǐ?","vn":"Ai đón bạn?"},{"cn":"他来接我了。","pinyin":"Tā lái jiē wǒ le.","vn":"Anh ấy đến đón tôi rồi."}]},{"hanzi":"住","pinyin":"zhù","pos":"dgt.","vn":"ở, sống, lưu trú","examples":[{"cn":"我住在北京。","pinyin":"Wǒ zhù zài Běijīng.","vn":"Tôi sống ở Bắc Kinh."},{"cn":"你住哪儿？","pinyin":"Nǐ zhù nǎr?","vn":"Bạn ở đâu?"},{"cn":"他住在学校。","pinyin":"Tā zhù zài xuéxiào.","vn":"Anh ấy ở trong trường."}]},{"hanzi":"早","pinyin":"zǎo","pos":"tt.","vn":"sớm","examples":[{"cn":"你来早了。","pinyin":"Nǐ lái zǎo le.","vn":"Bạn đến sớm rồi."},{"cn":"我们早点走吧。","pinyin":"Wǒmen zǎo diǎn zǒu ba.","vn":"Chúng ta đi sớm một chút đi."},{"cn":"早上好。","pinyin":"Zǎoshang hǎo.","vn":"Chào buổi sáng."}]},{"hanzi":"那","pinyin":"nà","pos":"liên.","vn":"vậy thì, thế thì","examples":[{"cn":"那我们走吧。","pinyin":"Nà wǒmen zǒu ba.","vn":"Vậy thì chúng ta đi thôi."},{"cn":"那好吧。","pinyin":"Nà hǎo ba.","vn":"Vậy thì được rồi."},{"cn":"那你呢？","pinyin":"Nà nǐ ne?","vn":"Vậy còn bạn thì sao?"}]},{"hanzi":"大兴机场","pinyin":"Dàxīng Jīchǎng","pos":"danh từ riêng","vn":"sân bay Đại Hưng","examples":[{"cn":"我在大兴机场下飞机。","pinyin":"Wǒ zài Dàxīng Jīchǎng xià fēijī.","vn":"Tôi xuống máy bay ở sân bay Đại Hưng."},{"cn":"大兴机场很大。","pinyin":"Dàxīng Jīchǎng hěn dà.","vn":"Sân bay Đại Hưng rất lớn."},{"cn":"他去大兴机场接我。","pinyin":"Tā qù Dàxīng Jīchǎng jiē wǒ.","vn":"Anh ấy đến sân bay Đại Hưng đón tôi."}]}],"grammar":[{"title":"并列复句“……，还/也……”","explanation_vn":"Câu phức liên hợp do hai hoặc nhiều mệnh đề có quan hệ lô-gic và kết cấu đối xứng tạo thành. Trong quyển này, chúng ta học câu phức liên hợp \"……, 还/也……\".","examples":[{"cn":"我喜欢这个，也喜欢那个。","pinyin":"Wǒ xǐhuan zhège, yě xǐhuan nàge.","vn":"Tôi thích cái này, cũng thích cái kia."},{"cn":"王老师是北京人，李文也是北京人。","pinyin":"Wáng lǎoshī shì Běijīng rén, Lǐ Wén yě shì Běijīng rén.","vn":"Cô Vương là người Bắc Kinh, Lý Văn cũng là người Bắc Kinh."},{"cn":"我喜欢喝中国茶，还喜欢吃中国菜。","pinyin":"Wǒ xǐhuan hē Zhōngguó chá, hái xǐhuan chī Zhōngguó cài.","vn":"Tôi thích uống trà Trung Quốc, còn thích ăn món Trung Quốc nữa."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"李文","cn":"你们爱吃哪个菜？","pinyin":"Nǐmen ài chī nǎge cài?"},{"speaker":"白家月","cn":"我喜欢这个，也喜欢那个。","pinyin":"Wǒ xǐhuan zhège, yě xǐhuan nàge."},{"speaker":"陈天中","cn":"这些菜都好吃，还很好看。","pinyin":"Zhèxiē cài dōu hǎochī, hái hěn hǎokàn."},{"speaker":"李文","cn":"我爱吃中国菜，也喜欢做。大家多吃点儿。","pinyin":"Wǒ ài chī Zhōngguó cài, yě xǐhuan zuò. Dàjiā duō chī diǎnr."}],"translation_vn":"Lý Văn: Các bạn thích ăn món nào?\nBạch Gia Nguyệt: Mình thích món này, cũng thích món kia.\nTrần Thiên Trung: Mấy món này đều ngon, lại còn đẹp mắt nữa.\nLý Văn: Mình thích ăn món Trung Quốc, cũng thích nấu nữa. Mọi người ăn nhiều vào nhé.","audio_dialogue":"15-1.mp3","audio_vocab":"15-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"李文","cn":"你们都想去哪儿？","pinyin":"Nǐmen dōu xiǎng qù nǎr?"},{"speaker":"安妮","cn":"去年我和男朋友去了西安，今年我想去北京。","pinyin":"Qùnián wǒ hé nánpéngyou qùle Xī'ān, jīnnián wǒ xiǎng qù Běijīng."},{"speaker":"白家月","cn":"前几年我去了西安，非常好玩儿。今年我也想去北京。","pinyin":"Qián jǐ nián wǒ qùle Xī'ān, fēicháng hǎowánr. Jīnnián wǒ yě xiǎng qù Běijīng."},{"speaker":"李文","cn":"我和王老师都是北京人，北京非常漂亮。","pinyin":"Wǒ hé Wáng lǎoshī dōu shì Běijīng rén, Běijīng fēicháng piàoliang."}],"translation_vn":"Lý Văn: Mọi người đều muốn đi đâu vậy?\nAnnie: Năm ngoái mình và bạn trai đã đi Tây An, năm nay mình muốn đi Bắc Kinh.\nBạch Gia Nguyệt: Mấy năm trước mình đã đi Tây An, rất thú vị. Năm nay mình cũng muốn đi Bắc Kinh.\nLý Văn: Mình và cô Vương đều là người Bắc Kinh, Bắc Kinh rất đẹp.","audio_dialogue":"15-3.mp3","audio_vocab":"15-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一飞","cn":"你们的飞机到北京要几个小时？","pinyin":"Nǐmen de fēijī dào Běijīng yào jǐ gè xiǎoshí?"},{"speaker":"白家月","cn":"九个小时。","pinyin":"Jiǔ gè xiǎoshí."},{"speaker":"王一飞","cn":"我家人都在北京，星期天我姐姐也有时间，她可以去机场接你们，你们也可以住我家。","pinyin":"Wǒ jiārén dōu zài Běijīng, xīngqītiān wǒ jiějie yě yǒu shíjiān, tā kěyǐ qù jīchǎng jiē nǐmen, nǐmen yě kěyǐ zhù wǒ jiā."},{"speaker":"安妮","cn":"我们星期日早上八点到大兴机场，早不早？","pinyin":"Wǒmen xīngqīrì zǎoshang bā diǎn dào Dàxīng Jīchǎng, zǎo bu zǎo?"},{"speaker":"王一飞","cn":"不早。","pinyin":"Bù zǎo."},{"speaker":"白家月","cn":"谢谢老师！那我们和您姐姐在大兴机场见！","pinyin":"Xièxie lǎoshī! Nà wǒmen hé nín jiějie zài Dàxīng Jīchǎng jiàn!"}],"translation_vn":"Vương Nhất Phi: Máy bay của các em đến Bắc Kinh mất mấy tiếng?\nBạch Gia Nguyệt: Chín tiếng ạ.\nVương Nhất Phi: Người nhà cô đều ở Bắc Kinh, chủ nhật chị gái cô cũng rảnh, chị ấy có thể ra sân bay đón các em, các em cũng có thể ở nhà cô.\nAnnie: Chúng em đến sân bay Đại Hưng lúc tám giờ sáng chủ nhật, có sớm quá không ạ?\nVương Nhất Phi: Không sớm đâu.\nBạch Gia Nguyệt: Cảm ơn cô! Vậy chúng em sẽ gặp chị gái cô ở sân bay Đại Hưng nhé!","audio_dialogue":"15-5.mp3","audio_vocab":"15-6.mp3"}]}],"pos_table":[{"pos_cn":"名词","pos_vn":"Danh từ","abbr":"dt."},{"pos_cn":"动词","pos_vn":"Động từ","abbr":"dgt."},{"pos_cn":"形容词","pos_vn":"Tính từ","abbr":"tt."},{"pos_cn":"代词","pos_vn":"Đại từ","abbr":"đt."},{"pos_cn":"副词","pos_vn":"Phó từ","abbr":"phó."},{"pos_cn":"介词","pos_vn":"Giới từ","abbr":"giới."},{"pos_cn":"连词","pos_vn":"Liên từ","abbr":"liên."},{"pos_cn":"助词","pos_vn":"Trợ từ","abbr":"trợ."},{"pos_cn":"数词","pos_vn":"Từ chỉ số đếm","abbr":"số."},{"pos_cn":"量词","pos_vn":"Lượng từ","abbr":"lượng."},{"pos_cn":"数量词","pos_vn":"Từ chỉ số lượng","abbr":"sl."},{"pos_cn":"叹词","pos_vn":"Từ cảm thán","abbr":"ct."},{"pos_cn":"拟声词","pos_vn":"Từ tượng thanh","abbr":"tượng."},{"pos_cn":"能愿动词","pos_vn":"Động từ năng nguyện","abbr":"đtnn."},{"pos_cn":"前缀","pos_vn":"Tiền tố","abbr":"ttố."},{"pos_cn":"后缀","pos_vn":"Hậu tố","abbr":"htố."}]};